CREATE TABLE `child_nutrition` (
  `id` int(11) NOT NULL,
  `nutrition_stage` varchar(100) NOT NULL COMMENT 'مرحله تغذیه',
  `age_start_months` int(11) NOT NULL COMMENT 'سن شروع (ماه)',
  `age_end_months` int(11) NOT NULL COMMENT 'سن پایان (ماه)',
  `recommended_foods` text NOT NULL COMMENT 'مواد غذایی توصیه شده',
  `foods_to_avoid` text DEFAULT NULL COMMENT 'مواد غذایی ممنوعه',
  `meal_frequency` varchar(100) NOT NULL COMMENT 'تعداد وعده‌های غذایی در روز',
  `tips` text DEFAULT NULL COMMENT 'نکات مهم تغذیه‌ای',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

