INSERT INTO `child_nutrition` (`id`, `nutrition_stage`, `age_start_months`, `age_end_months`, `recommended_foods`, `foods_to_avoid`, `meal_frequency`, `tips`, `created_at`, `updated_at`) VALUES
(1, 'شیر انحصاری (شیر مادر یا شیر خشک)', 0, 5, 'شیر مادر (تغذیه انحصاری با شیر مادر) یا شیر خشک مناسب با سن کودک', '❌ هیچ ماده غذایی دیگری به جز شیر مجاز نیست (آب، چای، عسل، آب میوه، حریره و غیره)', '۸-۱۲ بار در روز (هر ۲-۳ ساعت یک بار)', '💡 شیر مادر بهترین تغذیه برای کودک است. تا ۶ ماهگی هیچ غذایی به غیر از شیر مادر یا شیر خشک به کودک ندهید. در صورت استفاده از شیر خشک، دقیقاً طبق دستورالعمل روی بسته آن را آماده کنید.', '2026-08-06 10:05:47', '2026-08-06 10:05:47'),
(2, 'شروع غذای کمکی (آغازین)', 6, 8, 'شیر مادر یا شیر خشک + پوره ساده و تک ماده‌ای: پوره سیب‌زمینی، کدو حلوایی، هویج، سیب، گلابی، موز، برنج پخته نرم، فرنی', '❌ نمک، شکر، عسل (خطر بوتولیسم)، شیر گاو، تخم‌مرغ (تا یک سالگی کامل)، ماهی (تا یک سالگی)، مرکبات، آجیل و مغزها', 'شیر مادر/شیر خشک + ۱-۲ وعده غذای کمکی در روز (شروع با ۱-۲ قاشق چای‌خوری)', '💡 غذاها را کاملاً پوره کنید و با شیر مادر یا آب رقیق کنید. هر غذا را به مدت ۳-۴ روز امتحان کنید تا از عدم حساسیت مطمئن شوید. با یک قاشق کوچک و نرم به کودک غذا دهید.', '2026-08-06 10:05:47', '2026-08-06 10:05:47'),
(3, 'تکامل تغذیه کمکی (نیمه جامد)', 9, 12, 'شیر مادر یا شیر خشک + غذاهای نرم‌تر با تکه‌های کوچک: انواع پوره‌ها با ترکیب مواد مختلف، کوفته ریز، تخم‌مرغ (زرده پخته شده)، پنیر، ماست، برنج نرم، ماکارانی نرم، گوشت چرخ‌کرده پخته', '❌ نمک، شکر، عسل، شیر گاو (به عنوان نوشیدنی اصلی)، غذاهای سرخ شده و چرب، غذاهای با تکه‌های بزرگ (خطر خفگی)', 'شیر مادر/شیر خشک + ۲-۳ وعده غذای کمکی در روز', '💡 کمکم کودک را به غذاهای خانواده عادت دهید (بدون نمک و شکر). بافت غذا را سفت‌تر کنید تا کودک جویدن را یاد بگیرد. برای تشویق به غذا خوردن، کودک را در کنار خانواده بنشانید.', '2026-08-06 10:05:47', '2026-08-06 10:05:47'),
(4, 'تغذیه کودک نوپا (جامد و خانواده)', 13, 24, 'غذاهای خانواده (بدون نمک و شکر اضافه): انواع خورش‌ها، کتلت، کوکو سبزیجات، آش‌های ساده، برنج با مرغ یا گوشت، ماکارانی، سبزیجات پخته شده، میوه‌های نرم، لبنیات (ماست، پنیر)', '❌ نمک و شکر اضافه، عسل (تا یک سالگی)، غذاهای بسیار چرب و سرخ شده، آجیل کامل (خطر خفگی)، سوسیس و کالباس، نوشابه و آبمیوه‌های صنعتی', '۳ وعده غذای اصلی + ۲ میان‌وعده در روز (به همراه شیر مادر یا شیر گاو)', '💡 کودک را تشویق کنید خودش با دست یا قاشق غذا بخورد. صبور باشید و غذای جدید را چند بار امتحان کنید. از غذا خوردن اجباری خودداری کنید. برنامه غذایی منظم داشته باشید.', '2026-08-06 10:05:47', '2026-08-06 10:05:47'),
(5, 'تغذیه پیش‌دبستانی', 25, 60, 'تمام گروه‌های غذایی شامل: نان و غلات (نان سبوس‌دار، برنج، ماکارانی)، میوه‌ها و سبزیجات تازه، لبنیات (شیر، ماست، پنیر)، پروتئین‌ها (گوشت، مرغ، ماهی، تخم‌مرغ، حبوبات)', '❌ فست‌فود، نوشابه، چیپس و اسنک‌های شور و چرب، آبمیوه‌های صنعتی با شکر افزوده، غذاهای بسیار شیرین', '۳ وعده غذای اصلی + ۲ میان‌وعده سالم در روز', '💡 کودکان را به خوردن انواع میوه‌ها و سبزیجات تشویق کنید. صبحانه کامل و سالم مصرف کنند. از خوردن تنقلات ناسالم بین وعده‌ها خودداری کنید. غذا را به شکل‌های جذاب و متنوع سرو کنید.', '2026-08-06 10:05:47', '2026-08-06 10:05:47');

