--
-- Table structure for table `child_supplements`
--

CREATE TABLE `child_supplements` (
  `id` int(11) NOT NULL,
  `supplement_name` varchar(100) NOT NULL COMMENT 'نام مکمل',
  `description` text NOT NULL COMMENT 'توضیحات مکمل',
  `benefits` text NOT NULL COMMENT 'فواید مکمل',
  `dosage` varchar(100) NOT NULL COMMENT 'دوز مصرفی',
  `age_start_months` int(11) NOT NULL COMMENT 'سن شروع مصرف (ماه)',
  `age_end_months` int(11) DEFAULT NULL COMMENT 'سن پایان مصرف (ماه) - NULL یعنی ادامه دارد',
  `daily_requirement` varchar(100) DEFAULT NULL COMMENT 'نیاز روزانه',
  `food_sources` text DEFAULT NULL COMMENT 'منابع غذایی',
  `precautions` text DEFAULT NULL COMMENT 'موارد احتیاط',
  `is_essential` tinyint(1) DEFAULT 1 COMMENT 'آیا ضروری است؟',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `child_supplements`
--

INSERT INTO `child_supplements` (`id`, `supplement_name`, `description`, `benefits`, `dosage`, `age_start_months`, `age_end_months`, `daily_requirement`, `food_sources`, `precautions`, `is_essential`, `created_at`, `updated_at`) VALUES
(1, 'قطره ویتامین A+D (قطره آ+د)', 'مکمل حاوی ویتامین‌های A و D که از بدو تولد برای تمام نوزادان تجویز می‌شود. این قطره برای رشد استخوان‌ها، سیستم ایمنی و بینایی ضروری است.', '🌟 تقویت سیستم ایمنی، رشد استخوان‌ها و دندان‌ها، سلامت بینایی، پیشگیری از راشیتیسم، کمک به جذب کلسیم', '۵ قطره در روز (معادل ۱۰۰۰ واحد ویتامین D)', 0, 24, 'ویتامین D: ۴۰۰ واحد بین‌المللی در روز', 'نور خورشید، ماهی‌های چرب، زرده تخم‌مرغ، شیر غنی‌شده', '⚠️ از مصرف بیش از حد (بیش از دوز تجویز شده) خودداری کنید. در صورت مصرف همزمان با مکمل‌های دیگر حاوی ویتامین A و D، با پزشک مشورت کنید.', 1, '2026-08-06 10:10:36', '2026-08-06 10:10:36'),
(2, 'قطره آهن (سولفات فروس)', 'مکمل آهن از ۶ ماهگی برای پیشگیری از کم‌خونی فقر آهن تجویز می‌شود. آهن برای تولید هموگلوبین و انتقال اکسیژن ضروری است.', '🌟 پیشگیری از کم‌خونی، افزایش انرژی، بهبود رشد مغز، تقویت سیستم ایمنی، بهبود اشتها', '۱۵ قطره (معادل ۱۵ میلی‌گرم آهن) در روز', 6, 24, '۱۰-۱۵ میلی‌گرم در روز', 'گوشت قرمز، جگر، اسفناج، حبوبات، غلات غنی‌شده با آهن', '⚠️ آهن ممکن است باعث یبوست و تیره شدن مدفوع شود. با معده خالی جذب بهتر دارد (اما اگر باعث تهوع شد، همراه با غذا مصرف شود). از مصرف همزمان با شیر یا لبنیات خودداری کنید (۲ ساعت فاصله).', 1, '2026-08-06 10:10:36', '2026-08-06 10:10:36'),
(3, 'قطره مولتی‌ویتامین (مولتی‌سان)', 'مکمل حاوی ویتامین‌های A، D، E، C و گروه B که برای تکمیل نیازهای تغذیه‌ای کودک تجویز می‌شود. برای کودکانی که دچار کم‌اشتهایی یا رشد ناکافی هستند مفید است.', '🌟 تامین نیازهای ویتامینی، افزایش اشتها، تقویت سیستم ایمنی، بهبود رشد، افزایش انرژی', '۵-۱۰ قطره در روز (بسته به سن و وزن کودک)', 6, 60, 'مختلف (بسته به ویتامین‌ها)', 'میوه‌ها، سبزیجات، غلات کامل، لبنیات، گوشت', '⚠️ از مصرف همزمان با مکمل‌های دیگر حاوی ویتامین‌ها خودداری کنید (خطر مصرف بیش از حد). قبل از مصرف با پزشک مشورت کنید.', 0, '2026-08-06 10:10:36', '2026-08-06 10:10:36'),
(4, 'پروبیوتیک کودکان', 'مکمل حاوی باکتری‌های مفید که به سلامت دستگاه گوارش کمک می‌کند. برای کودکانی که دچار کولیک، یبوست، اسهال یا نفخ هستند مفید است.', '🌟 بهبود عملکرد گوارش، کاهش کولیک و نفخ، تقویت سیستم ایمنی، پیشگیری از اسهال، بهبود جذب مواد مغذی', '۵-۱۰ قطره یا ۱-۲ ساشه در روز (بسته به برند)', 0, 60, '۵-۱۰ میلیارد CFU در روز', 'ماست پروبیوتیک، دوغ، کفیر', '⚠️ در صورت نقص ایمنی یا بیماری شدید، با پزشک مشورت کنید. از برندهای معتبر و با کیفیت استفاده کنید.', 0, '2026-08-06 10:10:36', '2026-08-06 10:10:36'),
(5, 'امگا-۳ کودکان (DHA)', 'مکمل حاوی اسیدهای چرب ضروری (DHA و EPA) که برای رشد مغز و چشم‌های کودک ضروری است. به ویژه در سال‌های اول زندگی اهمیت دارد.', '🌟 رشد مغز و سیستم عصبی، بهبود حافظه و یادگیری، سلامت چشم‌ها، بهبود خلق و خو، کاهش التهاب', '۲۰۰-۳۰۰ میلی‌گرم DHA در روز (بسته به سن)', 6, 60, '۲۰۰-۳۰۰ میلی‌گرم DHA در روز', 'ماهی‌های چرب (سالمون، ساردین)، گردو، تخم کتان', '⚠️ از برندهای معتبر و فاقد جیوه استفاده کنید. در صورت مصرف رقیق‌کننده‌های خون، با پزشک مشورت کنید.', 0, '2026-08-06 10:10:36', '2026-08-06 10:10:36'),
(6, 'کلسیم کودکان', 'مکمل کلسیم برای کودکانی که لبنیات کافی مصرف نمی‌کنند یا در معرض کمبود کلسیم هستند تجویز می‌شود. برای رشد استخوان‌ها و دندان‌ها ضروری است.', '🌟 رشد استخوان‌ها و دندان‌ها، عملکرد صحیح عضلات و اعصاب، انعقاد خون، تنظیم فشار خون', '۲۰۰-۵۰۰ میلی‌گرم در روز (بسته به سن و نیاز)', 12, 60, '۷۰۰-۱,۰۰۰ میلی‌گرم در روز', 'شیر و لبنیات، ماست، پنیر، سبزیجات برگ‌سبز، بادام، کنجد', '⚠️ از مصرف همزمان با آهن خودداری کنید (۲ ساعت فاصله). دوز بالا ممکن است باعث یبوست یا سنگ کلیه شود.', 0, '2026-08-06 10:10:36', '2026-08-06 10:10:36'),
(7, 'روی (زینک) کودکان', 'مکمل روی برای کودکانی که دچار کم‌اشتهایی، ریزش مو، اختلال رشد یا عفونت‌های مکرر هستند تجویز می‌شود. روی برای رشد و تقسیم سلولی ضروری است.', '🌟 تقویت سیستم ایمنی، بهبود اشتها، رشد و تقسیم سلولی، بهبود ترمیم زخم‌ها، سلامت پوست و مو', '۵-۱۰ میلی‌گرم در روز (بسته به سن و کمبود)', 12, 60, '۵-۱۰ میلی‌گرم در روز', 'گوشت قرمز، جگر، تخم‌مرغ، حبوبات، مغزها و دانه‌ها', '⚠️ مصرف طولانی مدت و دوز بالا باعث کمبود مس می‌شود. با معده خالی ممکن است باعث تهوع شود.', 0, '2026-08-06 10:10:36', '2026-08-06 10:10:36');

