--
-- Table structure for table `common_conditions`
--

CREATE TABLE `common_conditions` (
  `id` int(11) NOT NULL,
  `condition_name` varchar(150) NOT NULL,
  `description` text NOT NULL,
  `symptoms` text NOT NULL,
  `home_care` text NOT NULL,
  `when_to_see_doctor` text NOT NULL,
  `age_group` varchar(50) NOT NULL COMMENT 'گروه سنی درگیر',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `common_conditions`
--

INSERT INTO `common_conditions` (`id`, `condition_name`, `description`, `symptoms`, `home_care`, `when_to_see_doctor`, `age_group`, `created_at`, `updated_at`) VALUES
(1, 'تب در کودکان', 'تب یک واکنش طبیعی بدن به عفونت است. در کودکان، تب معمولاً به دلیل عفونت‌های ویروسی یا باکتریایی ایجاد می‌شود و معمولاً خطرناک نیست، اما نیاز به مراقبت دارد.', 'دمای بدن بالای ۳۸ درجه سانتی‌گراد، بی‌قراری یا خواب‌آلودگی، کاهش اشتها، بی‌حالی، گریه بدون دلیل، تشنج (در موارد شدید)', '💊 استامینوفن یا ایبوپروفن (طبق وزن کودک و با مشورت پزشک). لباس‌های کودک را کم کنید. حمام آب ولرم (نه سرد). مایعات کافی به کودک بدهید (شیر مادر، آب، ORS). دمای محیط را خنک نگه دارید.', '🆘 اگر تب بیش از ۳ روز طول کشید، کودک زیر ۳ ماه دارد، تب بالای ۴۰ درجه، همراه با تشنج، بی‌حالی شدید، مشکل تنفس، بثورات پوستی یا کاهش هوشیاری بود.', 'همه گروه‌های سنی', '2026-08-06 10:05:36', '2026-08-06 10:05:36'),
(2, 'اسهال در کودکان', 'اسهال دفع مدفوع آبکی و مکرر است که معمولاً به دلیل عفونت‌های ویروسی یا باکتریایی ایجاد می‌شود. خطر اصلی اسهال، کم‌آبی بدن است.', 'دفع مدفوع آبکی بیش از ۳ بار در روز، کاهش اشتها، شکم‌درد، حالت تهوع و استفراغ، کاهش ادرار (علائم کم‌آبی)، تب خفیف', '💧 مایعات کافی (ORS، آب، شیر مادر) به کودک بدهید. رژیم غذایی BRAT (موز، برنج، سیب، نان تست). از شیرینی‌جات و غذاهای چرب خودداری کنید. پروبیوتیک‌ها می‌توانند مفید باشند. دفعات تعویض پوشک را افزایش دهید.', '🆘 اگر اسهال بیش از ۲ روز طول کشید، کودک زیر ۶ ماه است، علائم کم‌آبی (خشکی دهان، کاهش ادرار، گریه بدون اشک)، خون در مدفوع، تب بالا یا کاهش هوشیاری وجود دارد.', 'همه گروه‌های سنی (به ویژه نوزادان و کودکان نوپا)', '2026-08-06 10:05:36', '2026-08-06 10:05:36'),
(3, 'یبوست در کودکان', 'یبوست زمانی اتفاق می‌افتد که کودک دفع مدفوع سخت و خشک دارد. این مشکل در کودکان شایع است و اغلب به دلیل رژیم غذایی کم فیبر یا کم‌آبی ایجاد می‌شود.', 'دفع کمتر از ۳ بار در هفته، مدفوع سخت و خشک، درد هنگام دفع، شکم‌درد، نفخ، بی‌اشتهایی، گریه هنگام دستشویی', '🥗 افزایش مصرف فیبر (میوه‌ها، سبزیجات، غلات کامل). مایعات کافی (آب، آبمیوه طبیعی). ورزش و فعالیت بدنی. ماساژ شکم. برای کودکان بزرگ‌تر، نشستن روی توالت بعد از هر وعده غذایی.', '🆘 اگر یبوست بیش از ۲ هفته طول کشید، همراه با استفراغ، کاهش وزن، خون در مدفوع، درد شدید شکم یا عدم دفع مدفوع به مدت ۵ روز بود.', 'همه گروه‌های سنی', '2026-08-06 10:05:36', '2026-08-06 10:05:36'),
(4, 'کولیک نوزادان (قولنج)', 'کولیک به گریه‌های طولانی و بی‌وقفه در نوزادان سالم گفته می‌شود که معمولاً در اواخر بعد از ظهر یا شب اتفاق می‌افتد. علت دقیق آن مشخص نیست اما معمولاً تا ۳-۴ ماهگی بهبود می‌یابد.', 'گریه‌های شدید و بی‌وقفه (بیش از ۳ ساعت در روز، حداقل ۳ روز در هفته)، جمع کردن پاها به سمت شکم، صورت قرمز، مشت کردن دست‌ها، نفخ و گاز شکم، معمولاً در عصرها و شب‌ها', '👶 نوزاد را بغل کنید و آرام تکان دهید. از صدای سفید (white noise) استفاده کنید. قنداق کردن نوزاد. ماساژ آرام شکم. استفاده از بطری ضد کولیک. برای شیردهی، از حباب هوا جلوگیری کنید. قطره سیمتیکون (با مشورت پزشک).', '🆘 اگر گریه با تب، استفراغ، اسهال، کاهش وزن، خون در مدفوع یا بی‌حالی همراه بود، یا نوزاد شیر نمی‌خورد.', '۰-۴ ماه', '2026-08-06 10:05:36', '2026-08-06 10:05:36'),
(5, 'عفونت گوش در کودکان (اوتیت مدیا)', 'عفونت گوش میانی در کودکان شایع است و اغلب پس از سرماخوردگی یا عفونت تنفسی رخ می‌دهد. این بیماری می‌تواند دردناک باشد و نیاز به درمان آنتی‌بیوتیکی دارد.', 'درد گوش (کودک بزرگ‌تر از درد شکایت می‌کند، کودک کوچک‌تر گوش خود را می‌کشد). تب، بی‌قراری، کاهش اشتها، مشکل در خواب، مایع از گوش خارج می‌شود (در موارد شدید)', '💊 مسکن (استامینوفن یا ایبوپروفن طبق وزن کودک). کمپرس گرم روی گوش. استراحت و مایعات کافی. سر کودک را در حالت نیمه‌نشسته نگه دارید.', '🆘 اگر درد و تب بیش از ۲ روز طول کشید، مایع از گوش خارج شد، کودک زیر ۶ ماه است، یا علائم شدید مانند سفتی گردن، سردرد شدید یا بی‌حالی داشت.', '۶ ماه تا ۵ سال', '2026-08-06 10:05:36', '2026-08-06 10:05:36'),
(6, 'بثورات پوشک (راش پوشک)', 'بثورات پوشک یک التهاب و قرمزی پوست در ناحیه پوشک است که به دلیل تماس طولانی با ادرار و مدفوع، حساسیت به پوشک یا عفونت قارچی ایجاد می‌شود.', 'قرمزی و التهاب پوست در ناحیه پوشک، پوست خشک و پوسته‌پوسته، تاول‌های کوچک، درد و بی‌قرایی هنگام تعویض پوشک، حساسیت پوست در لمس', '🧴 دفعات تعویض پوشک را افزایش دهید. پوست کودک را با آب ولرم تمیز کنید و خشک کنید (نمالید). از کرم‌های محافظ پوست (حاوی اکسید روی) استفاده کنید. اجازه دهید پوست کودک مدتی بدون پوشک بماند. از پوشک‌های نخی و تنفس‌پذیر استفاده کنید.', '🆘 اگر بثورات بعد از ۳ روز بهبود نیافت، همراه با تب، تاول‌های چرکی، قرمزی و تورم گسترده، یا کودک بی‌حال و بدحال بود.', 'نوزادان و کودکان نوپا', '2026-08-06 10:05:36', '2026-08-06 10:05:36'),
(7, 'حساسیت غذایی در کودکان', 'حساسیت غذایی یک واکنش سیستم ایمنی به برخی مواد غذایی است. شایع‌ترین مواد آلرژی‌زا: شیر گاو، تخم‌مرغ، بادام‌زمینی، آجیل، گندم، سویا و ماهی.', 'بثورات پوستی (کهیر، اگزما)، خارش، تورم لب‌ها، زبان یا صورت، تهوع و استفراغ، اسهال، مشکل تنفس (در موارد شدید)، شوک آنافیلاکسی (نادر اما خطرناک)', '🚫 مواد غذایی حساسیت‌زا را شناسایی و حذف کنید (با مشورت پزشک). آنتی‌هیستامین (با مشورت پزشک). اگر علائم خفیف است، از خوردن ماده غذایی خاص خودداری کنید. رژیم غذایی جایگزین تهیه کنید.', '🆘 اگر علائم شدید (مشکل تنفس، تورم گلو، افت فشار خون، کهیر گسترده) یا شوک آنافیلاکسی رخ داد، فوراً به اورژانس مراجعه کنید. اگر علائم خفیف اما مکرر بود، به پزشک متخصص آلرژی مراجعه کنید.', 'همه گروه‌های سنی', '2026-08-06 10:05:36', '2026-08-06 10:05:36'),
(8, 'خواب‌آلودگی و بی‌خوابی در کودکان', 'مشکلات خواب در کودکان شایع است و می‌تواند به دلیل عادات بد خواب، استرس، بیماری یا مشکلات رشدی ایجاد شود. کمبود خواب بر رشد و خلق کودک تأثیر می‌گذارد.', 'مشکل در به خواب رفتن، بیدار شدن‌های مکرر در شب، مقاومت در برابر خواب، خواب‌آلودگی در طول روز، بی‌قرایی و تحریک‌پذیری، کاهش تمرکز', '🌙 برنامه خواب منظم داشته باشید. محیط خواب آرام و تاریک ایجاد کنید. از صفحه‌نمایش‌ها (تلویزیون، تبلت، موبایل) حداقل ۱ ساعت قبل از خواب خودداری کنید. روتین آرام‌بخش قبل از خواب (حمام، کتاب خواندن). کودک را برای خوابیدن آرام کنید (نه با تکان دادن شدید).', '🆘 اگر مشکل خواب بیش از ۳ هفته طول کشید، همراه با علائم دیگر (تب، درد، مشکل تنفس) بود، یا کودک در طول روز بسیار بی‌حال و تحریک‌پذیر است.', 'همه گروه‌های سنی (به ویژه ۱-۵ سال)', '2026-08-06 10:05:36', '2026-08-06 10:05:36');

