--
-- Table structure for table `development_milestones`
--

CREATE TABLE `development_milestones` (
  `id` int(11) NOT NULL,
  `milestone_name` varchar(150) NOT NULL,
  `category` enum('motor','language','cognitive','social_emotional') NOT NULL,
  `description` text NOT NULL,
  `age_months_start` int(11) NOT NULL COMMENT 'سن شروع معمول (ماه)',
  `age_months_end` int(11) NOT NULL COMMENT 'سن پایان معمول (ماه)',
  `milestone_type` enum('gross_motor','fine_motor','speech','social','cognitive') NOT NULL,
  `warning_signs` text DEFAULT NULL COMMENT 'علائم هشدار برای تاخیر',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

