--
-- Table structure for table `faqs`
--

CREATE TABLE `faqs` (
  `id` int(11) NOT NULL,
  `category` int(10) UNSIGNED DEFAULT NULL,
  `question` text NOT NULL,
  `answer` text NOT NULL,
  `order` int(11) DEFAULT 0,
  `is_active` tinyint(1) DEFAULT 1,
  `view_count` int(11) DEFAULT 0,
  `helpful_count` int(11) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `faqs`
--

INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `order`, `is_active`, `view_count`, `helpful_count`, `created_at`, `updated_at`) VALUES
(1, NULL, 'مصرف چه مکمل‌هایی در بارداری ضروریه؟', 'اسیدفولیک، آهن و ویتامین D معمولاً توسط پزشک برای تمام دوران بارداری تجویز می‌شن؛ دوز دقیق باید توسط پزشک شما مشخص بشه.', 1, 1, 0, 0, '2026-08-09 15:21:20', '2026-08-09 15:21:20'),
(2, NULL, 'کودکم در چه سنی باید بشینه؟', 'اکثر کودکان بین ۴ تا ۷ ماهگی می‌تونن بدون کمک بشینن؛ اگه تا ۹ ماهگی این توانایی رو نداشت، بهتره با پزشک مشورت کنید.', 2, 1, 0, 0, '2026-08-09 15:21:20', '2026-08-09 15:21:20'),
(3, NULL, 'برنامه‌ی واکسیناسیون کودک از کجا شروع می‌شه؟', 'اولین واکسن‌ها معمولاً بلافاصله بعد از تولد تزریق می‌شن؛ برنامه‌ی کامل رو می‌تونید در بخش واکسیناسیون سایت ببینید.', 3, 1, 0, 0, '2026-08-09 15:21:20', '2026-08-09 15:21:20'),
(4, 24, 'آیا خوردن موز و مواد غذایی حاوی پتاسیم باعث پسردار شدن می‌شود؟', 'موز و سایر مواد غذایی سرشار از پتاسیم برای یک رژیم متعادل مفید هستند، اما مصرف آنها جنسیت جنین را تعیین نمیکند و در علم پزشکی نیز ثابت نشدهاند.', 4, 1, 0, 0, '2026-09-06 19:23:28', '2026-09-09 10:18:08'),
(5, 24, 'آیا سن مادر یا پدر روی پسردار شدن تاثیر دارد؟', 'سن والدین میتواند بر باروری و برخی پیامدهای بارداری اثر بگذارد؛ اما نمیتوان از سن مادر یا پدر برای افزایش شانس پسردار شدن استفاده کرد، زیرا تاثیر قطعی و علمی روی جنسیت جنین ندارد.', 5, 1, 0, 0, '2026-09-06 19:23:28', '2026-09-09 10:18:08'),
(6, 24, 'آیا نزدیکی در روز تخمک‌گذاری باعث پسردار شدن می‌شود؟', 'نزدیکی در روز تخمکگذاری میتواند احتمال بارداری را افزایش دهد، اما نمیتواند شانس پسردار شدن را بالا ببرد.', 6, 1, 0, 0, '2026-09-06 19:23:28', '2026-09-09 10:18:08'),
(7, 30, 'اگر چند ماه است برای بارداری اقدام کرده‌ام و نتیجه نگرفته‌ام، چه کار کنم؟', 'اگر زیر ۳۵ سال هستید و پس از ۱۲ ماه اقدام منظم و بدون پیشگیری بارداری نشدید باید ارزیابیهای تخصصی انجام دهید. چنانچه بالای ۳۵ سال سن دارید، پس از ۶ ماه بارداری ناموفق باید به پزشک مراجعه کنید. در صورت قاعدگی نامنظم، سابقه بیماری یا جراحی لگنی، زودتر مراجعه کنید.', 7, 1, 0, 0, '2026-09-06 19:23:28', '2026-09-09 10:18:08'),
(8, 30, 'اگر در زمان تخمک‌گذاری روزها رابطه داشته باشم، باز هم احتمال بارداری وجود دارد؟', 'بله، رابطه در روزهای نزدیک تخمکگذاری نیز میتواند به بارداری منجر شود. ساعت رابطه مهم نیست، بلکه قرارگرفتن در پنجره باروری برای افزایش شانس لقاح اهمیت دارد.', 8, 1, 0, 0, '2026-09-06 19:23:28', '2026-09-09 10:18:08'),
(9, 30, 'آیا ساعت رابطه از زمان تخمک‌گذاری مهم‌تر است؟', 'خیر، زمان تخمکگذاری بسیار مهمتر است. رابطه در پنجره باروری شانس بارداری را افزایش میدهد، اما صبح یا شببودن تاثیر اثباتشدهای ندارد.', 9, 1, 0, 0, '2026-09-06 19:23:28', '2026-09-09 10:18:08'),
(10, 30, 'اگر دو فولیکول ۱۸ یا ۲۰ میلی‌متری داشته باشم، حتما دوقلو باردار می‌شوم؟', 'خیر، داشتن دو فولیکول ۱۸ یا ۲۰ میلیمتری شانس دوقلوزایی را بیشتر میکند، اما به معنای بارداری قطعی دوقلو نیست.', 10, 1, 0, 0, '2026-09-06 19:23:28', '2026-09-09 10:18:08'),
(11, 30, 'بهترین اندازه فولیکول قبل از تزریق آمپول HCG چقدر است؟', 'فولیکول غالب با قطر حدود ۱۸ تا ۲۰ میلیمتر برای تزریق HCG مناسب است. اما همچنان نظر پزشک تعیینکننده است.', 11, 1, 0, 0, '2026-09-06 19:23:28', '2026-09-09 10:18:08'),
(12, 30, 'با یک فولیکول بالغ هم ممکن است دوقلو باردار شوم؟', 'بله، اگر یک تخمک بارورشده به دو جنین تقسیم شود، دوقلوهای همسان شکل میگیرند. اما این اتفاق نسبتا نادر است.', 12, 1, 0, 0, '2026-09-06 19:23:28', '2026-09-09 10:18:08'),
(13, 30, 'اگر در خانواده‌ام دوقلو وجود داشته باشد، احتمال دوقلوزایی من بیشتر است؟', 'بله، بهویژه اگر دوقلوهای ناهمسان در بستگان نزدیک مادری وجود داشته باشند، احتمال دوقلوزایی شما افزایش مییابد. اما این اتفاق قطعی نیست.', 13, 1, 0, 0, '2026-09-06 19:23:28', '2026-09-09 10:18:08'),
(14, 30, 'دوقلوزایی را از مادرم به ارث می‌برم یا از پدرم؟', 'زمینه ژنتیکی دوقلوزایی ناهمسان میتواند از مادر یا پدر منتقل شود. اما فقط در زنان و از طریق بیشتخمکگذاری عملا اثرش آشکار میشود.', 14, 1, 0, 0, '2026-09-06 19:23:28', '2026-09-09 10:18:08'),
(15, 30, 'اگر همسرم دوقلو باشد، احتمال دوقلوزایی فرزندم بیشتر می‌شود؟', 'اگر همسرتان دوقلوی ناهمسان داشته باشد، احتمال دوقلوزایی ممکن است به دخترتان منتقل شده و بعدها روی او اثر بگذارد.', 15, 1, 0, 0, '2026-09-06 19:23:28', '2026-09-09 10:18:08'),
(16, 30, 'اگر اولین بارداری‌ام دوقلو باشد، احتمال دوقلوزایی در بارداری بعدی هم وجود دارد؟', 'بله، احتمال تکرار دوقلوزایی در بارداری بعدی بیشتر میشود، بهویژه اگر دوقلوها ناهمسان بوده باشند.', 16, 1, 0, 0, '2026-09-06 19:23:28', '2026-09-09 10:18:08'),
(17, 30, 'کدام روش شانس بارداری بیشتری دارد؟', 'به طور کلی IVF شانس بارداری بالاتری نسبت به IUI دارد؛ چون لقاح در محیط آزمایشگاه انجام میشود و امکان انتخاب جنین سالم وجود دارد. در حالی که IUI بیشتر به شرایط طبیعی بدن وابسته است و درصد موفقیت پایینتری دارد.', 17, 1, 0, 0, '2026-09-06 19:23:28', '2026-09-09 10:18:08'),
(18, 30, 'احتمال دوقلوزایی در IUI بیشتر است یا IVF؟', 'احتمال دوقلوزایی در IUI معمولا بیشتر است، بهخصوص زمانی که از داروهای تحریک تخمکگذاری استفاده شده و چند تخمک همزمان آزاد میشوند. در IVF با انتقال تک جنین، این احتمال کمتر و کنترلشدهتر است.', 18, 1, 0, 0, '2026-09-06 19:23:28', '2026-09-09 10:18:08'),
(19, 30, 'آیا می‌توان بعد از شکست IUI سراغ IVF رفت؟', 'بله، در صورت شکست IUI میتوان سراغ IVF رفت. معمولا پزشکان پس از چند سیکل ناموفق IUI، روش IVF را بهعنوان مرحله بعدی درمان پیشنهاد میکنند تا شانس بارداری افزایش پیدا کند.', 19, 1, 0, 0, '2026-09-06 19:23:28', '2026-09-09 10:18:08'),
(20, 30, 'چه تفاوتی بین پریود نشدن به‌خاطر بارداری و به‌خاطر پروژسترون وجود دارد؟', 'در بارداری، پریود به دلیل افزایش هورمونهای بارداری قطع میشود. اما در تزریق پروژسترون، تاخیر یا قطع پریود ناشی از تغییرات موقت هورمونی دارو است. در این شرایط انجام تست بارداری توصیه میشود.', 20, 1, 0, 0, '2026-09-06 19:23:28', '2026-09-09 10:18:08'),
(21, 30, 'آیا دوز آمپول پروژسترون در پریود نشدن تاثیر دارد؟', 'بله، دوز و تعداد دفعات تزریق میتواند مدت تاخیر پریود را بیشتر یا کمتر کند.', 21, 1, 0, 0, '2026-09-06 19:23:28', '2026-09-09 10:18:08'),
(22, 30, 'بعد از چند روز تاخیر باید تست بارداری بدهم؟', 'معمولا از روز اول تاخیر میتوان تست داد، اما نتیجه دقیقتر یک هفته بعد از تاخیر به دست میآید.', 22, 1, 0, 0, '2026-09-06 19:23:28', '2026-09-09 10:18:08'),
(23, 30, 'آیا رنگ زردی پوست یا تهوع صبحگاهی نشان‌دهنده جنسیت است؟', 'خیر، این موضوع پایه علمی ندارد. تهوع صبحگاهی یا تغییرات پوستی بیشتر به نوسانات هورمونی بارداری و تغییرات متابولیکی بدن مربوط است و ربطی به جنسیت جنین ندارد.', 23, 1, 0, 0, '2026-09-06 19:23:28', '2026-09-09 10:18:08'),
(24, 30, 'اگر نتیجه سونوگرافی جنسیت دختر یا پسر را نشان دهد، چقدر دقت دارد؟', 'دقت سونوگرافی در تشخیص جنسیت معمولاً بین ۸۰ تا ۹۵ درصد است، به شرطی که در هفته ۱۶ تا ۲۰ و توسط پزشک متخصص انجام شود. عواملی مثل وضعیت قرارگیری جنین میتوانند دقت را کاهش دهند.', 24, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(25, 30, 'آیا شکم رو به پایین نشانه جنین پسر است و رو به بالا جنین دختر؟ آیا این علمی است؟', 'خیر، این باور پایه علمی ندارد. فرم شکم در بارداری به عواملی مثل موقعیت جنین، ماهیچههای شکم، و میزان مایع آمنیوتیک بستگی دارد و به جنسیت ربطی ندارد.', 25, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(26, 30, 'راهی برای تعیین جنسیت در ماه اول بارداری وجود دارد؟', 'خیر. جنسیت جنین از لحظه لقاح مشخص است، اما تشخیص قطعی آن معمولاً از هفته ۱۲ به بعد با سونوگرافی یا آزمایشهای ژنتیکی مثل NIPT امکانپذیر است.', 26, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(27, 30, 'تهوع صبحگاهی از علائم بارداری دختر است؟', 'از شایعترین علائم بارداری دختر در باور عمومی، مقدار تهوع صبحگاهی است. عدهای افزایش تهوع را از ریزترین علائم بارداری دختر در اوایل بارداری دانستهاند. سوال این است که آیا این نشانه علمی است؟ خیر. تهوع صبحگاهی به تغییرات هورمونی دوران بارداری و پایین بودن قند خون در این دوران مرتبط است. بنابراین، تهوع بارداری را نمیتوان از علائم علمی بارداری دختر دانست.', 27, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(28, 30, 'معده درد در بارداری نشانه دختر است یا پسر؟', 'بعضی معتقدند تغییرات هورمونی شدید منجر به بروز مشکلات گوارشی بیشتر، از جمله سوزش معده میشود. از آنجایی که تغییرات هورمونی در جنسیت جنین دختر بیشتر است، سوزش و درد معده میتواند از نشانههای بارداری دختر باشد. از نظر علمی، درد و سوزش معده ربطی به جنسیت جنین ندارد و بیشتر به عواملی مانند خوراک مادر یا شکل خوابیدن او بستگی دارد.', 28, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(29, 30, 'بالا بودن سطح استرس از علائم بارداری دختر است؟', 'برخی معتقدند که زیاد بودن استرس مادر پیش از بارداری، سبب دختر شدن جنین او میشود. پژوهشی در سال 2012 نشان داد کسانی که هورمون کورتیزول (هورمون استرس) در بدنشان بیشتر باشد، احتمال دختردار شدن آنها بیشتر است. بابد توجه داشت که این موضوع فقط احتمال آماری است و نمیتوان آن را امری قطعی و صددرصدی دانست. ', 29, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(30, 30, 'سردرد از علائم بارداری پسر است یا دختر؟', 'به نظر میرسد که سردرد یکی از شایعترین علائم بارداری پسر  است و این زنان بیشتر از زنانی که جنین دختر دارند دچار سردرد میشوند. سردرد سه ماه دوم بارداری اغلب نتیجه تغییرات هورمونی است.', 30, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(31, 30, 'آیا استفاده از شیاف پروژسترون روی جنین عوارض ندارد؟', 'خیر، اگر طبق دستور پزشک باشد، بیخطر است و معمولاً برای حمایت بارداری تجویز میشود.', 31, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(32, 30, 'آیا در صورت استفاده از شیاف پروژسترون باید استراحت کرد و نزدیکی نداشت؟', 'بستگی به علت تجویز دارد؛ اگر برای تهدید به سقط است، استراحت و اجتناب از نزدیکی توصیه میشود.', 32, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(33, 30, 'آیا می‌توانم در ماه ششم بارداری از شیاف پروژسترون استفاده کنم؟ تا ماه چند استفاده از این شیاف مجاز است؟', 'بله، در صورت نیاز تا پایان بارداری قابل استفاده است، اما تنها با تجویز پزشک.', 33, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(34, 30, 'بعد از استفاده از شیاف پروژسترون خارش مقعد دارم، قطع کنم؟', 'ممکن است به ماده شیاف حساسیت داشته باشید. مصرف را تحت نظر ماما یا پزشک متوقف کرده و با درمانگرتان مشورت کنید.', 34, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(35, 30, 'شیاف پروژسترون را واژینال گذاشتم اما باید مقعدی می‌گذاشتم؛ خطری دارد؟', 'خیر، روش واژینال هم معمولاً بیخطر است. پزشک روش صحیح را مشخص میکند.', 35, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(36, 30, 'بعد از گذاشتن شیاف پروژسترون حالت تهوع دارم و نمی‌توانم غذا بخورم؛ علت چیست؟', 'ممکن است حساسیت به دارو باشد. با پزشک مشورت کنید؛ تغییر روش مصرف یا دوز ممکن است کمک کند.', 36, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(37, 30, 'درد لگن بعد از زایمانم برطرف می‌شود؟', 'در بیشتر مادران، درد لگن پس از زایمان بهتدریج کاهش مییابد. البته گاهی ممکن است چند هفته یا ماه ادامه پیدا کند.', 37, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(38, 30, 'چرا در بارداری لگن سمت چپم درد می‌کند؟', 'درد لگن سمت چپ در بارداری ممکن است در اثر فشار عضلات، مفاصل، سیاتیک یا PGP رخ دهد.', 38, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(39, 30, 'آیا می‌توانم برای درد لگن در بارداری از کمربند بارداری استفاده کنم؟', 'بله، در برخی موارد کمربند حمایتی لگن درد را کاهش میدهد. اما انتخاب نوع مناسب و مدت استفاده باید با نظر پزشک یا فیزیوتراپیست باشد.', 39, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(40, 30, 'آیا در زمان عفونت قارچی واژن در بارداری می‌توانم رابطه جنسی داشته باشم؟', 'رابطه جنسی در طول ابتلا به عفونت قارچی واژن در بارداری ممنوع نیست، اما ممکن است درد و سوزش را تشدید کند. بهتر است تا بهبود علائم و نظر پزشک صبر کنید.', 40, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(41, 30, 'آیا عفونت قارچی در بارداری برای جنینم خطرناک است؟', 'عفونت قارچی معمولا برای جنین خطرناک نیست، اما تشخیص و درمان مناسب در بارداری اهمیت دارد.', 41, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(42, 30, 'آیا عفونت قارچی می‌تواند باعث سقط جنینم یا زایمان زودرس شود؟', 'معمولا نه، شواهد فعلی ارتباط مشخصی میان عفونت قارچی واژن و سقط یا زایمان زودرس نشان نمیدهند، اما تشخیص و درمان این عفونت مهم است.', 42, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(43, 30, 'از کجا بفهمم ترشحاتم طبیعی است یا عفونت قارچی دارم؟', 'ترشحات طبیعی بارداری معمولا رقیق، شفاف یا سفید شیری و بدون خارش هستند. در حالیکه ترشحات قارچی اغلب غلیظ، سفید و همراه خارش و سوزش و تحریک واژن هستند.', 43, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(44, 30, 'اگر مایع آمنیوتیکم کم باشد، روزانه چقدر آب بنوشم؟', 'میزان آب مصرفی مقدار ثابتی ندارد و پزشک با توجه به شرایط شما، افزایش مصرف آب و مایعات را توصیه میکند.', 44, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(45, 30, 'آیا آب نارگیل برای افزایش مایع آمنیوتیک مفید است؟', 'شواهد کافی درباره اثر مستقیم آب نارگیل بر افزایش مایع آمنیوتیک وجود ندارد و همچنان مصرف آب برای هیدراتاسیون انتخاب اصلی خواهد بود.', 45, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(46, 30, 'برای افزایش مایع آمنیوتیک از چه غذاهایی پرهیز کنم؟', 'غذای خاصی برای پرهیز با هدف افزایش مایع آمنیوتیک وجود ندارد. آب کافی بنوشید، تغذیه متعادل داشته باشید و کافئین را محدود کنید.', 46, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(47, 30, 'آیا خط شکم در بارداری برای من یا جنینم خطرناک است؟', 'خیر. لینا نیگرا معمولا یک تغییر طبیعی رنگدانههای پوست در بارداری است و به تنهایی برای مادر یا جنین خطری ندارد.', 47, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(48, 30, 'چرا خط شکم بعضی زنان باردار بالاتر از ناف ادامه پیدا می‌کند؟', 'لینا نیگرا در بعضی افراد به دلیل تیره شدن بیشتر لاینئا آلبا در تمام طول خط میانی شکم، از ناف عبور کرده و به سمت بالای شکم ادامه پیدا میکند. این تفاوت طبیعی است و مشکلی ایجاد نمیکند.', 48, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(49, 30, 'چرا خط شکمم نسبت به قبل پررنگ‌تر شده است؟', 'افزایش تغییرات هورمونی در بارداری میتواند تولید ملانین را بیشتر کند و باعث شود خط شکم نسبت به قبل، تیرهتر و واضحتر دیده شود.', 49, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(50, 30, 'تفاوت خونریزی لانه گزینی با خونریزی پریودی چیست؟', 'مهم‌ترین فرق خونریزی پریود و لانه گزینی شدت و نوع خونریزی است. خونریزی لانه‌گزینی معمولا به صورت سبک، کوتاه‌مدت و با رنگ صورتی یا قهوه‌ای ظاهر می‌شود، در حالی که پریود شدیدتر، پیوسته و قرمز روشن تا تیره است.', 50, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(51, 30, 'آیا خونریزی لانه‌گزینی همیشه نشانه بارداری است؟', 'خیر، خونریزی سبک می‌تواند گاهی ناشی از تغییرات هورمونی یا تحریک دهانه رحم باشد، اما اگر با علائم دیگر بارداری همراه باشد، نیاز به بررسی دارد.', 51, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(52, 30, 'چه زمانی باید تست بارداری انجام داد؟', 'بهترین زمان برای تست بارداری، چند روز پس از مشاهده خونریزی لانه‌گزینی یا زمانی است که پریود به تاخیر افتاده باشد تا نتیجه دقیق باشد.', 52, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(53, 30, 'آیا خونریزی لانه‌گزینی خطرناک است؟', 'اکثر اوقات خونریزی لانه‌گزینی طبیعی و بی‌خطر است، اما اگر خونریزی شدید با درد شدید یا علائم غیرعادی همراه باشد، باید به پزشک مراجعه کنید.', 53, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(54, 30, 'آیا دردهای شکمی در لانه‌گزینی نیاز به دارو دارند؟', 'معمولا درد سبک و کوتاه‌مدت لانه‌گزینی نیاز به درمان ندارد و با استراحت و مراقبت ساده کنترل می‌شود، مگر اینکه شدت آن غیرقابل تحمل باشد.', 54, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(55, 30, 'آیا رنگ خون همیشه تفاوت بین پریود و لانه‌گزینی را نشان می‌دهد؟', 'رنگ خون یک شاخص مهم است اما همیشه قطعی نیست؛ باید سایر علائم مانند شدت جریان، مدت زمان خونریزی و درد را نیز در نظر گرفت.', 55, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(56, 30, 'تهوع صبحگاهی در بارداری نشانه چیست؟', 'بسیاری از زنان، تهوع صبحگاهی را نشانهای از بارداری میدانند.', 56, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(57, 30, 'برای تهوع صبحگاهی بارداری چه کنیم؟', 'تغییر سبک زندگی و تغذیه تاثیر بسیار زیادی در کاهش و کنترل تهوع صبحگاهی در بارداری دارد؛ پیشنهاد میشود توصیههای ارائه شده در این مقاله را اجرا کنید.', 57, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(58, 30, 'حالت تهوع بارداری از کی شروع میشه؟', 'حالت تهوع بارداری از اوایل هفته ششم شروع میشود؛ اما برخی از زنان ممکن است از هفته 9 بارداری علائم تهوع را تجربه کنند.', 58, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(59, 30, 'آیا طب سوزنی برای تهوع صبحگاهی بارداری خوب است؟', 'طب سنتی روشی قدیمی برای درمان بسیاری از مشکلات سلامتی است؛ اما قبل از هر اقدامی باید با پزشک متخصص زنان مشورت کنید.', 59, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(60, 30, 'تپش قلب در سه ماهه سوم بارداری طبیعی است؟', 'تپش قلب خفیف گاهی طبیعی است؛ اما اگر با تنگی نفس، درد قفسه سینه، غش یا سرگیجه همراه شد، پیگیری کنید.', 60, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(61, 30, 'لکه بینی در سه ماهه سوم بارداری نشانه چیست؟', 'گاهی ممکن است بهدلیل تغییرات دهانه رحم، معاینه داخلی یا نزدیک شدن به زایمان رخ دهد؛ اما میتواند نشانه مشکلات مهمتری مثل شروع زایمان زودرس، مشکل جفت یا پارگی کیسه آب هم باشد. اگر لکهبینی با درد شکم، انقباضات منظم، کاهش حرکات جنین، نشت مایع، سرگیجه یا خونریزی بیشتر همراه شد، مادر باید فوری با پزشک تماس بگیرد.', 61, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(62, 30, 'ترشحات سه ماهه سوم بارداری به چه صورت است؟ چه زمانی خطرناک است؟', 'ترشحات سفید یا شیری، رقیق و بدون بوی بد در سهماهه سوم معمولا طبیعی است. ترشح بدبو، سبز، زرد، خاکستری، خونی، همراه خارش و سوزش یا نشت مایع شفاف و آبکی میتواند خطرناک باشد و نیاز به بررسی فوری پزشکی دارد.', 62, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(63, 30, 'بهترین حالت خوابیدن در سه‌ماهه سوم بارداری چیست؟', 'خوابیدن به پهلو، مخصوصا پهلوی چپ، معمولا راحتتر است و میتواند فشار روی کمر، لگن و گردش خون را کمتر کند.', 63, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(64, 30, 'سه ماهه دوم بارداری از هفته چندم شروع می‌شود؟', 'سهماهه دوم بارداری از هفته ۱۴ شروع میشود و تا پایان هفته ۲۷ ادامه دارد.', 64, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(65, 30, 'ترشحات سه ماهه دوم بارداری طبیعی است؟', 'بله، ترشحات سفید یا شیری و بدون بو طبیعی است؛ اما ترشح بدبو، رنگی، خونی یا همراه خارش نیاز به بررسی دارد.', 65, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(66, 30, 'غذاهای ممنوعه در سه ماهه دوم بارداری چه غذایی است؟', 'غذاهای خام یا نیمپز، لبنیات غیرپاستوریزه، ماهی پرجیوه، غذاهای سرد مانده و کافئین زیاد توصیه نمیشود.', 66, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(67, 30, 'آیا مسافرت در سه‌ماهه دوم بارداری مجاز است؟', 'اگر بارداری کمخطر باشد و پزشک محدودیتی نداده باشد، مسافرت معمولا امکانپذیر است. اما برای سفرهای طولانی بهتر است با مشورت پزشک شود.', 67, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(68, 30, 'سه ماهه اول بارداری تا هفته چندم است؟', 'سهماهه اول بارداری از هفته ۱ شروع میشود و تا پایان هفته ۱۳ ادامه دارد.', 68, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(69, 30, 'بهترین صبحانه در سه ماهه اول بارداری چیست؟', 'بهترین صبحانه شامل نان سبوسدار، تخممرغ کاملا پخته، لبنیات پاستوریزه، میوه، مغزها و آب کافی است.', 69, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(70, 30, 'آیا در سه ماهه اول بارداری نباید رابطه داشت؟', 'در بارداری کمخطر، رابطه معمولا ممنوع نیست. اما در صورت خونریزی، درد، سابقه سقط یا بارداری پرخطر با پزشک مشورت کنید.', 70, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(71, 30, 'آیا لکه‌بینی خفیف در اوایل بارداری خطرناک است؟', 'لکهبینی خفیف گاهی دیده میشود؛ اما اگر ادامهدار، شدید یا همراه با درد باشد، نیاز به بررسی پزشکی دارد.', 71, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(72, 30, 'در سه‌ماهه اول بارداری چه مکملی مهم‌تر است؟', 'اسیدفولیک یکی از مهمترین مکملهای این دوره است و باید طبق نظر پزشک مصرف شود.', 72, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(73, 30, 'آیا در سه‌ماهه اول بارداری می‌توان مسافرت رفت؟', 'اگر بارداری کمخطر باشد و پزشک محدودیتی نداده باشد، معمولا سفر کوتاه و ایمن مشکلی ندارد.', 73, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(74, 30, 'در سه‌ماهه اول بارداری چه غذاهایی بهتر است مصرف شوند؟', 'سبزیجات، میوهها، غلات کامل، پروتئین کاملا پخته، لبنیات پاستوریزه، مغزها و آب کافی انتخابهای مناسبی هستند.', 74, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(75, 30, 'ممنوعات سه ماهه اول بارداری چیست؟', 'ممنوعات سه ماهه اول بارداری شامل مصرف الکل، سیگار، مواد مخدر، داروی خودسرانه، غذای خام، لبنیات غیرپاستوریزه، کافئین زیاد و ماهی پرجیوه است.', 75, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(76, 30, 'اولین سونوگرافی بارداری هفته چندم برم؟', 'بهترین زمان انجام اولین سونوگرافی بارداری بین هفته ۶ تا ۸ بارداری است.', 76, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(77, 30, 'برای اولین سونوگرافی بارداری باید مثانه پر باشد؟', 'اگر سونوگرافی شکمی انجام شود، لازم است مثانه نسبتا پر باشد. در سونوگرافی واژینال نیازی به پر بودن مثانه نیست.', 77, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(78, 30, 'اولین سونوگرافی بارداری باید ناشتا باشد؟', 'نیازی به ناشتا بودن وجود ندارد، مگر اینکه پزشک توصیه خاصی کرده باشد.', 78, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(79, 30, 'هزینه اولین سونوگرافی بارداری چقدر است؟', 'هزینه سونوگرافی به مرکز تصویربرداری، پوشش بیمه، روش انجام (واژینال یا شکمی) و شهر شما بستگی دارد. در مراکز خصوصی هزینه آن ممکن است بیشتر از مراکز دولتی باشد، اما بهتر است قبل از انجام سونوگرافی از مرکز مورد نظر درباره هزینه دقیق بپرسید.', 79, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(80, 30, 'اگر در اولین سونوگرافی ضربان قلب دیده نشود یعنی مشکلی وجود دارد؟', 'خیر، اگر سونوگرافی خیلی زود مثلا قبل از هفته ۶ انجام شده باشد، ممکن است هنوز ضربان قلب قابل مشاهده نباشد. در این شرایط معمولا پزشک تکرار سونوگرافی را بعد از چند روز توصیه می‌کند.', 80, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(81, 30, 'بهترین زمان خرید سیسمونی چه ماهی از بارداری است؟', 'بهترین زمان خرید سیسمونی ماه هفتم بارداری است، چون جنسیت نوزاد مشخص شده، مادر انرژی کافی دارد و زمان کافی برای آمادهسازی وسایل وجود دارد.', 81, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(82, 30, 'سیسمونی دختر و پسر چه تفاوتی دارد؟', 'تفاوت سیسمونی دختر و پسر بیشتر در رنگ، طرح و جزئیات ظاهری وسایل است؛ وسایل اصلی و کاربردی تقریباً یکساناند. سیسمونی دختر معمولاً با رنگهای صورتی، یاسی و طرحهای گلدار تهیه میشود، در حالیکه سیسمونی پسر بیشتر آبی، طوسی یا سبز و با طرحهای حیوانات یا ماشین است.', 82, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(83, 30, 'هزینه سیسمونی نوزاد حدوداً چقدر است؟', 'هزینه سیسمونی نوزاد بسته به کیفیت وسایل بین حدود ۵ تا ۲۰ میلیون تومان متغیر است.', 83, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(84, 30, 'چه وسایلی از سیسمونی را نباید قبل از تولد نوزاد بخریم؟', 'وسایلی مانند شیشهشیر، پستانک، پوشک با سایز مشخص و کفش نوزاد را بهتر است بعد از تولد و با توجه به نیاز و سایز واقعی نوزاد تهیه کنید.', 84, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(85, 30, 'آیا دیابت بارداریم باعث افزایش مایع آمنیوتیک می‌شود؟', 'بله، دیابت بارداری بهویژه اگر قند خون خوب کنترل نشود، میتواند با افزایش ادرار جنین، مقدار مایع آمنیوتیک را بیشتر کند.', 85, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(86, 30, 'اگر AFI بالا باشد، حتما نیاز به درمان دارم؟', 'نه، AFI بالا نیازمند درمان نیست. درمان به شدت افزایش مایع، علائم، علت زمینهای و وضعیت جنین بستگی دارد.', 86, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(87, 30, 'آیا افزایش مایع آمنیوتیک باعث زایمان زودرس می‌شود؟', 'بله، مایع آمنیوتیک افزایش یافته میتواند احتمال زایمان زودرس را بیشتر کند، اما همیشه باعث آن نمیشود.', 87, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(88, 30, 'بهترین ماه بارداری برای مراجعه به ارتودنتیست کدام است؟', 'معمولا سهماهه دوم بارداری، بهدلیل کاهش تهوع و پایداری بیشتر شرایط جسمی، زمان مناسبتری برای شروع یا انجام اقدامات غیرضروری ارتودنسی است.', 88, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(89, 30, 'آیا تعویض سیم ارتودنسی در بارداری مجاز است؟', 'بله. اگر درمان از قبل شروع شده باشد، تعویض سیم و تنظیم براکتها معمولا بدون مشکل و طبق برنامه انجام میشود.', 89, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(90, 30, 'چه داروهای مسکنی هنگام ارتودنسی در بارداری مجاز هستند؟', 'مصرف هر نوع مسکن باید فقط با تایید پزشک زنان انجام شود و از مصرف خودسرانه داروها باید خودداری کرد.', 90, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(91, 30, 'آیا سیاه‌دانه روی جنین تاثیر منفی می‌گذارد؟', 'اثر منفی سیاه‌دانه روی جنین قطعی نیست، اما به‌دلیل نبود شواهد کافی، مصرف زیاد یا دارویی آن توصیه نمی‌شود.', 91, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(92, 30, 'ترکیب سیاه دانه و عسل برای بارداری مفید است؟', 'مصرف ترکیب سیاه‌دانه و عسل در بارداری توصیه نمی‌شود؛ چون ایمنی سیاه‌دانه هنوز از نظر علمی کامل ثابت نشده است.', 92, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(93, 30, 'مصرف شیاف سیاه دانه در بارداری توصیه می‌شود؟', 'خیر، مصرف شیاف سیاه دانه در بارداری توصیه نمی‌شود و فقط باید با تجویز پزشک انجام شود.', 93, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(94, 30, 'فرق مسمومیت غذایی با ویروس معده در بارداری چیست؟', 'مسمومیت غذایی معمولا بعد از خوردن غذای آلوده شروع می‌شود؛ اما ویروس معده بیشتر از تماس با فرد یا سطح آلوده منتقل می‌شود. علائمشان شبیه به هم است و هر دو در بارداری باید جدی گرفته شوند.', 94, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(95, 30, 'آیا مسمومیت غذایی باعث سقط جنین می‌شود؟', 'در بیشتر موارد نه. اما بعضی عفونت‌های غذایی، به‌ویژه لیستریا می‌توانند خطر سقط، زایمان زودرس یا مرده‌زایی را افزایش دهند.', 95, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(96, 30, 'آیا مسمومیت غذایی می‌تواند باعث زایمان زودرس شود؟', 'بله، برخی عفونت‌های غذایی مثل لیستریا ممکن است خطر زایمان زودرس را افزایش دهند.', 96, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(97, 30, 'برای مسمومیت غذایی در بارداری چه زمانی باید به پزشک مراجعه کرد؟', 'اگر با تب، اسهال خونی، استفراغ مداوم، کم‌آبی، درد شدید شکم یا کاهش حرکات جنین مواجه شدید، باید سریع به پزشک مراجعه کنید.', 97, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(98, 30, 'آیا مصرف داروی ضداسهال در بارداری مجاز است؟', 'مصرف خودسرانه داروی ضداسهال در بارداری مجاز نیست. چون بعضی داروها برای این دوره مناسب نیستند و باید با نظر پزشک مصرف شوند.', 98, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(99, 30, 'آیا خوردن شیر سویا در اوایل بارداری مجاز است؟', 'مصرف متعادل شیر سویا در سه ماه اول بارداری یا اوایل بارداری مجاز است و هیچ مشکلی برای مادران سالم که مشکل تیروئید یا آلرژی ندارند، ایجاد نمی‌کند. در این دوران بهتر است از نوع غنی‌شده با کلسیم و بدون شکر استفاده شود.', 99, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(100, 30, 'آیا خوردن شیر سویا در بارداری باعث سقط جنین می‌شود؟', 'خیر. شواهد علمی نشان می‌دهند که مصرف متعادل شیر سویا در یک رژیم متنوع، با افزایش خطر سقط جنین هیچ ارتباطی ندارد.', 100, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(101, 30, 'بهترین شیر گیاهی در بارداری کدام است؟', 'از نظر تغذیه‌ای، شیر سویای غنی‌شده به دلیل داشتن پروتئین کامل و شباهت بیشتر به شیر گاو، بهترین انتخاب گیاهی است. سایر شیرها مانند شیر بادام یا جو دوسر پروتئین کافی ندارند.', 101, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(102, 30, 'مصرف شیر سویا روی جنسیت جنین تاثیر دارد؟', 'خیر. این باور قدیمی کاملا اشتباه است و جنسیت جنین تنها توسط کروموزوم اسپرم پدر تعیین می‌شود و رژیم غذایی مادر هیچ تاثیری بر آن ندارد.', 102, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(103, 30, 'در بارداری شیر سویا بخوریم یا شیر گاو؟', 'اگر مشکلی با لبنیات ندارید، شیر گاو منبع طبیعی عالی است. اگر گیاهخوار هستید یا به لاکتوز حساسیت دارید، شیر سویای غنی‌شده بهترین جایگزین است.', 103, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(104, 30, 'چه زمانی برای خونریزی لثه باید به دندانپزشک مراجعه کنم؟', 'اگر خونریزی شدید یا مداوم است، یا همراه با تورم، درد و تشدید علائم لثه باشد، بهتر است به دندانپزشک مراجعه کنید.', 104, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(105, 30, 'آیا می‌توانم در بارداری برای خونریزی لثه جرم‌گیری انجام دهم؟', 'بله. جرمگیری دندانها در دوران بارداری قابل انجام است و به کاهش پلاک و التهاب لثه کمک میکند.', 105, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(106, 30, 'برای خونریزی لثه در بارداری چه دهان‌شویه‌ای می‌توانم استفاده کنم؟', 'دهانشویه بدون الکل میتواند به کنترل التهاب و باکتریهای دهان کمک کند. برای دهانشویههای دارویی، پیش از مصرف با پزشک یا دندانپزشک مشورت کنید.', 106, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(107, 30, 'آیا خونریزی لثه می‌تواند نشانه کمبود ویتامین در بارداری باشد؟', 'خونریزی لثه در بارداری معمولا با تغییرات هورمونی و افزایش حساسیت لثه به پلاک ارتباط دارد؛ کمبود ویتامین به عنوان علت اصلی آن محسوب نمیشود.', 107, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(108, 30, 'از چه هفته‌ای باید مصرف مکمل‌های بارداری را شروع کرد؟', 'مصرف اسید فولیک بهتر است از یک تا سه ماه قبل از بارداری آغاز شود و تا پایان هفته دوازدهم ادامه پیدا کند. سایر مکملها نیز بسته به شرایط مادر و نظر پزشک از ابتدای بارداری یا در هفتههای بعد شروع میشوند.', 108, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(109, 30, 'آیا می‌توان آهن و کلسیم را همزمان مصرف کرد؟', 'خیر. کلسیم جذب آهن را کاهش میدهد؛ بنابراین بهتر است این دو مکمل با حداقل ۲ ساعت فاصله مصرف شوند تا جذب هر دو بهخوبی انجام شود.', 109, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(110, 30, 'در صورت ویار شدید، مکمل‌های بارداری را چگونه مصرف کنیم؟', 'بهتر است مکمل را بعد از غذا یا پیش از خواب مصرف کنید. در صورت شدید بودن ویار، بهجای قطع خودسرانه مکملها، با پزشک درباره تغییر نوع یا زمان مصرف آنها مشورت کنید.', 110, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(111, 30, 'بهترین زمان برای خوردن مولتی ویتامین در بارداری چه زمانی است؟', 'بهتر است هنگام اقدام به بارداری یا بلافاصله پس از مشاهده اولین علائم بارداری، مصرف را آغاز کنید.', 111, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(112, 30, 'آیا مصرف مولتی‌ویتامین با معده خالی ضرر دارد؟', 'این کار توصیه نمیشود، زیرا در بسیاری از مادران باعث بروز مشکلات گوارشی یا تشدید تهوع صبحگاهی میشود.', 112, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(113, 30, 'برای کاهش تهوع بارداری مولتی‌ویتامین را چه زمانی مصرف کنیم؟', 'برای جلوگیری از تهوع، مولتیویتامین را همراه با وعده غذایی میل کنید.', 113, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(114, 30, 'اگر یک نوبت مولتی‌ویتامین را فراموش کنیم چه کار کنیم؟', 'به محض یادآوری آن را مصرف کنید. اما اگر زمان کمی تا نوبت بعدی باقی مانده، از آن صرفنظر کرده و و طبق برنامه عادی پیش بروید.', 114, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(115, 30, 'آیا شیاف دیکلوفناک در بارداری باعث سقط جنین می‌شود؟', 'نتایج برخی مطالعات نشان داده‌اند که مصرف شیاف دیکلوفناک ۱۰۰ در بارداری یا حتی دوزهای کمتر در اوایل بارداری، ممکن است ریسک سقط جنین را افزایش دهد.', 115, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(116, 30, 'عوارض شیاف دیکلوفناک در بارداری برای جنین چیست؟', 'مصرف شیاف دیکلوفناک 100 در بارداری یا حتی شیاف دیکلوفناک 50 در بارداری، عوارض مختلفی برای جنین دارد. از هفته بیستم، احتمال اختلال در عملکرد کلیه جنین و کاهش مایع آمنیوتیک افزایش پیدا می‌کند و از هفته 30 به بعد، خطر بسته شدن زودرس مجرای شریانی جنین وجود دارد.', 116, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(117, 30, 'آیا در بارداری میشه شیاف دیکلوفناک استفاده کرد؟', 'استفاده از این دارو در سه ماهه اول و تا قبل از هفته 20 بارداری تنها با نظر پزشک مجاز است، اما پس از هفته 20 تا 30 ممنوعیت شدید دارد و از هفته 30 به بعد باید کاملا از مصرف آن خودداری شود.', 117, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(118, 30, 'رده بندی شیاف دیکلوفناک در بارداری چیست؟', 'سازمان دارو و محصولات درمانی استرالیا (AU TGA) شیاف دیکلوفناک را در رده C در بارداری قرار داده است. این رده‌بندی نشان می‌دهد که شیاف دیکلوفناک در بارداری می‌تواند اثرات مضری (غیرساختاری) روی جنین ایجاد کند که ممکن است قابل بازگشت باشند. سازمان غذا و داروی ایالات متحده (US FDA) تاکنون رده‌بندی برای این دارو تعیین نکرده است.', 118, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(119, 30, 'چرا در بارداری، شب‌ها بیشتر دچار گرفتگی پا می‌شوم؟', 'در بارداری، خستگی عضلات، تغییر گردش خون و فشار رحم میتوانند گرفتگی پا را بیشتر کنند. این مشکل معمولا هنگام استراحت و شبها بیشتر احساس میشود.', 119, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(120, 30, 'آیا گرفتگی پا به جنینم آسیب می‌رساند؟', 'خیر. گرفتگی معمولی پا، خطری برای جنین ندارد و از عوارض شایع بارداری است. اگر گرفتگی شدید یا همراه با علائم غیرعادی باشد، باید توسط پزشک معاینه شوید.', 120, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(121, 30, 'برای رفع سریع گرفتگی پا در بارداری چه کار کنم؟', 'عضله را به آرامی ماساژ دهید و پنجه پا را به سمت خود بکشید. ماساژ ملایم، کمپرس گرم و کمی راه رفتن میتوانند به شل شدن عضله و کاهش درد کمک کنند.', 121, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(122, 30, 'آیا عفونت چشم می‌تواند باعث تاری دید در بارداری شود؟', 'بله، عفونت چشم میتواند باعث تاری دید شود.', 122, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(123, 30, 'آیا استفاده از لنز تماسی باعث عفونت چشم در بارداری می‌شود؟', 'استفاده نادرست از لنز، خوابیدن با آن یا رعایت نکردن بهداشت میتواند خطر عفونت چشم را در بارداری افزایش دهد.', 123, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(124, 30, 'آیا آرایش چشم می‌تواند عفونت چشم را در بارداری تشدید کند؟', 'بله، آرایش چشم میتواند تحریک، آلودگی و انتقال عفونت را بیشتر کند.', 124, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(125, 30, 'درمان سریع عفونت چشم در بارداری چیست؟', 'درمان سریع آن شامل شستوشوی دست، کمپرس تمیز و مراجعه به پزشک برای دریافت قطره مناسب بارداری میشود.', 125, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(126, 30, 'آیا واریس پا بعد از زایمان از بین می‌رود؟', 'بله، واریس بارداری در بیشتر موارد طی۳تا۴ماه بعد از زایمان کم‌رنگ‌تر یا کوچک‌تر می‌شود.', 126, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(127, 30, 'آیا ایستادن طولانی باعث بدتر شدن واریس می‌شود؟', 'بله، ایستادن طولانی می‌تواند جریان خون پاها را کند کند و فشار رگ‌ها را بالا ببرد. همین موضوع علائم واریس بارداری را تشدید می‌کند.', 127, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(128, 30, 'آیا واریس در بارداری منجر به زایمان زودرس می‌شود؟', 'خیر، واریس پا در بارداری به‌تنهایی باعث زایمان زودرس نمی‌شود.', 128, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(129, 30, 'درد تخمدان تا چه زمانی در بارداری طبیعی محسوب می‌شود؟', 'درد خفیف و گذرای تخمدان بدون خونریزی یا علائم نگرانکننده، معمولا طبیعی است درد شدید یا مداوم این ناحیه باید توسط پزشک بررسی شود.', 129, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(130, 30, 'درد تخمدان در بارداری به جنین آسیب می‌زند؟', 'درد خفیف معمولا به جنین آسیب نمیزند. اما در صورت وجود دلایلی مثل عفونت، خونریزی، بارداری خارجرحمی یا پیچخوردگی تخمدان باید سریع ارزیابی پزشکی انجام شود.', 130, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(131, 30, 'برای کاهش درد تخمدان در بارداری چه کارهایی بی‌خطر است؟', 'استراحت، تغییر آرام وضعیت بدن، نوشیدن آب، مصرف فیبر، وعدههای سبک، پیادهروی ملایم و کمپرس گرم ملایم روشهای بیخطری برای مدیریت این شرایط هستند. اما در صورت درد شدید یا خونریزی مراجعه به پزشک لازم است.', 131, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(132, 30, 'درد تخمدان یک‌طرفه در بارداری نشانه چیست؟', 'گاهی به کیست تخمدان یا جسم زرد، فشار رحم یا مشکلات گوارشی مربوط است؛ اما درد شدید یکطرفه میتواند نشانه وضعیتهای جدی هم باشد.', 132, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(133, 30, 'چه زمانی برای درد تخمدان در بارداری باید به پزشک مراجعه کرد؟', 'اگر درد شدید، ناگهانی، مداوم یا همراه خونریزی، سرگیجه، تب، غش، تهوع شدید یا درد شانه باشد، مراجعه فوری لازم است.', 133, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(134, 30, 'دوران نقاهت زایمان طبیعی کوتاه‌تر است یا سزارین؟', 'نقاهت زایمان طبیعی کوتاهتر از سزارین است. زیرا سزارین یک جراحی است و به زمان بیشتری برای بهبود نیاز دارد.', 134, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(135, 30, 'بعد از سزارین می‌توانم زایمان طبیعی داشته باشم؟', 'بله، بسیاری از زنان پس از سزارین میتوانند زایمان طبیعی داشته باشند. اما به شرایط بارداری و نظر پزشک بستگی دارد.', 135, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(136, 30, 'زایمان طبیعی روی شیردهی تاثیر بهتری دارد؟', 'زایمان طبیعی ممکن است شروع شیردهی را کمی آسانتر و زودتر کند. اما سزارین هم مانع شیردهی موفق نیست و تفاوت چشمگیری ندارند.', 136, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(137, 30, 'آیا زایمان بدون درد باعث افزایش احتمال سزارین می‌شود؟', 'خیر، شواهد نشان میدهند اپیدورال بهطور معمول احتمال سزارین را افزایش نمیدهد. عوامل پزشکی و روند پیشرفت زایمان عوامل تعیینکنندهتری هستند.', 137, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(138, 30, 'تزریق اپیدورال در چه مرحله‌ای از زایمان انجام می‌شود؟', 'اپیدورال معمولا پس از شروع زایمان، بنا به تایید پزشک انجام میشود.', 138, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(139, 30, 'آیا بعد از زایمان بدون درد کمردرد ایجاد می‌شود؟', 'ممکن است درد موقتی محل تزریق ایجاد شود، اما اپیدورال معمولا کمردرد مزمن نمیآورد.', 139, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(140, 30, 'جای زخم سزارین معمولا چقدر طول می‌کشد تا بهتر شود؟', 'ترمیم اولیه معمولا ۴ تا ۶ هفته طول میکشد، اما بهبود کامل پوست و کاهش قرمزی و اسکار ممکن است تا 12 ماه یا بیشتر ادامه پیدا کند.', 140, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(141, 30, 'برای بهبود جای زخم سزارین چه باید کرد؟', 'برای بهبود این زخم باید آن را تمیز و خشک نگه داشت، از فشار و کشش ناحیه اجتناب کرد، تغذیه و خواب کافی داشت، و در صورت نیاز از کرمها یا درمانهای پزشکی مناسب استفاده کرد.', 141, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(142, 30, 'آیا خارش و سوزش جای زخم سزارین طبیعی است؟', 'بله، خارش خفیف و سوزش جزئی در مراحل بازسازی پوست طبیعی است، اما خارش شدید یا همراه با ترشح نیاز به بررسی پزشک دارد.', 142, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(143, 30, 'بهترین پماد برای جای زخم سزارین چیست؟', 'پماد ترمیم کننده یا ژل سیلیکونی پزشکی، مهمترین گزینه برای بهبود جای زخم سزارین محسوب میشود و استفاده منظم از آن به کاهش ضخامت، قرمزی کمرنگ شدن اسکار کمک میکند.', 143, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(144, 30, 'آیا ماساژ یا ورزش سبک به ترمیم جای زخم کمک می‌کند؟', 'ورزش ملایم و ماساژ ملایم بعد از بسته شدن اولیه زخم، جریان خون را افزایش داده و روند بهبود بافتها را تسریع میکند.', 144, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(145, 30, 'بهترین روش برای پیشگیری از اسکار برجسته چیست؟', 'مراقبت صحیح از زخم شامل تمیز نگه داشتن، جلوگیری از فشار یا کشش روی ناحیه، استفاده از ورقه یا ژل سیلیکونی و رعایت سبک زندگی سالم، بهترین روش برای پیشگیری از اسکار برجسته است.', 145, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(146, 30, 'چرا شب‌ها بعد از زایمان بیشتر عرق می‌کنم؟', 'تعریق شبانه بعد از زایمان معمولا بهدلیل افت هورمونها و دفع مایعات اضافی بدن در زمان استراحت بیشتر احساس میشود.', 146, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(147, 30, 'آیا تعریق زیاد بعد از زایمان باعث کم‌آبی بدن می‌شود؟', 'بله، اگر آب کافی ننوشید، تعریق زیاد میتواند خطر کمآبی را بیشتر کند.', 147, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(148, 30, 'چه غذاهایی تعریق بعد از زایمان را تشدید می‌کنند؟', 'غذاهای تند، نوشیدنیهای خیلی گرم، کافئین و غذاهای سنگین ممکن است گرگرفتگی و تعریق بعد از زایمان را در برخی مادران تشدید کنند.', 148, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(149, 30, 'افت ضربان قلب جنین یعنی حتما باید سزارین انجام شود؟', 'افت ضربان قلب جنین همیشه به معنی سزارین نیست. پزشک شدت، مدت افت و وضعیت جنین را بررسی می‌کند؛ اگر افت ادامه‌دار یا خطرناک باشد، سزارین لازم می‌شود.', 149, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(150, 30, 'اگر زایمان طبیعی پیش نرود چه زمانی سزارین انجام می‌شود؟', 'اگر با وجود انقباضات مناسب، دهانه رحم باز نشود یا جنین پایین نیاید و ادامه زایمان خطرناک یا بی‌فایده باشد، پزشک سزارین را توصیه می‌کند.', 150, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(151, 30, 'آیا وضعیت نامناسب جنین همیشه باعث سزارین فوری می‌شود؟', 'نه، همیشه فوری نیست. پزشک نوع وضعیت جنین، سن بارداری، ضربان قلب و امکان اصلاح موقعیت را بررسی می‌کند؛ اما در دیسترس جنینی یا خطر اکسیژن‌رسانی، سزارین فوری لازم می‌شود.', 151, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(152, 30, 'آیا سزارین قبل از هفته ۳۹ خطرناک است؟', 'اگر بدون دلیل پزشکی انجام شود، می‌تواند خطر مشکلات تنفسی، نیاز به مراقبت ویژه و ناپایداری وضعیت نوزاد را بیشتر کند.', 152, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(153, 30, 'چه عواملی باعث جلو افتادن زمان سزارین می‌شوند؟', 'خونریزی، مشکلات جفت، پره‌اکلامپسی شدید، افت ضربان قلب جنین، توقف زایمان یا خطر پارگی رحم می‌توانند زمان سزارین را جلو بیندازند.', 153, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(154, 30, 'نوزاد ۸ ماهه روزانه چقدر شیر مادر یا شیر خشک نیاز دارد؟', 'در ۸ ماهگی، شیر مادر یا شیر خشک همچنان بخش مهمی از تغذیه نوزاد است و معمولا در کنار غذاهای کمکی، حدود نیمی از نیاز روزانه او را تامین میکند. مقدار دقیق آن به اشتها و نظر پزشک بستگی دارد.', 154, 1, 0, 0, '2026-09-06 19:23:29', '2026-09-09 10:18:08'),
(155, 30, 'اگر نوزاد ۸ ماهه شب‌ها مرتب بیدار شود طبیعی است؟', 'بله. در این سن، اضطراب جدایی، دندان درآوردن یا یادگیری مهارتهای جدید میتوانند باعث بیدار شدن مکرر نوزاد در طول شب شوند.', 155, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(156, 30, 'آیا لجبازی یا وابستگی شدید در نوزاد ۸ ماهه طبیعی است؟', 'بله. وابستگی بیشتر به والدین، بیقراری هنگام دور شدن آنها و محتاط بودن در برابر غریبهها، بخشی طبیعی از رشد عاطفی و شناختی نوزاد در این سن هستند.', 156, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(157, 30, 'چه زمانی رشد نوزادشش ماهه نگران‌کننده است؟', 'اگر کودک مهارت‌های حرکتی مثل نشستن با حمایت، گرفتن اشیا، یا واکنش به صداها را نشان ندهد، یا تغییرات غیرطبیعی در وزن و قد داشته باشد، باید با پزشک مشورت کرد.', 157, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(158, 30, 'گریه زیاد نوزاد شش ماهه نشانه چیست؟', 'گریه ممکن است نشانه گرسنگی، خستگی، نیاز به آرامش یا دندان درآوردن باشد. همچنین، ناراحتی کوتاه ‌مدت هنگام کشف محیط و بازی طبیعی است.', 158, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(159, 30, 'نوزاد شش ماهه چه کارهایی باید بلد باشد؟', 'نشستن با حمایت، ایجاد آواهای ساده، گرفتن اشیا و اسباب‌بازی در دست، واکنش نشان دادن به صداها و توانایی غلت زدن، برخی از کارهایی هستند که نوزاد شش ماهه باید بلد باشد.', 159, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(160, 30, 'نوزاد سه ماهه در روز چند بار باید مدفوع کند؟', 'نوزادان در بازه سنی سه تا چهار ماهگی، معمولا به‌ طور میانگین 2 تا 4 بار در روز دفع دارند.', 160, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(161, 30, 'نوزاد سه ماهه در شب چند بار باید شیر بخورد؟', 'با افزایش حجم معده در سه ماهگی، نوزاد می‌تواند مقدار بیشتری شیر بخورد و معمولا فواصل شیردهی به هر 4 تا 5 ساعت یک‌بار می‌رسد.', 161, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(162, 30, 'نوزاد سه ماهه چقدر شیر خشک میخوره؟', 'میزان نیاز نوزاد به شیر، چه شیر مادر و چه شیر خشک در این سن، معمولا حدود 120 تا 180 میلی‌لیتر در هر نوبت است.', 162, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(163, 30, 'نوزاد سه ماهه باید چند کیلو باشد؟', 'وزن نوزاد سه ماهه دختر حدود 5.9 کیلوگرم و وزن نوزاد سه ماهه پسر حدود 6.4 کیلوگرم پیش‌بینی می‌شود.', 163, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(164, 30, 'نوزاد سه ماهه چند ساعت میخوابد؟', 'نوزاد سه ماهه به 14 تا 16 ساعت خواب در شبانه‌ روز نیاز دارد که معمولا 10 ساعت آن در شب و حدود 6 ساعت آن به صورت چرت‌های روزانه تقسیم می‌شود.', 164, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(165, 30, 'قد نرمال نوزاد سه ماهه چند است؟', 'میانگین قد نوزاد سه ماهه دختر حدود 59.8 سانتی‌متر است، در حالی که میانگین قد نوزاد سه ماهه پسر حدود 61.4 سانتی‌متر تخمین زده می‌شود.', 165, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(166, 30, 'به نوزاد سه ماهه میشه اب داد؟', 'خیر، توصیه می‌شود که به نوزادان زیر 6 ماه آب داده نشود، چون می‌تواند خطرناک باشد.', 166, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(167, 30, 'نوزاد در چهار ماهگی چه واکسن هایی باید بزند؟', 'نوزاد در چهار ماهگی باید واکسن پنج‌گانه و واکسن فلج اطفال را بزند.', 167, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(168, 30, 'وزن و قد نوزاد چهار ماهه چقدر است؟', 'وزن و قد نوزاد چهار ماهه باید به‌ترتیب بین 4.5 کیلوگرم تا 8 کیلوگرم و 56 سانتی‌متر تا 69 سانتی‌متر باشد.', 168, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(169, 30, 'آیا نوزاد چهار ماهه به غذای کمکی نیاز دارد؟', 'خیر. کودکان تا 6 ماهگی نیازی به غذای کمکی نداشته و شیر مادر یا شیر خشک تمامی نیازهای بدن آن‌ها را تامین می‌کند.', 169, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(170, 30, 'نوزاد چهار ماهه چقدر باید بخوابد؟', 'نوزاد در چهار ماهگی باید بین 12 تا 16 ساعت بخوابد که شامل 9 تا 10 ساعت خواب شبانه و دو چرت روزانه برای 3 تا 4 ساعت است.', 170, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(171, 30, 'بهترین زمان اولین حمام نوزاد در چند روزگی است؟', 'طبق پیشنهاد سازمان بهداشت جهانی، بهترین زمان اولین حمام نوزاد در یک روزگی یا 24 ساعت بعد از تولد است.', 171, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(172, 30, 'چطور نوزاد یک روزه را بشوییم؟', 'برای شستشوی نوزاد یک روزه می‌توان از اسفنج یا حوله نرم و مرطوب استفاده کرد. البته شستن نوزاد با آب و شوینده ملایم نیز طبق آنچه در بالا گفته شده، بلامانع است.', 172, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(173, 30, 'نوزادان به چندبار حمام در هفته نیاز دارند؟', 'نیازی نیست نوزاد تازه متولد شده را هر روز حمام کنید؛ چون آن‌ها به‌ندرت عرق می‌کنند یا آنقدر کثیف می‌شوند که حمام کامل نیاز داشته باشند؛ بنابراین 3 بار حمام در طول هفته کافی است.', 173, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(174, 30, 'چرا باید حمام کردن نوزاد را تا 24 ساعت عقب انداخت؟', 'منتظر ماندن برای اولین حمام نوزاد مزایایی شامل موفقیت بیشتر شیردهی، زمان بیشتر برای تماس پوست‌به‌پوست با مادر، تجربه رایحه آشنا بین بوی آمونیاک و سینه مادر و تنظیم دمای بدن هستند.', 174, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(175, 30, 'بهترین روش اولین حمام نوزاد چیست؟', 'اولین حمام نوزاد بعد از تولد بهتر است حمام اسفنجی باشد که در آن نیازی نیست نوزاد داخل وان قرار بگیرد؛ چون هنوز بند ناف او خشک نشده است.', 175, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(176, 30, 'پوست انگور برای نوزاد ضرر دارد؟', 'خیر، پوست انگور حاوی آنتی‌اکسیدان است و ضرری برای نوزاد ندارد. اما هسته‌ها باید همیشه جدا شوند تا خطر خفگی وجود نداشته باشد. برای نوزادان کوچک‌تر، بهتر است انگور پوره یا خرد شود.', 176, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(177, 30, 'انگور باعث دل‌درد یا نفخ نوزاد می‌شود؟', 'در حالت معمولی، مصرف مقدار مناسب انگور باعث دل‌درد یا نفخ نمی‌شود. مصرف زیاد یا ناگهانی می‌تواند گاهی مشکلات گوارشی جزئی ایجاد کند.', 177, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(178, 30, 'نشانه‌های حساسیت نوزاد به انگور چیست؟', 'واکنش‌های آلرژیک ممکن است شامل جوش، قرمزی پوست، استفراغ یا اسهال باشند. اگر چنین علائمی را مشاهده کردید، مصرف انگور را متوقف کرده و از پزشک کمک بگیرید.', 178, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(179, 30, 'آیا می‌توان دانه‌های کامل انار را به نوزاد داد؟', 'بهتر است از دادن دانههای کامل به نوزادان خودداری کنید، زیرا خطر خفگیدارند. بهترین روش این است که دانهها را پوره یا له کرده و سپس به کودک بدهید.', 179, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(180, 30, 'چه میزان انار به نوزاد بدهیم؟', 'با مقدار کم، مانند یک تا دو قاشق چایخوری شروع کنید و به تدریج افزایش دهید. همیشه واکنش کودک را بررسی کنید و در صورت حساسیت یا مشکلات گوارشی، مقدار را تغییر دهید.', 180, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(181, 30, 'آیا انار برای سرماخوردگی نوزاد مفید است؟', 'تحقیقات نشان میدهند که عصارههای انار ممکن است اثرات ضدویروسی داشته باشند، اما هیچ شواهد محکمی برای درمان سرماخوردگی با انار وجود ندارد.', 181, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(182, 30, 'چگونه انار را برای نوزاد پوره کنیم؟', 'برای نوزادان بزرگتر، دانهها را له کرده و با میوه نرم دیگری مانند موز مخلوط کنید تا یک پوره ایمن و مغذی تهیه شود.', 182, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(183, 30, 'آیا انار در رشد مغز نوزاد موثر است؟', 'انار حاوی مواد مغذی و پلیفنولهایی است که میتوانند به سلامت مغز و عملکرد شناختی کودک کمک کنند.', 183, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(184, 30, 'از چند ماهگی به نوزاد موز بدهیم؟', 'از 6 ماهگی می‌توانید به نوزاد موز بدهید.', 184, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(185, 30, 'بافت موز نوزاد در هر سنی باید چطور باشد؟', 'بافت موز در شروع غذای کمکی باید به‌شکل پوره‌شده باشد و به‌مرور می‌توانید موز له‌شده، نوارهای باریک موز و در نهایت یک‌سوم یا حتی یک موز کامل را به کودک بدهید.', 185, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(186, 30, 'آیا ممکن است نوزادان با خوردن موز خفه شوند؟', 'خیر. موز به‌دلیل نرم بودن، خطر خفگی رایجی برای نوزادان ندارد؛ نوزادان ممکن است هنگام خوردن موز حالت‌ تهوع داشته باشند؛ چون به سقف دهانشان می‌چسبد.', 186, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(187, 30, 'موز باعث یبوست نوزاد می‌شود؟', 'مو نارس (موز سبز) به‌دلیل داشتن نشاسته مقاوم، مدفوع را سفت کرده و از این طریق ممکن است باعث یبوست شود.', 187, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(188, 30, 'آیا موز برای نوزاد حساسیت‌زا است؟', 'خیر. موز تنها در نوزادانی که به لاتکس حساسیت دارند ممکن است باعث واکنش آلرژیک شود.', 188, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(189, 30, 'نارنگی از چند ماهگی به نوزاد بدهیم؟', 'در پاسخ به این سوال که نارنگی از چند ماهگی مجاز است، باید بگوییم که می‌توانید بعد از ۸ ماهگی و زمان که کودک برای خوردن غذاهای کمکی آماده است، از مقدار کمی نارنگی در رژیم غذایی نوزاد استفاده کنید.', 189, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(190, 30, 'آیا ممکن است خوردن نارنگی در کودک موجب حساسیت شود؟', 'نارنگی معمولا حساسیت‌زا نیست، ولی افراد مبتلا به سندرم آلرژی دهان، ممکن است بعد از خوردن این میوه دچار مشکل شوند. در موارد نادر، برخی کودکان نیز ممکن است بعد از مصرف این میوه دچار علائم آلرژی و بثورات پوستی شوند.', 190, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(191, 30, 'مصرف آب نارنگی برای نوزاد، از چه سنی مجاز است؟', 'آب نارنگی بهتر است بعد از ۸ ماهگی تا یک سالگی مصرف شود. به خاطر داشته باشید که مصرف میوه به دلیل وجود فیبر، از آب میوه مفیدتر است و از همین رو توصیه می‌شود از آب میوه به مقدار محدود استفاده کنید.', 191, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(192, 30, 'آیا خواب‌آلودگی بعد از مصرف هیدروکسی زین طبیعی است؟', 'بله، خوابآلودگی از عوارض شایع شربت هیدروکسی زین برای کودکان است. اگر این عوارض شدید یا طولانی شدند، باید با پزشک مشورت کنید.', 192, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(193, 30, 'اگر یک نوبت داروی فرزندم را فراموش کنم چه کار کنم؟', 'دوز فراموششده را بهمحض یادآوری، به کودک بدهید. اما اگر نوبت بعدی نزدیک است، آن را حذف کرده و دوز را دوبرابر نکنید.', 193, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(194, 30, 'آیا می‌توانم هیدروکسی زین را همراه شربت سرماخوردگی بدهم؟', 'خیر، بدون نظر پزشک این دو دارو را به صورت همزمان به کودک ندهید. بعضی شربتهای سرماخوردگی، آنتیهیستامین یا ترکیبات خوابآور دارند و میتوانند خوابآلودگی و عوارض کودک را تشدید کنند.', 194, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `order`, `is_active`, `view_count`, `helpful_count`, `created_at`, `updated_at`) VALUES
(195, 30, 'اگر یک نوبت از دارو فراموش بشه، باید چیکار کنم؟', 'در صورتی که یک دوز از آزیترومایسین را فراموش کردید، در زمان یادآوری سریعاً آن را مصرف کنید. اگر از زمان مصرف آن دوز خیلی گذشته است، دیگر نیازی به مصرف دوز فراموش شده نیست. از مصرف هم‌زمان دو دوز آزیترومایسین پرهیز کنید.', 195, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(196, 30, 'کاربرد قرص آزیترومایسین چیست؟', 'قرص های آزیترومایسین در دوز 250 مورد استفاده قرار می‌گیرند و دوره مصرف این قرص ها مشابه دوره مصرف شربت آزیترومایسین، یک دوره 1 تا 5 روزه است. در روز اول، دو قرص 250 میلی‌گرمی و در روزهای بعدی، یک قرص 250 میلی‌گرمی مصرف می‌شود.بنابراین می‌توان گفت طیف درمان قرص آزیترومایسین مانند طیف درمان شربت آزیترومایسین است.', 196, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(197, 30, 'چند روز باید آزیترومایسین به کودک داده شود؟', 'مدت درمان معمولاً ۳ تا ۵ روز است، اما طول دقیق دوره با توجه به نوع و شدت عفونت باید توسط پزشک تعیین شود.', 197, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(198, 30, 'میشه آزیترومایسین رو با شیر یا غذا به کودک داد؟', 'بله، مصرف آزیترومایسین با غذا یا شیر مشکلی ایجاد نمی‌کند و حتی ممکن است ناراحتی معده را کاهش دهد.', 198, 1, 0, 0, '2026-09-06 19:23:30', '2026-09-09 10:18:08'),
(199, 30, 'آیا حرکات زیاد جنین نشانه پسر بودن است؟', 'خیر، حرکات زیاد جنین ارتباط مستقیمی با جنسیت ندارد و تحت تاثیر عواملی مانند سلامت و سطح فعالیت جنین است.', 199, 1, 0, 0, '2026-09-07 13:27:24', '2026-09-09 10:18:08'),
(200, 30, 'آزمایش بارداری خون مثبت شد و عدد بتام ۲۰۵ است. آیا جنین پسر است؟', 'خیر؛ عدد بتا جنسیت جنین را مشخص نمیکند.', 200, 1, 0, 0, '2026-09-07 13:27:24', '2026-09-09 10:18:08'),
(201, 30, 'آیا جنین چهار ماهه تغییر جنسیت می‌دهد؟', 'خیر؛ جنسیت جنین از لحظه لقاح تعیین میشود و تغییر نمیکند.', 201, 1, 0, 0, '2026-09-07 13:27:24', '2026-09-09 10:18:08'),
(202, 30, 'آیا می‌شود با تغذیه پسردار شد؟', 'تغذیه تنها در شرایط خاص احتمال بارداری پسر را کمی تغییر میدهد ولی به تنهایی قطعی نیست و حتما برای تعیین جنسیت باید اصلاح سبک و تغذیه و روز اقدام و نوع پوزیشن و.. همراه باشد تا اثردهی بیشتر شود.', 202, 1, 0, 0, '2026-09-07 13:27:24', '2026-09-09 10:18:08'),
(203, 30, 'از چند هفتگی می‌توان جنسیت جنین را با آزمایش خون مشخص کرد؟', 'آزمایش خون تعیین جنسیت (بررسی DNA جنینی در خون مادر) معمولاً از حدود هفته 9 تا 10 بارداری قابل انجام است و در صورت انجام در زمان مناسب، دقت بالایی دارد.', 203, 1, 0, 0, '2026-09-07 13:27:24', '2026-09-09 10:18:08'),
(204, 30, 'کدام روش تعیین جنسیت کم‌خطرتر است؟', 'کمخطرترین روشها، آزمایش خون غیرتهاجمی (NIPT) و سونوگرافی هستند، زیرا نیازی به ورود به رحم یا نمونهگیری تهاجمی ندارند. در مقابل، روشهایی مانند آمنیوسنتز یا CVS فقط در موارد خاص و با تجویز پزشک انجام میشوند.', 204, 1, 0, 0, '2026-09-07 13:27:24', '2026-09-09 10:18:08'),
(205, 30, 'آیا می‌توان در ماه اول بارداری جنسیت را فهمید؟', 'در ماه اول بارداری تعیین جنسیت بهصورت قطعی امکانپذیر نیست. در این زمان جنین هنوز در مراحل اولیه رشد است و ساختارهای جنسی قابل مشاهده یا تشخیص دقیق نیستند. تنها برخی تستهای ژنتیکی میتوانند از هفتههای بعد اطلاعات قابل اعتمادتری ارائه دهند.', 205, 1, 0, 0, '2026-09-07 13:27:24', '2026-09-09 10:18:08'),
(206, 30, 'چرا نوزادم بعد از هر بار شیر خوردن شیر پنیری بالا می‌آورد؟', 'پنیری یا دلمهای شدن شیر معمولا به این دلیل است که شیر مدتی در معده مانده و با اسید معده مخلوط شده است؛ ظاهر پنیری آن به تنهایی نشانه بیماری نیست.', 206, 1, 0, 0, '2026-09-07 13:27:24', '2026-09-09 10:18:08'),
(207, 30, 'نوزادم شیر پنیری بالا می‌آورد اما وزن‌گیری خوبی دارد؛ آیا باید نگران باشم؟', 'اگر نوزاد سرحال است، به خوبی شیر میخورد و وزنگیری مناسبی دارد، بالا آوردن مقدار کمی شیر پنیری معمولا طبیعی است و با رشد نوزاد کاهش پیدا میکند.', 207, 1, 0, 0, '2026-09-07 13:27:24', '2026-09-09 10:18:08'),
(208, 30, 'آیا زیاد شیر خوردن باعث استفراغ پنیری نوزادم می‌شود؟', 'زیاد شیر خوردن میتواند احتمال رفلاکس و بالا آوردن شیر را بیشتر کند، اما پنیری شدن آن مستقیما به حجم شیر مربوط نیست. شیری که مدتی در معده میماند و با اسید معده مخلوط میشود، ممکن است هنگام بالا آمدن ظاهر دلمهای یا پنیری داشته باشد.', 208, 1, 0, 0, '2026-09-07 13:27:24', '2026-09-09 10:18:08'),
(209, 30, 'سفیده تخم مرغ از چند ماهگی به نوزاد بدهیم؟', 'سفیده تخم مرغ را می‌توان از 6 ماهگی به تغذیه نوزاد اضافه کرد.', 209, 1, 0, 0, '2026-09-07 13:27:24', '2026-09-09 10:18:08'),
(210, 30, 'زرده تخم مرغ از چند ماهگی میشه داد؟', 'مصرف زرده را همچون سفیده می‌توان از 6 ماهگی شروع کرد.', 210, 1, 0, 0, '2026-09-07 13:27:24', '2026-09-09 10:18:08'),
(211, 30, 'آیا تخم‌مرغ باعث حساسیت در نوزاد می‌شود؟', 'بله، تخم‌مرغ یکی از مواد غذایی آلرژن محسوب می‌شود و ممکن است در برخی نوزادان باعث کهیر، استفراغ یا خس‌خس سینه شود؛ اضافه کردن تدریجی به برنامه غذایی نوزاد و پخت کامل آن، خطر حساسیت را کاهش می‌دهد.', 211, 1, 0, 0, '2026-09-07 13:27:24', '2026-09-09 10:18:08'),
(212, 30, 'آیا نوزاد زیر یک سال می‌تواند تخم‌مرغ کامل بخورد؟', 'بله نوزاد از 6 ماهگی می‌تواند تخم مرغ کامل بخورد.', 212, 1, 0, 0, '2026-09-07 13:27:24', '2026-09-09 10:18:08'),
(213, 30, 'تخم‌مرغ محلی بهتر است یا صنعتی برای نوزاد؟', 'برای نوزاد تفاوت اصلی در ایمنی و سلامت تخم‌مرغ است. تخم‌مرغ صنعتی پاستوریزه و دارای نظارت بهداشتی معمولا انتخاب مطمئن‌تری است؛ مهم‌تر از نوع آن، تازگی و پخت کامل تخم مرغ برای نوزاد است.', 213, 1, 0, 0, '2026-09-07 13:27:24', '2026-09-09 10:18:08'),
(214, 30, 'چند بار در هفته می‌توان به نوزاد تخم‌مرغ داد؟', 'محدودیت هفتگی مشخصی برای مصرف تخم مرغ برای نوزاد وجود ندارد؛ تخم‌مرغ می‌تواند چند بار در هفته و در چارچوب رژیم متنوع غذایی مصرف شود. مهم‌تر از تعداد دفعات، رعایت پخت کامل و تعادل غذایی است.', 214, 1, 0, 0, '2026-09-07 13:27:25', '2026-09-09 10:18:08');

