INSERT INTO `pregnancy_exercises` (`id`, `exercise_name`, `description`, `benefits`, `how_to_do`, `duration`, `trimester`, `week_start`, `week_end`, `intensity_level`, `category`, `equipment_needed`, `precautions`, `is_high_risk`, `requires_doctor_consultation`, `created_at`, `updated_at`) VALUES
(1, 'پیاده‌روی منظم', 'یکی از ایمن‌ترین و در دسترس‌ترین ورزش‌ها برای تمام دوران بارداری. پیاده‌روی با سرعت متوسط، یک ورزش هوازی عالی است که به تجهیزات خاصی نیاز ندارد و می‌توان آن را در هر مکانی انجام داد. [citation:1][citation:4]', 'بهبود گردش خون، کاهش استرس و اضطراب، کنترل وزن، کاهش کمردرد، افزایش سطح انرژی، بهبود کیفیت خواب، کاهش خطر دیابت بارداری، آمادگی برای زایمان [citation:1][citation:5][citation:6]', 'با سرعت آهسته شروع کنید و به تدریج سرعت خود را افزایش دهید. روی سطح صاف و هموار راه بروید. کفش راحت و مناسب بپوشید. دست‌های خود را به طور طبیعی حرکت دهید. [citation:1][citation:2]', '۳۰ دقیقه در روز، حداقل ۵ روز در هفته (جمعاً ۱۵۰ دقیقه در هفته) [citation:2][citation:5]', 'all', NULL, NULL, 'moderate', 'cardio', 'کفش ورزشی راحت', 'از پیاده‌روی در هوای بسیار گرم یا سرد خودداری کنید. اگر دچار تنگی نفس شدید، سرعت خود را کاهش دهید. در سه‌ماهه سوم، از سطوح ناهموار خودداری کنید. [citation:1][citation:4]', 0, 0, '2026-08-05 14:39:13', '2026-08-05 14:39:13'),
(2, 'شنا و ورزش‌های آبی', 'یکی از ایمن‌ترین و کامل‌ترین ورزش‌ها در دوران بارداری. آب وزن بدن را تحمل کرده و فشار روی مفاصل را کاهش می‌دهد. شنا به ویژه برای کاهش تورم دست و پا و کمردرد بسیار مفید است. [citation:1][citation:2][citation:4]', 'کاهش فشار روی مفاصل و ستون فقرات، کاهش تورم دست و پا، تقویت عضلات بدون آسیب، بهبود گردش خون، کاهش کمردرد، افزایش انعطاف‌پذیری، آرامش ذهنی و کاهش استرس [citation:1][citation:2][citation:5]', 'در استخر با دمای ولرم (۲۸-۳۲ درجه سانتی‌گراد) شنا کنید. از کرال سینه، کرال پشت یا قورباغه با سرعت ملایم استفاده کنید. از شیرجه زدن و پریدن خودداری کنید. [citation:1][citation:2]', '۲۰-۳۰ دقیقه، ۳-۴ بار در هفته [citation:2]', 'all', NULL, NULL, 'moderate', 'cardio', 'لباس شنا، عینک شنا، کلاه شنا', 'از استخرهای با دمای بالا (جکوزی، سونا) خودداری کنید. از شیرجه زدن و حرکات ناگهانی خودداری کنید. اگر خسته شدید، استراحت کنید. [citation:1][citation:4]', 0, 1, '2026-08-05 14:39:13', '2026-08-05 14:39:13'),
(3, 'دوچرخه‌سواری ثابت', 'ورزشی کم‌تأثیر و ایمن که خطر افتادن را ندارد. دوچرخه ثابت به تقویت عضلات پا و بهبود سلامت قلب و عروق کمک می‌کند. در سه‌ماهه دوم و سوم جایگزین مناسبی برای دوچرخه‌سواری در فضای باز است. [citation:1][citation:2][citation:4]', 'تقویت عضلات پا، بهبود گردش خون، حفظ تناسب اندام، کاهش خطر دیابت بارداری، کنترل وزن، ایمن‌تر از دوچرخه‌سواری در فضای باز [citation:1][citation:2]', 'روی دوچرخه ثابت با مقاومت کم و بدون شیب بنشینید. پشت خود را صاف نگه دارید. پدال‌ها را با سرعت ملایم بزنید. از دسته‌ها برای حفظ تعادل استفاده کنید. [citation:1][citation:2]', '۲۰-۳۰ دقیقه، ۳ بار در هفته [citation:2]', 'all', 1, 40, 'moderate', 'cardio', 'دوچرخه ثابت', 'در سه‌ماهه سوم، مراقب تعادل خود باشید. از دوچرخه‌سواری در فضای باز خودداری کنید (خطر افتادن). [citation:1][citation:7]', 0, 1, '2026-08-05 14:39:13', '2026-08-05 14:39:13'),
(4, 'تمرینات کگل (Kegel)', 'تمرینات کگل برای تقویت عضلات کف لگن بسیار ضروری است. این عضلات از رحم، مثانه و روده حمایت می‌کنند و در دوران بارداری و پس از زایمان اهمیت ویژه‌ای دارند. [citation:2][citation:4][citation:5]', 'پیشگیری از بی‌اختیاری ادرار، کاهش مشکلات پس از زایمان مانند افتادگی اندام‌ها، تسهیل زایمان طبیعی، بهبود روابط جنسی، حمایت از رحم و مثانه [citation:2][citation:4]', 'عضلات کف لگن را مانند زمانی که جریان ادرار را متوقف می‌کنید، منقبض کنید. ۳-۵ ثانیه نگه دارید و سپس به آرامی رها کنید. ۱۰ بار تکرار کنید. این تمرین را می‌توانید در هر وضعیتی (نشسته، ایستاده، درازکش) انجام دهید. [citation:2]', '۱۰ تکرار در هر نوبت، ۳ نوبت در روز (مجموعاً ۳۰ تکرار در روز) [citation:2]', 'all', NULL, NULL, 'light', 'pelvic_floor', 'بدون نیاز به تجهیزات', 'اگر در حین انجام تمرین احساس درد کردید، با پزشک مشورت کنید. از انقباض عضلات شکم، باسن یا ران خودداری کنید. فقط عضلات کف لگن را منقبض کنید. [citation:2]', 0, 0, '2026-08-05 14:39:13', '2026-08-05 14:39:13'),
(5, 'اسکات (Squat)', 'اسکات یکی از بهترین تمرینات برای تقویت عضلات پا، باسن و کف لگن است. این حرکت به باز شدن لگن و آماده‌سازی برای زایمان کمک می‌کند. [citation:2]', 'تقویت عضلات پا و باسن، افزایش فضای لگن برای تولد جنین، بهبود وضعیت جنین، آمادگی برای زایمان طبیعی، کاهش کمردرد [citation:2]', 'پاها را به اندازه عرض شانه باز کنید. به آرامی بدن را پایین بیاورید (مانند نشستن روی صندلی) تا زانوها ۹۰ درجه خم شوند. ۳-۵ ثانیه نگه دارید و سپس به آرامی بلند شوید. ۸-۱۰ تکرار انجام دهید. [citation:2]', '۸-۱۰ تکرار، ۲-۳ ست در روز [citation:2]', 'all', NULL, NULL, 'moderate', 'strength', 'بدون نیاز به تجهیزات (می‌توان از صندلی برای حمایت استفاده کرد)', 'در سه‌ماهه سوم، از صندلی یا دیوار برای حمایت استفاده کنید. زانوها را از انگشتان پا جلوتر نبرید. اگر درد لگن داشتید، تمرین را متوقف کنید. [citation:2]', 0, 0, '2026-08-05 14:39:13', '2026-08-05 14:39:13'),
(6, 'تمرینات قدرتی سبک با وزنه', 'تمرینات قدرتی با وزنه‌های سبک (۱-۲ کیلوگرم) می‌تواند به حفظ عضلات و جلوگیری از کمردرد کمک کند. این تمرینات باید با احتیاط و زیر نظر مربی انجام شوند. [citation:2][citation:4]', 'حفظ توده عضلانی، جلوگیری از کمردرد، بهبود وضعیت بدن، کنترل وزن، تقویت عضلات برای زایمان [citation:2]', 'از دمبل‌های ۱-۲ کیلوگرمی استفاده کنید. تمرینات را نشسته یا ایستاده انجام دهید. روی گروه‌های عضلانی اصلی (بازو، شانه، پشت) تمرکز کنید. ۸-۱۰ تکرار در ۲-۳ ست انجام دهید. [citation:2]', '۸-۱۰ تکرار در ۲-۳ ست، ۲-۳ بار در هفته [citation:2]', 'second', 13, 26, 'moderate', 'strength', 'دمبل ۱-۲ کیلوگرمی یا کش ورزشی', 'از دراز کشیدن به پشت خودداری کنید. وزنه را روی شکم قرار ندهید. از بلند کردن وزنه‌های سنگین خودداری کنید. [citation:2][citation:7]', 1, 1, '2026-08-05 14:39:13', '2026-08-05 14:39:13'),
(7, 'یوگای بارداری', 'یوگای بارداری ترکیبی از حرکات کششی، تنفسی و آرامش‌بخش است که برای مادران باردار بسیار مفید است. این ورزش به کاهش استرس، افزایش انعطاف‌پذیری و آمادگی برای زایمان کمک می‌کند. [citation:1][citation:2][citation:4]', 'کاهش استرس و اضطراب، افزایش انعطاف‌پذیری، بهبود تنفس، کاهش کمردرد، آمادگی برای زایمان، آرامش ذهنی و جسمی، بهبود کیفیت خواب [citation:1][citation:2][citation:4]', 'حرکات ایستاده و نشسته مانند \"حرکت گربه و گاو\"، \"حرکت کودک\" و \"پروانه\" را انجام دهید. از حرکات وارونه و دراز کشیدن به پشت خودداری کنید. با تنفس عمیق همراه کنید. [citation:1][citation:2]', '۱۵-۲۰ دقیقه در روز یا شرکت در کلاس یوگای بارداری [citation:2]', 'all', 1, 40, 'light', 'flexibility', 'زیرانداز یوگا، بالش یا پتوی تاشده', 'از یوگای هات و بیکرام (در دمای بالا) خودداری کنید. از حرکات وارونه و چرخش‌های شدید شکم پرهیز کنید. اگر احساس سرگیجه یا درد کردید، تمرین را متوقف کنید. [citation:1][citation:4]', 0, 1, '2026-08-05 14:39:13', '2026-08-05 14:39:13'),
(8, 'حرکت کششی \"گربه و گاو\" (Cat-Cow)', 'حرکت کششی ملایم برای ستون فقرات که به کاهش کمردرد و افزایش انعطاف‌پذیری کمر کمک می‌کند. این حرکت در سه‌ماهه دوم و سوم بسیار مفید است. [citation:2]', 'کاهش کمردرد، افزایش انعطاف‌پذیری ستون فقرات، بهبود وضعیت بدن، کاهش فشار روی رحم، آرامش ذهنی [citation:2]', 'روی دست‌ها و زانوها قرار بگیرید. کف دست‌ها زیر شانه‌ها و زانوها زیر باسن. هنگام دم، کمر را به سمت پایین خم کنید و سر را بالا ببرید (حرکت گاو). هنگام بازدم، کمر را به سمت بالا قوس دهید و سر را پایین بیاورید (حرکت گربه). ۱۰-۱۵ بار تکرار کنید. [citation:2]', '۱۰-۱۵ تکرار، روزانه [citation:2]', 'second', 13, 40, 'light', 'flexibility', 'زیرانداز یوگا', 'اگر در مچ دست یا زانو احساس ناراحتی می‌کنید، از زیرانداز ضخیم‌تر استفاده کنید. حرکت را به آرامی و بدون فشار انجام دهید. [citation:2]', 0, 0, '2026-08-05 14:39:13', '2026-08-05 14:39:13'),
(9, 'حرکت \"کودک\" (Child\'s Pose)', 'حرکت آرامش‌بخش یوگا که به کشش کمر، شانه‌ها و ران‌ها کمک می‌کند. این حرکت برای کاهش استرس و کمردرد در تمام دوران بارداری مفید است. [citation:2]', 'کشش کمر، شانه‌ها و ران‌ها، کاهش استرس و اضطراب، آرامش ذهنی، بهبود تنفس، کاهش کمردرد [citation:2]', 'روی زانوها بنشینید و باسن را روی پاشنه پاها قرار دهید. زانوها را به اندازه عرض شانه باز کنید (برای فضای بیشتر شکم). به آرامی بالاتنه را به سمت جلو خم کنید و پیشانی را روی زمین قرار دهید. دست‌ها را در کنار بدن یا بالای سر قرار دهید. ۱-۳ دقیقه نگه دارید. [citation:2]', '۱-۳ دقیقه، روزانه [citation:2]', 'all', 1, 40, 'light', 'flexibility', 'زیرانداز یوگا، بالش یا پتوی تاشده (زیر پیشانی)', 'اگر در زانوها احساس ناراحتی می‌کنید، یک پتو یا بالش زیر زانوها قرار دهید. برای فضای بیشتر شکم، زانوها را بازتر کنید. [citation:2]', 0, 0, '2026-08-05 14:39:13', '2026-08-05 14:39:13'),
(10, 'تمرینات تنفس عمیق', 'تمرینات تنفس عمیق به مادران باردار کمک می‌کند تا آرامش بیشتری داشته باشند، استرس را کاهش دهند و برای زایمان آماده شوند. این تمرینات را می‌توان در هر زمان و مکانی انجام داد. [citation:1][citation:2][citation:4]', 'کاهش استرس و اضطراب، افزایش اکسیژن رسانی به بدن و جنین، بهبود کیفیت خواب، آمادگی برای زایمان، کنترل درد در حین زایمان [citation:1][citation:4][citation:6]', 'در وضعیت راحت بنشینید یا دراز بکشید. بینی خود را عمیقاً نفس بکشید تا ریه‌ها پر شوند. ۳-۵ ثانیه نگه دارید. سپس به آرامی از طریق دهان بازدم کنید. ۵-۱۰ بار تکرار کنید. [citation:4]', '۵-۱۰ بار در هر نوبت، ۲-۳ نوبت در روز [citation:4]', 'all', NULL, NULL, 'light', 'breathing', 'بدون نیاز به تجهیزات', 'اگر احساس سرگیجه یا تنگی نفس کردید، تمرین را متوقف کنید و به طور عادی نفس بکشید. [citation:4]', 0, 0, '2026-08-05 14:39:13', '2026-08-05 14:39:13'),
(11, 'تمرینات تنفس برای زایمان (Lamaze)', 'تمرینات تنفس لاماز یکی از تکنیک‌های معروف برای مدیریت درد در حین زایمان است. این تمرینات شامل تنفس عمیق و کنترل‌شده همراه با تکنیک‌های آرام‌سازی است. [citation:4]', 'مدیریت درد زایمان، کاهش اضطراب، افزایش اکسیژن رسانی، بهبود کنترل ذهنی و جسمی، آمادگی برای زایمان طبیعی [citation:4]', 'در وضعیت راحت بنشینید. با شروع انقباض، عمیقاً نفس بکشید (تنفس پاک‌کننده). سپس به تنفس آرام و منظم (تنفس الگوی دار) ادامه دهید. با پایان انقباض، بازدم عمیق انجام دهید. [citation:4]', '۵-۱۰ دقیقه تمرین روزانه از سه‌ماهه سوم [citation:4]', 'third', 27, 40, 'light', 'breathing', 'بدون نیاز به تجهیزات', 'تمرینات را با همسر یا همراه خود تمرین کنید تا در حین زایمان بتوانند شما را راهنمایی کنند. [citation:4]', 0, 0, '2026-08-05 14:39:13', '2026-08-05 14:39:13'),
(12, 'پیلاتس بارداری', 'پیلاتس بر تقویت عضلات مرکزی بدن، بهبود تعادل و انعطاف‌پذیری تمرکز دارد. این ورزش در دوران بارداری به تقویت ستون فقرات، بهبود وضعیت بدن و کاهش کمردرد کمک می‌کند. [citation:1][citation:2][citation:4]', 'تقویت عضلات هسته بدن (Core)، بهبود تعادل، کاهش کمردرد، بهبود وضعیت بدن، آمادگی برای زایمان، بهبود کنترل ذهنی و جسمی [citation:1][citation:2]', 'تمرینات را روی تشک با تمرکز بر عضلات مرکزی (شکم، کمر، لگن) انجام دهید. از حرکات دراز کشیدن به پشت خودداری کنید. با تنفس عمیق همراه کنید. [citation:1][citation:2]', '۲۰-۳۰ دقیقه، ۲-۳ بار در هفته [citation:1]', 'first', 1, 12, 'moderate', 'strength', 'زیرانداز پیلاتس', 'از حرکات دراز کشیدن به پشت خودداری کنید. از حرکات چرخشی و کششی بیش از حد پرهیز کنید. [citation:1][citation:2]', 0, 1, '2026-08-05 14:39:13', '2026-08-05 14:39:13'),
(13, 'حرکات کششی سبک (روزانه)', 'حرکات کششی ساده و ملایم که به بهبود انعطاف‌پذیری و کاهش تنش عضلانی کمک می‌کند. در سه‌ماهه اول برای کاهش استرس و آماده‌سازی بدن مفید است. [citation:1][citation:5]', 'افزایش انعطاف‌پذیری، کاهش تنش عضلانی، بهبود گردش خون، کاهش خستگی و استرس، بهبود وضعیت بدن [citation:1][citation:5]', 'تمرینات کششی ملایم برای گردن، شانه‌ها، کمر و پاها انجام دهید. هر کشش را ۱۰-۱۵ ثانیه نگه دارید. از کشش‌های عمیق و ناگهانی خودداری کنید. [citation:1]', '۱۰-۱۵ دقیقه، روزانه [citation:1]', 'first', 1, 12, 'light', 'flexibility', 'بدون نیاز به تجهیزات', 'از کشش‌های عمیق و ناگهانی خودداری کنید. در صورت احساس درد، کشش را متوقف کنید. [citation:1]', 0, 0, '2026-08-05 14:39:13', '2026-08-05 14:39:13'),
(14, 'تمرینات با توپ یوگا (جیم بال)', 'ورزش با توپ یوگا به کاهش کمردرد، بهبود تعادل و آماده‌سازی لگن برای زایمان کمک می‌کند. نشستن و حرکت روی توپ باعث تقویت عضلات مرکزی و بهبود وضعیت بدن می‌شود. [citation:2][citation:3][citation:4]', 'کاهش کمردرد، بهبود جریان خون در ناحیه لگن و رحم، کاهش فشار روی پاها، تقویت عضلات مرکزی، آمادگی برای زایمان، افزایش انعطاف‌پذیری لگن [citation:2][citation:4]', 'روی توپ یوگا (به اندازه مناسب) بنشینید. پاها را به اندازه عرض شانه باز کنید. به آرامی حرکات چرخشی و نوسانی انجام دهید. از حرکات تعادلی ملایم استفاده کنید. [citation:2][citation:4]', '۱۰-۱۵ دقیقه، روزانه [citation:2]', 'second', 13, 26, 'light', 'flexibility', 'توپ یوگا (جیم بال)', 'برای حفظ تعادل، پاها را محکم روی زمین قرار دهید. از حرکات ناگهانی و چرخش‌های شدید خودداری کنید. [citation:2]', 0, 1, '2026-08-05 14:39:13', '2026-08-05 14:39:13'),
(15, 'تمرینات آمادگی برای زایمان', 'تمرینات ترکیبی شامل اسکات، تنفس عمیق و حرکات کششی لگن که به آمادگی جسمانی و ذهنی برای زایمان کمک می‌کند. این تمرینات در سه‌ماهه سوم اهمیت ویژه‌ای دارند. [citation:4][citation:5]', 'آمادگی برای زایمان، کاهش اضطراب، بهبود کنترل جسمانی، کاهش درد زایمان، افزایش اعتماد به نفس، بهبود وضعیت جنین [citation:4][citation:5]', 'ترکیبی از اسکات (با حمایت)، تمرینات تنفس لاماز، حرکات کششی لگن و تمرینات کگل را انجام دهید. هر تمرین را ۸-۱۰ بار تکرار کنید. [citation:2][citation:4]', '۱۵-۲۰ دقیقه، روزانه [citation:4]', 'third', 27, 40, 'moderate', 'flexibility', 'صندلی یا دیوار برای حمایت، زیرانداز یوگا', 'از انجام حرکاتی که نیاز به تعادل بالا دارند خودداری کنید. در صورت احساس درد یا فشار، تمرین را متوقف کنید. با پزشک خود مشورت کنید. [citation:4][citation:7]', 0, 1, '2026-08-05 14:39:13', '2026-08-05 14:39:13');

