--
-- Table structure for table `pregnancy_nutrition`
--

CREATE TABLE `pregnancy_nutrition` (
  `id` int(11) NOT NULL,
  `nutrient_name` varchar(100) NOT NULL,
  `benefits` text NOT NULL,
  `daily_requirement` varchar(100) NOT NULL,
  `food_sources` text NOT NULL,
  `supplement_advice` text DEFAULT NULL,
  `trimester` enum('first','second','third','all') NOT NULL,
  `week_start` int(11) NOT NULL COMMENT 'اولین هفته بارداری که این ماده مغذی مرتبط است (۱ تا ۴۰)',
  `week_end` int(11) NOT NULL COMMENT 'آخرین هفته بارداری که این ماده مغذی مرتبط است (۱ تا ۴۰)',
  `weeks_recommended` varchar(50) DEFAULT NULL COMMENT 'برچسب نمایشی، مثلاً: ۱-۱۲ یا کل دوران بارداری',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `pregnancy_nutrition`
