INSERT INTO `pregnancy_nutrition` (`id`, `nutrient_name`, `benefits`, `daily_requirement`, `food_sources`, `supplement_advice`, `trimester`, `week_start`, `week_end`, `weeks_recommended`, `created_at`, `updated_at`) VALUES
(1, 'اسید فولیک (ویتامین B9)', 'پیشگیری از نقص لوله عصبی در جنین (اسپینا بیفیدا و آنانسفالی)، تولید سلول‌های قرمز خون، رشد و تقسیم سلولی، کاهش خطر کم‌خونی در مادر', '۶۰۰ میکروگرم در روز (معادل ۴۰۰ میکروگرم اسید فولیک در مکمل‌ها)', 'سبزیجات برگ‌سبز تیره (اسفناج، کلم بروکلی، کاهو)، حبوبات (عدس، نخود، لوبیا)، مرکبات (پرتقال، لیمو)، موز، غلات غنی‌شده، نان و برنج غنی‌شده، آووکادو، جوانه گندم', 'مصرف اسید فولیک را حداقل یک ماه قبل از بارداری شروع کنید و تا پایان سه‌ماهه اول ادامه دهید. در صورت داشتن سابقه نقص لوله عصبی در بارداری‌های قبلی، با پزشک در مورد دوز بالاتر (تا ۴ میلی‌گرم در روز) مشورت کنید.', 'all', 1, 40, 'کل دوران بارداری (به‌ویژه هفته‌های ۱-۱۲)', '2026-08-06 11:06:31', '2026-08-06 11:06:31'),
(2, 'آهن (Iron)', 'پیشگیری از کم‌خونی فقر آهن در مادر، افزایش حجم خون، انتقال اکسیژن به جنین، کاهش خطر زایمان زودرس و وزن کم هنگام تولد، جلوگیری از خستگی و سرگیجه', '۲۷ میلی‌گرم در روز', 'گوشت قرمز بدون چربی، جگر، ماهی، مرغ، زرده تخم‌مرغ، اسفناج، لوبیا، عدس، نخود، غلات غنی‌شده با آهن، برگه زردآلو، خرما', 'برای جذب بهتر آهن، آن را همراه با ویتامین C (مثل آب پرتقال) مصرف کنید. از مصرف آهن همراه با کلسیم، چای و قهوه خودداری کنید (۲ ساعت فاصله دهید). در صورت مصرف مکمل آهن، ممکن است دچار یبوست شوید که با مصرف فیبر و مایعات قابل کنترل است.', 'all', 1, 40, 'کل دوران بارداری (نیاز در سه‌ماهه سوم بیشتر است)', '2026-08-06 11:06:31', '2026-08-06 11:06:31'),
(3, 'کلسیم (Calcium)', 'تشکیل استخوان‌ها و دندان‌های جنین، عملکرد صحیح عضلات و اعصاب، انعقاد خون، تنظیم فشار خون، پیشگیری از پوکی استخوان مادر', '۱٬۰۰۰ میلی‌گرم در روز', 'شیر و لبنیات کم‌چرب (ماست، پنیر)، ماهی‌های کنسروی با استخوان (ساردین، سالمون)، سبزیجات برگ‌سبز تیره (کلم پیچ، اسفناج)، توفو، بادام، کنجد، شیر سویا', '۸۰٪ کلسیم مورد نیاز جنین در سه‌ماهه سوم ذخیره می‌شود. در صورت عدم مصرف لبنیات، از مکمل کلسیم با مشورت پزشک استفاده کنید. کلسیم را همراه با آهن مصرف نکنید (حداقل ۲ ساعت فاصله).', 'all', 1, 40, 'کل دوران بارداری (نیاز در سه‌ماهه سوم بیشتر است)', '2026-08-06 11:06:31', '2026-08-06 11:06:31'),
(4, 'ویتامین D (Vitamin D)', 'جذب کلسیم و فسفر، رشد استخوان‌ها و دندان‌های جنین، تقویت سیستم ایمنی، کاهش خطر پره‌اکلامپسی، زایمان زودرس و وزن کم هنگام تولد', '۱۵ میکروگرم (۶۰۰ واحد بین‌المللی) در روز', 'نور خورشید (مهم‌ترین منبع)، ماهی‌های چرب (سالمون، ساردین، ماهی تن)، زرده تخم‌مرغ، شیر و غلات غنی‌شده با ویتامین D، جگر', 'در بسیاری از مناطق، دریافت کافی ویتامین D از طریق نور خورشید ممکن نیست. مصرف مکمل روزانه ۱۰ تا ۱۵ میکروگرم با مشورت پزشک توصیه می‌شود.', 'all', 1, 40, 'کل دوران بارداری', '2026-08-06 11:06:31', '2026-08-06 11:06:31'),
(5, 'پروتئین (Protein)', 'ساخت بافت‌ها و اندام‌های جنین (عضلات، استخوان‌ها، پوست، مو)، رشد جفت، افزایش حجم خون مادر، ساخت هورمون‌ها و آنزیم‌ها', '۷۱ گرم در روز', 'گوشت‌های کم‌چرب (مرغ، بوقلمون، گوشت قرمز بدون چربی)، ماهی، تخم‌مرغ، لبنیات، حبوبات (عدس، نخود، لوبیا)، سویا و توفو، مغزها و دانه‌ها، کینوا', 'پروتئین با کیفیت بالا از منابع حیوانی و گیاهی را در همه وعده‌های غذایی بگنجانید. مصرف روزانه ۲-۳ وعده پروتئین توصیه می‌شود.', 'all', 1, 40, 'کل دوران بارداری (نیاز در سه‌ماهه دوم و سوم بیشتر ', '2026-08-06 11:06:31', '2026-08-06 11:06:31'),
(6, 'امگا-۳ / ALA (اسیدهای چرب ضروری)', 'رشد مغز و چشم‌های جنین، بهبود عملکرد شناختی، کاهش خطر زایمان زودرس، کاهش التهاب، بهبود خلق‌وخوی مادر', 'حداقل ۱٫۴ گرم اسید آلفا-لینولنیک (ALA) در روز', 'گردو، تخم کتان، دانه چیا، سویا، روغن کانولا (این‌ها منبع ALA هستند؛ برای DHA/EPA به ردیف جداگانه «DHA» مراجعه کنید)', 'مصرف ۲-۳ وعده ماهی کم‌جیوه در هفته توصیه می‌شود. در صورت عدم مصرف ماهی، از مکمل امگا-۳ (DHA و EPA) با مشورت پزشک استفاده کنید.', 'all', 1, 40, 'کل دوران بارداری (به‌ویژه سه‌ماهه دوم و سوم)', '2026-08-06 11:06:31', '2026-08-06 11:06:31'),
(7, 'فیبر (Fiber)', 'پیشگیری و کاهش یبوست (شایع در بارداری به‌دلیل هورمون پروژسترون و فشار رحم)، کمک به کنترل قند خون، احساس سیری و کنترل افزایش وزن، سلامت روده', '۲۸ گرم در روز', 'حبوبات (عدس، نخود، لوبیا)، غلات کامل (جو دوسر، نان سبوس‌دار، برنج قهوه‌ای)، سبزیجات، میوه‌ها (به‌ویژه با پوست)، مغزها و دانه‌ها', 'فیبر را به‌تدریج افزایش دهید و همزمان مایعات کافی بنوشید تا از نفخ جلوگیری شود. مکمل فیبر معمولاً لازم نیست و باید ابتدا از منابع غذایی تأمین شود.', 'all', 1, 40, 'کل دوران بارداری (اهمیت بیشتر در سه‌ماهه دوم و سوم', '2026-08-06 11:06:31', '2026-08-06 11:06:31'),
(8, 'آب و مایعات (Water)', 'حفظ حجم خون و مایع آمنیوتیک، پیشگیری از یبوست و عفونت ادراری، تنظیم دمای بدن، کاهش خطر انقباضات زودرس ناشی از کم‌آبی', 'حدود ۳ لیتر مایعات در روز (تقریباً ۱۰-۱۲ لیوان، شامل آب، سوپ و میوه‌های آبدار)', 'آب ساده، دوغ کم‌نمک، سوپ و آش، میوه‌ها و سبزیجات آبدار (هندوانه، خیار، پرتقال)، شیر', 'مصرف کافئین را محدود کنید چون اثر ادرارآور دارد. اگر ورزش می‌کنید یا هوا گرم است، مایعات بیشتری بنوشید. رنگ ادرار روشن نشانه آب‌رسانی کافی است.', 'all', 1, 40, 'کل دوران بارداری', '2026-08-06 11:06:31', '2026-08-06 11:06:31'),
(9, 'ید (Iodine)', 'عملکرد صحیح غده تیروئید مادر، رشد مغز و سیستم عصبی جنین، جلوگیری از اختلالات رشد ذهنی و جسمی', '۲۲۰ میکروگرم در روز', 'ماهی و غذاهای دریایی، نمک یددار، لبنیات، تخم‌مرغ، جگر، غلات', 'از نمک یددار در پخت‌وپز استفاده کنید. در صورت کمبود ید، مکمل با مشورت پزشک مصرف شود.', 'first', 1, 12, '۱-۱۲', '2026-08-06 11:06:31', '2026-08-06 11:06:31'),
(10, 'روی (زینک - Zinc)', 'تقسیم سلولی و رشد جنین، تشکیل DNA و پروتئین‌ها، تقویت سیستم ایمنی، بهبود ترمیم بافت‌ها، کاهش خطر نقایص مادرزادی', '۱۱-۱۲ میلی‌گرم در روز', 'گوشت قرمز، مرغ، جگر، تخم‌مرغ، غذاهای دریایی (مخصوصاً صدف)، حبوبات، مغزها و دانه‌ها (تخم کدو)، غلات کامل', 'کمبود روی می‌تواند منجر به نقایص مادرزادی و تأخیر رشد شود. مصرف منابع غذایی غنی از روی در دوران بارداری ضروری است.', 'first', 1, 12, '۱-۱۲', '2026-08-06 11:06:31', '2026-08-06 11:06:31'),
(11, 'ویتامین B6 (پیریدوکسین)', 'کاهش تهوع صبحگاهی و استفراغ دوران بارداری، متابولیسم پروتئین و کربوهیدرات، تولید گلبول‌های قرمز', '۱٫۹ میلی‌گرم در روز', 'مرغ، ماهی، جگر، سیب‌زمینی، موز، حبوبات، غلات کامل، آووکادو، اسفناج', 'مصرف ویتامین B6 همراه با داکسی‌لامین، درمان استاندارد تهوع شدید بارداری است. در صورت تهوع شدید، با پزشک مشورت کنید.', 'first', 1, 12, '۱-۱۲', '2026-08-06 11:06:31', '2026-08-06 11:06:31'),
(12, 'ویتامین A', 'رشد چشم‌ها، اسکلت، پوست و سیستم ایمنی جنین در مراحل اولیه شکل‌گیری اندام‌ها؛ کمک به سلامت بینایی مادر', '۷۷۰ میکروگرم RAE در روز (حداکثر مجاز از منابع مکمل/گوشت جگر: ۳٬۰۰۰ میکروگرم در روز)', 'سبزیجات نارنجی و سبز تیره (هویج، سیب‌زمینی شیرین، اسفناج) به‌عنوان بتاکاروتن، زرده تخم‌مرغ، لبنیات', 'مصرف زیاد ویتامین A پیش‌ساخته (رتینول، به‌ویژه از جگر و مکمل‌های پرقدرت) در بارداری با نقص مادرزادی مرتبط است؛ از خوردن جگر به‌مقدار زیاد و مکمل‌های غیرضروری ویتامین A خودداری کنید. بتاکاروتن گیاهی خطر ندارد.', 'first', 1, 12, '۱-۱۲ (دوران شکل‌گیری اندام‌ها)', '2026-08-06 11:06:31', '2026-08-06 11:06:31'),
(13, 'منیزیم (Magnesium)', 'کاهش گرفتگی عضلات پا، بهبود کیفیت خواب، تنظیم فشار خون، عملکرد عصبی و عضلانی، سلامت استخوان‌ها و دندان‌ها', '۳۵۰-۳۶۰ میلی‌گرم در روز', 'سبزیجات برگ‌سبز (اسفناج، کلم)، مغزها (بادام، گردو)، دانه‌ها (تخم کدو)، حبوبات، غلات کامل، موز، آووکادو، شکلات تلخ', 'مصرف منیزیم می‌تواند به کاهش گرفتگی عضلات پا که در سه‌ماهه دوم شایع است، کمک کند.', 'second', 13, 26, '۱۳-۲۶', '2026-08-06 11:06:31', '2026-08-06 11:06:31'),
(14, 'ویتامین C (اسید اسکوربیک)', 'جذب بهتر آهن از غذا، تقویت سیستم ایمنی، ساخت کلاژن برای پوست، لثه و رگ‌های خونی، ترمیم بافت‌ها', '۸۰-۸۵ میلی‌گرم در روز', 'مرکبات (پرتقال، لیمو، گریپ‌فروت)، کیوی، توت‌فرنگی، فلفل دلمه‌ای، گوجه‌فرنگی، کلم بروکلی، انبه', 'برای جذب بهتر آهن، غذاهای غنی از آهن را همراه با منبع ویتامین C (مثل آب پرتقال) مصرف کنید.', 'second', 13, 26, '۱۳-۲۶', '2026-08-06 11:06:31', '2026-08-06 11:06:31'),
(15, 'سلنیوم (Selenium)', 'آنتی‌اکسیدان، حمایت از عملکرد تیروئید مادر و جنین، تقویت سیستم ایمنی، کاهش خطر برخی عوارض بارداری', '۶۰ میکروگرم در روز', 'آجیل برزیلی (فقط ۱-۲ عدد در روز کافی است چون بسیار غلیظ است)، غذاهای دریایی، گوشت، تخم‌مرغ، غلات کامل', 'از مصرف زیاد آجیل برزیلی خودداری کنید چون سطح سلنیوم می‌تواند به‌سرعت از حد مجاز عبور کند. مکمل جداگانه معمولاً لازم نیست.', 'second', 13, 26, '۱۳-۲۶', '2026-08-06 11:06:31', '2026-08-06 11:06:31'),
(16, 'ویتامین B12', 'رشد سیستم عصبی جنین، تولید گلبول‌های قرمز، عملکرد مغز، جلوگیری از کم‌خونی مگالوبلاستیک', '۲٫۶ میکروگرم در روز', 'گوشت، جگر، ماهی، تخم‌مرغ، شیر و لبنیات (منابع حیوانی)، غلات غنی‌شده (برای گیاه‌خواران)', 'گیاه‌خواران مطلق (وگان‌ها) در معرض کمبود ویتامین B12 هستند و باید حتماً از مکمل استفاده کنند. کمبود B12 می‌تواند بر رشد مغز جنین تأثیر بگذارد.', 'third', 27, 40, '۲۷-۴۰', '2026-08-06 11:06:31', '2026-08-06 11:06:31'),
(17, 'کولین (Choline)', 'رشد مغز و حافظه جنین، عملکرد کبد، انتقال پیام‌های عصبی، کاهش خطر نقایص لوله عصبی', '۴۵۰ میلی‌گرم در روز', 'زرده تخم‌مرغ، جگر، گوشت قرمز، ماهی، سویا، کلم بروکلی، گل‌کلم، جوانه گندم', 'کولین یک ماده مغذی ضروری است که بسیاری از زنان باردار به میزان کافی دریافت نمی‌کنند. مصرف تخم‌مرغ (به‌ویژه زرده) منبع خوبی است.', 'third', 27, 40, '۲۷-۴۰', '2026-08-06 11:06:31', '2026-08-06 11:06:31'),
(18, 'DHA (اسید دوکوزاهگزانوئیک)', 'رشد سریع مغز و شبکیه چشم جنین در دوران جهش رشدی مغز (رشد بیشتر مغز جنین در همین بازه رخ می‌دهد)، ممکن است به کاهش خطر زایمان زودرس کمک کند', 'حدود ۲۰۰-۳۰۰ میلی‌گرم در روز', 'ماهی‌های چرب کم‌جیوه (سالمون، ساردین، آنچوی، هرینگ)، تخم‌مرغ غنی‌شده با امگا-۳، جلبک دریایی (برای گیاه‌خواران)', 'اگر ماهی کافی مصرف نمی‌کنید، مکمل DHA (از روغن ماهی یا جلبک) با مشورت پزشک توصیه می‌شود؛ به‌ویژه در سه‌ماهه سوم که مغز جنین سریع‌ترین رشد را دارد.', 'third', 27, 40, '۲۷-۴۰ (رشد مغز)', '2026-08-06 11:06:31', '2026-08-06 11:06:31');

-- --------------------------------------------------------

--
-- Table structure for table `pregnancy_supplements`
--

CREATE TABLE `pregnancy_supplements` (
  `id` int(11) NOT NULL,
  `supplement_name` varchar(100) NOT NULL,
  `importance` text NOT NULL,
  `dosage` varchar(100) NOT NULL,
  `start_time` varchar(100) NOT NULL,
  `duration` varchar(100) NOT NULL,
  `precautions` text DEFAULT NULL,
  `week_start` int(11) DEFAULT NULL COMMENT 'شروع هفته مصرف مکمل (۱-۴۰)',
  `week_end` int(11) DEFAULT NULL COMMENT 'پایان هفته مصرف مکمل (۱-۴۰)',
  `trimester` enum('first','second','third','all') NOT NULL,
  `is_essential` tinyint(1) DEFAULT 1 COMMENT 'آیا مصرف آن ضروری است؟',
  `requires_prescription` tinyint(1) DEFAULT 0 COMMENT 'آیا فقط با تجویز/تشخیص پزشک مصرف شود؟',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `pregnancy_supplements`
--

INSERT INTO `pregnancy_supplements` (`id`, `supplement_name`, `importance`, `dosage`, `start_time`, `duration`, `precautions`, `week_start`, `week_end`, `trimester`, `is_essential`, `requires_prescription`, `created_at`, `updated_at`) VALUES
(1, 'اسید فولیک (Folic Acid)', '🌟 ضروری برای پیشگیری از نقص لوله عصبی در جنین. کمبود آن یکی از شایع‌ترین علل نقایص مادرزادی مانند اسپینا بیفیدا و آنانسفالی است. همچنین برای تولید سلول‌های خونی و رشد جنین حیاتی است.', '۴۰۰-۸۰۰ میکروگرم در روز (در صورت سابقه نقص لوله عصبی، تا ۴ میلی‌گرم در روز)', 'یک ماه قبل از بارداری (حداقل از هفته ۱ بارداری)', 'تا پایان هفته ۱۲ بارداری (بهترین زمان) و در برخی موارد تا پایان بارداری', '⚠️ مصرف بیش از حد (بیش از ۱ میلی‌گرم) ممکن است علائم کمبود ویتامین B12 را بپوشاند. بدون مشورت پزشک دوز را افزایش ندهید. بهترین زمان مصرف: همراه با غذا.', 1, 12, 'first', 1, 0, '2026-08-06 11:15:00', '2026-08-06 11:15:00'),
(2, 'مولتی‌ویتامین مخصوص بارداری', '🌟 تامین نیازهای تغذیه‌ای مادر و جنین شامل ویتامین‌ها و مواد معدنی ضروری. بهترین راه برای اطمینان از دریافت تمام ریزمغذی‌های مورد نیاز در دوران بارداری.', 'یک قرص در روز (ترجیحاً همراه با غذا)', 'از هفته ۱ بارداری (یا یک ماه قبل از بارداری)', 'تا پایان دوران بارداری و در صورت شیردهی، تا ۶ ماه پس از زایمان', '⚠️ از مصرف همزمان با مولتی‌ویتامین‌های دیگر خودداری کنید (خطر مصرف بیش از حد ویتامین A). مولتی‌ویتامین نباید بیش از ۳٬۰۰۰ میکروگرم (۱۰٬۰۰۰ واحد بین‌المللی) ویتامین A پیش‌ساخته داشته باشد. از مولتی‌ویتامین‌های مخصوص بارداری استفاده کنید.', 1, 40, 'all', 1, 0, '2026-08-06 11:15:00', '2026-08-06 11:15:00'),
(3, 'آهن (Iron)', '🌟 پیشگیری از کم‌خونی فقر آهن در مادر که می‌تواند منجر به خستگی، سرگیجه، زایمان زودرس و وزن کم هنگام تولد شود. نیاز به آهن در بارداری افزایش می‌یابد.', '۲۷-۳۰ میلی‌گرم در روز (معادل یک قرص آهن یا موجود در مولتی‌ویتامین)', 'از هفته ۱ بارداری (طبق توصیه ACOG)؛ در صورت تهوع شدید سه‌ماهه اول، می‌توان با نظر پزشک شروع را به هف', 'تا پایان دوران بارداری و حداقل ۳ ماه پس از زایمان', '⚠️ آهن را با معده خالی مصرف کنید (جذب بهتر) اما اگر باعث تهوع شد، همراه با غذا مصرف کنید. مصرف آهن همراه با کلسیم، چای و قهوه جذب را کاهش می‌دهد (حداقل ۲ ساعت فاصله). ممکن است باعث یبوست و مدفوع تیره شود. مصرف ویتامین C همراه با آهن جذب را افزایش می‌دهد.', 1, 40, 'all', 1, 0, '2026-08-06 11:15:00', '2026-08-06 11:15:00'),
(4, 'کلسیم (Calcium)', '🌟 تشکیل استخوان‌ها و دندان‌های جنین، عملکرد صحیح عضلات و اعصاب. ۸۰٪ کلسیم مورد نیاز جنین در سه‌ماهه سوم ذخیره می‌شود، اما نیاز مادر به کلسیم از همان ابتدای بارداری وجود دارد. کمبود آن می‌تواند به پوکی استخوان مادر منجر شود.', '۱٬۰۰۰-۱٬۳۰۰ میلی‌گرم در روز (اگر از لبنیات کافی استفاده نمی‌کنید)', 'از هفته ۱ بارداری', 'تا پایان بارداری (نیاز در سه‌ماهه سوم بیشتر است)', '⚠️ در صورت مصرف مکمل کلسیم، آن را همراه با غذا مصرف کنید. از مصرف همزمان کلسیم با آهن خودداری کنید (حداقل ۲ ساعت فاصله). دوز بالای کلسیم (بیش از ۲٬۵۰۰ میلی‌گرم در روز) ممکن است باعث سنگ کلیه شود.', 1, 40, 'all', 1, 0, '2026-08-06 11:15:00', '2026-08-06 11:15:00'),
(5, 'ویتامین D (Vitamin D)', '🌟 جذب کلسیم و فسفر، رشد استخوان‌ها و دندان‌های جنین، تقویت سیستم ایمنی، کاهش خطر پره‌اکلامپسی و زایمان زودرس.', '۶۰۰-۲٬۰۰۰ واحد بین‌المللی (۱۵-۵۰ میکروگرم) در روز', 'از هفته ۱ بارداری', 'تا پایان دوران بارداری و شیردهی', '⚠️ بهترین زمان مصرف همراه با وعده غذایی حاوی چربی (جذب بهتر). در صورت مصرف دوزهای بالا (بیش از ۴٬۰۰۰ واحد بین‌المللی در روز) حتماً با پزشک مشورت کنید.', 1, 40, 'all', 1, 0, '2026-08-06 11:15:00', '2026-08-06 11:15:00'),
(6, 'ید (Iodine)', '🌟 ضروری برای عملکرد صحیح غده تیروئید و رشد مغز جنین. کمبود ید یکی از علل اصلی اختلالات رشد ذهنی قابل‌پیشگیری در جهان است. حساس‌ترین دوره، سه‌ماهه اول (شکل‌گیری اولیه مغز) است، اما نیاز به ید تا پایان بارداری و شیردهی ادامه دارد.', '۱۵۰-۲۲۰ میکروگرم در روز', 'یک ماه قبل از بارداری (یا از هفته ۱ بارداری)', 'تا پایان دوران بارداری و شیردهی', '⚠️ مصرف بیش از حد ید (بیش از ۱٬۱۰۰ میکروگرم در روز) برای جنین مضر است. مکمل‌های حاوی ید را فقط با تجویز پزشک مصرف کنید. اگر از نمک یددار استفاده می‌کنید، ممکن است نیازی به مکمل نداشته باشید.', 1, 40, 'all', 1, 0, '2026-08-06 11:15:00', '2026-08-06 11:15:00'),
(7, 'ویتامین B6 (پیریدوکسین)', '⚠️ کاهش تهوع صبحگاهی و استفراغ دوران بارداری. مفید برای مادرانی که تهوع شدید دارند (hyperemesis gravidarum).', '۱۰-۲۵ میلی‌گرم ۳ بار در روز (مجموعاً ۳۰-۷۵ میلی‌گرم در روز)', 'از هفته ۴ بارداری (زمان شروع تهوع)', 'تا پایان سه‌ماهه اول (معمولاً تا هفته ۱۲-۱۴)', '⚠️ دوزهای بالا (بیش از ۱۰۰ میلی‌گرم در روز) می‌تواند باعث بی‌حسی و آسیب عصبی شود. همراه با داکسی‌لامین (تحت نظر پزشک) بهترین اثر را دارد. بهترین زمان مصرف: صبح ناشتا.', 4, 12, 'first', 0, 0, '2026-08-06 11:15:00', '2026-08-06 11:15:00'),
(8, 'زنجبیل (Ginger)', '⚠️ کاهش تهوع و استفراغ خفیف تا متوسط دوران بارداری (به‌ویژه سه‌ماهه اول)، بدون عوارض دارویی قابل‌توجه. گزینه‌ای طبیعی، جایگزین یا مکمل ویتامین B6.', '۲۵۰ میلی‌گرم، ۴ بار در روز (یا معادل آن به‌صورت چای/کپسول زنجبیل)', 'از هر زمانی که تهوع شروع شود (معمولاً هفته ۴-۶)', 'تا پایان سه‌ماهه اول یا تا زمانی که تهوع برطرف شود', '⚠️ در دوزهای بسیار بالا احتمال دارد خطر جزئی رقیق شدن خون را افزایش دهد؛ اگر داروی ضدانعقاد مصرف می‌کنید یا سابقه سقط/خونریزی دارید، حتماً قبل از مصرف با پزشک مشورت کنید.', 4, 12, 'first', 0, 0, '2026-08-06 11:15:00', '2026-08-06 11:15:00'),
(9, 'منیزیم (Magnesium)', '⚠️ کاهش گرفتگی عضلات پا و بهبود کیفیت خواب. مفید برای مادرانی که دچار گرفتگی عضلات، بی‌خوابی یا فشار خون بالا هستند.', '۲۰۰-۳۶۰ میلی‌گرم در روز (به صورت سیترات منیزیم یا گلیسینات برای جذب بهتر)', 'از هفته ۱۳ بارداری (با شروع سه‌ماهه دوم)', 'تا پایان دوران بارداری', '⚠️ دوزهای بالا (بیش از ۴۰۰ میلی‌گرم) ممکن است باعث اسهال شود. از مصرف منیزیم همراه با کلسیم یا آهن (۲ ساعت فاصله) خودداری کنید. قبل از مصرف با پزشک مشورت کنید.', 13, 40, 'second', 0, 0, '2026-08-06 11:15:00', '2026-08-06 11:15:00'),
(10, 'امگا-۳ (DHA و EPA)', '⚠️ رشد مغز و چشم‌های جنین، کاهش خطر زایمان زودرس، بهبود خلق و خوی مادر. DHA به ویژه برای رشد مغز در سه‌ماهه دوم و سوم حیاتی است.', '۲۰۰-۳۰۰ میلی‌گرم DHA + ۱۰۰-۲۰۰ میلی‌گرم EPA در روز (معادل ۱٬۰۰۰ میلی‌گرم روغن ماهی)', 'از هفته ۱۳ بارداری (یا از ابتدای بارداری)', 'تا پایان دوران بارداری و شیردهی', '⚠️ مکمل‌های روغن ماهی را از برندهای معتبر و فاقد جیوه انتخاب کنید. بهترین زمان مصرف همراه با غذا. اگر از رقیق‌کننده‌های خون استفاده می‌کنید، با پزشک مشورت کنید.', 13, 40, 'second', 0, 0, '2026-08-06 11:15:00', '2026-08-06 11:15:00'),
(11, 'آسپرین کم‌دوز (Low-dose Aspirin)', '⚠️ فقط برای مادران با ریسک بالای پره‌اکلامپسی (سابقه پره‌اکلامپسی، فشار خون مزمن، بارداری چندقلویی، دیابت، بیماری کلیوی و مشابه). طبق دستورالعمل ACOG/USPSTF خطر پره‌اکلامپسی، زایمان زودرس و محدودیت رشد جنین را کاهش می‌دهد.', '۸۱ میلی‌گرم در روز', 'بین هفته ۱۲ تا ۲۸ بارداری، ترجیحاً پیش از هفته ۱۶', 'مصرف روزانه تا زمان زایمان', '⚠️ فقط با تشخیص و تجویز پزشک مصرف شود؛ خودسرانه شروع نکنید. این یک دارو است نه یک مکمل تغذیه‌ای معمولی. قبل از هرگونه جراحی یا نزدیک زایمان با پزشک درباره ادامه یا قطع مصرف مشورت کنید.', 12, 40, 'second', 0, 1, '2026-08-06 11:15:00', '2026-08-06 11:15:00'),
(12, 'ویتامین B12', '⚠️ رشد سیستم عصبی جنین و تولید گلبول‌های قرمز. کمبود آن در گیاهخواران مطلق (وگان‌ها) شایع است و می‌تواند به تأخیر رشد مغز جنین منجر شود.', '۲٫۶-۳ میکروگرم در روز (در صورت کمبود، دوز بالاتر با تجویز پزشک)', 'از هفته ۲۷ بارداری (شروع سه‌ماهه سوم)', 'تا پایان دوران بارداری و شیردهی', '⚠️ گیاهخواران مطلق (وگان‌ها) حتماً باید مکمل B12 مصرف کنند. بهترین زمان مصرف: همراه با غذا. مصرف B12 با سایر ویتامین‌های گروه B مشکلی ندارد.', 27, 40, 'third', 0, 0, '2026-08-06 11:15:00', '2026-08-06 11:15:00'),
(13, 'کولین (Choline)', '⚠️ رشد مغز و حافظه جنین، عملکرد کبد و سیستم عصبی. یکی از مواد مغذی که بسیاری از زنان باردار به میزان کافی دریافت نمی‌کنند.', '۴۵۰ میلی‌گرم در روز', 'از هفته ۲۷ بارداری (شروع سه‌ماهه سوم)', 'تا پایان دوران بارداری و شیردهی', '⚠️ مصرف بیش از حد (بیش از ۳٬۵۰۰ میلی‌گرم در روز) ممکن است باعث افت فشار خون و بوی بدن شود. بهترین منابع غذایی: زرده تخم‌مرغ و جگر.', 27, 40, 'third', 0, 0, '2026-08-06 11:15:00', '2026-08-06 11:15:00'),
(14, 'پروبیوتیک (Probiotics)', '⚠️ بهبود عملکرد گوارش، کاهش یبوست، نفخ و سوزش سر دل. مفید برای مادرانی که مشکلات گوارشی دارند.', '۱۰-۲۰ میلیارد CFU در روز (با حداقل ۵ سویه مختلف)', 'در صورت نیاز و با مشورت پزشک (هر زمان از بارداری)', 'تا زمانی که علائم بهبود یابد یا تا پایان بارداری', '⚠️ از برندهای معتبر و فاقد مواد افزودنی استفاده کنید. بهترین زمان مصرف: همراه با غذا. در صورت داشتن نقص ایمنی، با پزشک مشورت کنید.', 1, 40, 'all', 0, 0, '2026-08-06 11:15:00', '2026-08-06 11:15:00'),
(15, 'روی (زینک - Zinc)', '⚠️ تقسیم سلولی و رشد جنین، تقویت سیستم ایمنی، بهبود ترمیم بافت‌ها. کمبود روی می‌تواند منجر به نقایص مادرزادی شود.', '۱۱-۱۵ میلی‌گرم در روز', 'در صورت کمبود (با تجویز پزشک) از هفته ۱ بارداری', 'تا پایان سه‌ماهه اول (یا با تجویز پزشک تا پایان بارداری)', '⚠️ مصرف همزمان روی با آهن و کلسیم جذب را کاهش می‌دهد (۲ ساعت فاصله). مصرف روی با معده خالی ممکن است باعث تهوع شود، همراه با غذا مصرف کنید.', 1, 12, 'first', 0, 0, '2026-08-06 11:15:00', '2026-08-06 11:15:00');

-- --------------------------------------------------------

--
-- Table structure for table `pregnancy_warning_signs`
--

CREATE TABLE `pregnancy_warning_signs` (
  `id` int(11) NOT NULL,
  `symptom_name` varchar(150) NOT NULL,
  `description` text NOT NULL,
  `possible_causes` text DEFAULT NULL,
  `action_required` text NOT NULL,
  `urgency_level` enum('emergency','urgent','important','informational') NOT NULL,
  `category` enum('bleeding','pain','headache_vision','swelling','fever','digestive','movement','urinary','respiratory','psychological','other') NOT NULL,
  `trimester` enum('first','second','third','all') NOT NULL,
  `week_start` int(11) DEFAULT NULL COMMENT 'شروع هفته (۱-۴۰)',
  `week_end` int(11) DEFAULT NULL COMMENT 'پایان هفته (۱-۴۰)',
  `immediate_action` tinyint(1) DEFAULT 1 COMMENT 'آیا نیاز به اقدام فوری دارد؟',
  `call_doctor` tinyint(1) DEFAULT 1 COMMENT 'آیا باید با پزشک تماس گرفت؟',
  `go_to_hospital` tinyint(1) DEFAULT 0 COMMENT 'آیا باید به بیمارستان مراجعه کرد؟',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `pregnancy_warning_signs`
--

INSERT INTO `pregnancy_warning_signs` (`id`, `symptom_name`, `description`, `possible_causes`, `action_required`, `urgency_level`, `category`, `trimester`, `week_start`, `week_end`, `immediate_action`, `call_doctor`, `go_to_hospital`, `created_at`, `updated_at`) VALUES
(1, 'خونریزی شدید واژینال', 'خونریزی که سنگین‌تر از یک پریود معمولی باشد، همراه با لخته‌های خونی بزرگ یا نیاز به تعویض نوار بهداشتی هر ۱-۲ ساعت. خونریزی می‌تواند قرمز روشن یا تیره با لخته باشد.', 'ممکن است نشانه‌ای از سقط جنین، جفت‌سرراهی (در سه‌ماهه دوم و سوم)، جدا شدن جفت، پارگی رحم یا حاملگی خارج از رحم باشد.', '🚨 فوراً با اورژانس (۱۱۵) تماس بگیرید و به نزدیک‌ترین بیمارستان مراجعه کنید. تا رسیدن به بیمارستان، دراز بکشید و از حرکت خودداری کنید. چیزی از طریق واژن وارد نکنید. از بلند کردن اجسام سنگین خودداری کنید.', 'emergency', 'bleeding', 'all', 1, 40, 1, 1, 1, '2026-08-05 14:26:41', '2026-08-05 14:26:41'),
(2, 'پاره شدن کیسه آب (نشت مایع)', 'خروج ناگهانی یا نشت مداوم مایع شفاف یا زرد رنگ از واژن که قابل کنترل نیست. ممکن است به صورت یک جریان ناگهانی یا نشت آهسته و مداوم باشد. مایع ممکن است حاوی ذرات سفید رنگ (ورنیکس) باشد.', 'نشانه شروع زایمان است. اگر قبل از هفته ۳۷ باشد، زایمان زودرس محسوب می‌شود و نیاز به مراقبت ویژه دارد.', '🚨 فوراً به پزشک خود اطلاع دهید و به بیمارستان مراجعه کنید. رنگ مایع را بررسی کنید (شفاف، سبز یا قهوه‌ای). از رابطه جنسی خودداری کنید. از وارد کردن چیزی به واژن خودداری کنید. اگر مایع سبز یا قهوه‌ای است، فوراً به اورژانس مراجعه کنید.', 'emergency', 'urinary', 'all', 1, 40, 1, 1, 1, '2026-08-05 14:26:41', '2026-08-05 14:26:41'),
(3, 'کاهش شدید یا قطع حرکات جنین', 'کاهش قابل توجه در تعداد یا شدت حرکات جنین (کمتر از ۱۰ حرکت در ۲ ساعت). اگر بیش از ۱۲ ساعت حرکتی احساس نمی‌کنید، بسیار خطرناک است.', 'می‌تواند نشانه ناراحتی جنین، کاهش اکسیژن رسانی، مشکلات جفت یا بند ناف باشد.', '🚨 فوراً با پزشک تماس بگیرید و به بیمارستان مراجعه کنید. تا رسیدن به بیمارستان، به پهلوی چپ بخوابید و مایعات شیرین (آب میوه) بنوشید. حرکات را بشمارید. اگر بعد از ۲ ساعت کمتر از ۱۰ حرکت بود، اورژانسی اقدام کنید.', 'emergency', 'movement', 'third', 27, 40, 1, 1, 1, '2026-08-05 14:26:41', '2026-08-05 14:26:41'),
(4, 'درد شدید و ناگهانی شکم', 'درد شدید، تیز و ناگهانی در ناحیه شکم که با استراحت بهبود نمی‌یابد. درد ممکن است مداوم یا به صورت موجی باشد و با علائمی مانند تهوع، استفراغ، تب یا خونریزی همراه باشد.', 'می‌تواند نشانه جدا شدن جفت، پارگی رحم، آپاندیسیت، سنگ کلیه، کیسه صفرا یا مشکلات گوارشی باشد.', '🚨 فوراً با اورژانس تماس بگیرید و به بیمارستان مراجعه کنید. تا رسیدن به بیمارستان، دراز بکشید و از مصرف هرگونه داروی مسکن خودداری کنید (تشخیص را سخت می‌کند). چیزی نخورید و ننوشید (به جز آب).', 'emergency', 'pain', 'all', 1, 40, 1, 1, 1, '2026-08-05 14:26:41', '2026-08-05 14:26:41'),
(5, 'تشنج یا بیهوشی', 'گرفتگی و انقباضات غیرارادی عضلات، از دست دادن هوشیاری، خیره شدن، یا حرکات کنترل‌نشده بدن. ممکن است با کف کردن دهان یا به هم فشردن دندان‌ها همراه باشد.', 'می‌تواند نشانه پره‌اکلامپسی شدید یا اکلامپسی باشد. اورژانس پزشکی جدی است.', '🚨 فوراً با اورژانس (۱۱۵) تماس بگیرید. بیمار را به پهلو بخوابانید تا در صورت استفراغ، خفه نشود. چیزی در دهان بیمار قرار ندهید. پس از پایان تشنج، بررسی کنید که تنفس دارد. تا رسیدن آمبولانس، بیمار را تنها نگذارید.', 'emergency', 'other', 'all', 1, 40, 1, 1, 1, '2026-08-05 14:26:41', '2026-08-05 14:26:41'),
(6, 'سردرد شدید همراه با تاری دید', 'سردرد شدید و مداوم که با استراحت و مسکن بهبود نمی‌یابد، همراه با تاری دید، دیدن نقاط نورانی، دوبینی یا کاهش ناگهانی دید.', 'می‌تواند نشانه پره‌اکلامپسی (فشار خون بالا در بارداری) یا مشکلات مغزی باشد.', '🚨 فوراً به پزشک خود اطلاع دهید و به بیمارستان مراجعه کنید. فشار خون خود را اندازه‌گیری کنید (اگر بالای ۱۴۰/۹۰ بود، اورژانسی است). از رانندگی خودداری کنید.', 'emergency', 'headache_vision', 'all', 1, 40, 1, 1, 1, '2026-08-05 14:26:41', '2026-08-05 14:26:41'),
(7, 'تهوع و استفراغ شدید', 'استفراغ مکرر (بیش از ۳-۴ بار در روز) که باعث عدم تحمل غذا و مایعات، کاهش وزن و دهیدراتاسیون می‌شود. ممکن است با سرگیجه، ضعف و کاهش ادرار همراه باشد.', 'شایع‌ترین علت، تهوع صبحگاهی شدید (hyperemesis gravidarum) است. همچنین می‌تواند نشانه مسمومیت غذایی، عفونت یا مشکلات کبدی باشد.', '⚠️ به پزشک خود اطلاع دهید. مایعات کافی (آب، محلول ORS) بنوشید. وعده‌های غذایی کوچک و مکرر مصرف کنید. اگر نمی‌توانید مایعات را نگه دارید، به پزشک مراجعه کنید. در صورت دهیدراتاسیون شدید، نیاز به بستری و سرم درمانی است.', 'urgent', 'digestive', 'first', 4, 14, 0, 1, 0, '2026-08-05 14:26:41', '2026-08-05 14:26:41'),
(8, 'تب بالا (بیش از ۳۸.۵ درجه سانتی‌گراد)', 'دمای بدن بالای ۳۸.۵ درجه سانتی‌گراد که با استراحت کاهش نمی‌یابد. ممکن است با لرز، تعریق، درد عضلانی و ضعف همراه باشد.', 'می‌تواند نشانه عفونت (ادرار، تنفسی، گوارشی) یا آنفلوآنزا باشد. تب بالا در بارداری می‌تواند برای جنین خطرناک باشد.', '⚠️ به پزشک خود اطلاع دهید. از استامینوفن (با مشورت پزشک) برای کاهش تب استفاده کنید. از ایبوپروفن و آسپرین خودداری کنید. مایعات کافی بنوشید. اگر تب با علائم دیگری مانند درد یا خونریزی همراه بود، اورژانسی اقدام کنید.', 'urgent', 'fever', 'all', 1, 40, 0, 1, 0, '2026-08-05 14:26:41', '2026-08-05 14:26:41'),
(9, 'تورم ناگهانی و شدید دست، پا و صورت', 'افزایش ناگهانی و شدید تورم در دست‌ها، پاها، مچ پاها یا صورت که با استراحت بهبود نمی‌یابد. ممکن است با افزایش وزن ناگهانی (بیش از ۱ کیلوگرم در هفته) همراه باشد.', 'شایع‌ترین علت، پره‌اکلامپسی است. همچنین می‌تواند نشانه مشکلات کلیوی، فشار خون بالا یا احتباس مایعات باشد.', '⚠️ فوراً به پزشک خود اطلاع دهید. فشار خون خود را اندازه‌گیری کنید. پاهای خود را بالا قرار دهید. مصرف نمک را کاهش دهید. اگر با سردرد یا تاری دید همراه بود، اورژانسی است.', 'urgent', 'swelling', 'third', 27, 40, 0, 1, 0, '2026-08-05 14:26:41', '2026-08-05 14:26:41'),
(10, 'فشار خون بالا (بیش از ۱۴۰/۹۰ میلی‌متر جیوه)', 'فشار خون سیستولیک بالای ۱۴۰ یا دیاستولیک بالای ۹۰ میلی‌متر جیوه که در دو نوبت با فاصله ۴ ساعت اندازه‌گیری شود.', 'می‌تواند نشانه پره‌اکلامپسی یا فشار خون مزمن باشد. خطر جدی برای مادر و جنین دارد.', '⚠️ فوراً به پزشک خود اطلاع دهید. اگر همراه با سردرد، تاری دید یا درد بالای شکم بود، به اورژانس مراجعه کنید. استراحت کنید و از مصرف نمک خودداری کنید. فشار خون را مرتباً اندازه‌گیری کنید.', 'urgent', 'other', 'all', 1, 40, 0, 1, 0, '2026-08-05 14:26:41', '2026-08-05 14:26:41'),
(11, 'درد یا سوزش هنگام ادرار', 'احساس درد، سوزش یا ناراحتی هنگام دفع ادرار. ممکن است با تکرر ادرار، احساس دفع ناقص، ادرار تیره یا بدبو همراه باشد.', 'شایع‌ترین علت، عفونت ادراری است که در بارداری شایع است و می‌تواند به کلیه‌ها صعود کند.', '⚠️ به پزشک خود اطلاع دهید. مایعات کافی (آب و آب کرنبری) بنوشید. تا زمان مراجعه به پزشک، از مصرف خودسرانه آنتی‌بیوتیک خودداری کنید. آزمایش ادرار دهید.', 'urgent', 'urinary', 'all', 1, 40, 0, 1, 0, '2026-08-05 14:26:41', '2026-08-05 14:26:41'),
(12, 'درد شدید ناحیه لگن یا زیر شکم', 'درد مداوم یا متناوب در ناحیه لگن، زیر شکم یا کشاله ران که با استراحت بهبود نمی‌یابد. ممکن است با فشار یا سنگینی همراه باشد.', 'می‌تواند نشانه زایمان زودرس، اتساع دهانه رحم، عفونت، فیبروم یا مشکلات روده باشد.', '⚠️ به پزشک خود اطلاع دهید. اگر قبل از هفته ۳۷ است، خطر زایمان زودرس وجود دارد. استراحت کنید و از فعالیت خودداری کنید. اگر با خونریزی یا ترشحات همراه بود، اورژانسی است.', 'urgent', 'pain', 'second', 13, 26, 0, 1, 0, '2026-08-05 14:26:41', '2026-08-05 14:26:41'),
(13, 'خونریزی خفیف یا لکه‌بینی', 'خونریزی بسیار خفیف به صورت لکه‌بینی (نقاط کوچک خون روی لباس زیر یا هنگام دستمال کشیدن) که بدون درد و بدون لخته است. معمولاً قرمز روشن یا قهوه‌ای است.', 'می‌تواند نشانه لانه‌گزینی (هفته ۴)، تغییرات دهانه رحم، عفونت یا در برخی موارد خطر سقط باشد.', '📌 به پزشک خود اطلاع دهید. استراحت کنید و از فعالیت خودداری کنید. اگر خونریزی شدیدتر شد یا با درد همراه شد، فوراً به پزشک مراجعه کنید.', 'important', 'bleeding', 'first', 1, 12, 0, 1, 0, '2026-08-05 14:26:41', '2026-08-05 14:26:41'),
(14, 'خارش شدید بدن (بدون جوش)', 'خارش شدید و منتشر در بدن (به ویژه کف دست و پا) که بدون جوش یا بثورات پوستی است. خارش ممکن است شب‌ها بدتر شود.', 'می‌تواند نشانه کلستاز بارداری (اختلال کبدی) باشد که نیاز به بررسی دارد.', '📌 به پزشک خود اطلاع دهید. آزمایش خون (اسیدهای صفراوی و آنزیم‌های کبدی) انجام دهید. از کرم‌های مرطوب‌کننده و ضدخارش استفاده کنید. از حمام آب داغ خودداری کنید.', 'important', 'other', 'third', 27, 40, 0, 1, 0, '2026-08-05 14:26:41', '2026-08-05 14:26:41'),
(15, 'ترشحات واژینال غیرعادی', 'ترشحات واژینال که رنگ، بو یا قوام آن تغییر کرده است. ممکن است به صورت ترشحات زرد، سبز، خاکستری، پنیری یا بدبو باشد. همراه با خارش یا سوزش باشد.', 'می‌تواند نشانه عفونت واژینال (قارچی، باکتریایی یا تریکومونیاز) باشد که در بارداری شایع است.', '📌 به پزشک خود اطلاع دهید. از بهداشت شخصی رعایت کنید. از شوینده‌های معطر و لباس زیر تنگ خودداری کنید. درمان عفونت در بارداری مهم است.', 'important', 'other', 'all', 1, 40, 0, 1, 0, '2026-08-05 14:26:41', '2026-08-05 14:26:41'),
(16, 'یبوست شدید و بواسیر', 'یبوست شدید همراه با دفع سخت و دردناک مدفوع، همراه با خونریزی خفیف هنگام دفع یا توده‌های متورم در ناحیه مقعد (بواسیر).', 'یبوست شایع‌ترین مشکل گوارشی در بارداری است. بواسیر در اثر فشار به رگ‌های مقعد ایجاد می‌شود.', '📌 فیبر بیشتر (میوه، سبزیجات، غلات کامل) و مایعات کافی مصرف کنید. از نشستن طولانی مدت خودداری کنید. در صورت بواسیر، از پمادهای موضعی با مشورت پزشک استفاده کنید.', 'important', 'digestive', 'all', 1, 40, 0, 0, 0, '2026-08-05 14:26:41', '2026-08-05 14:26:41'),
(17, 'تهوع صبحگاهی معمولی', 'تهوع خفیف تا متوسط که معمولاً در صبح بدتر می‌شود اما می‌تواند در طول روز نیز باشد. معمولاً بدون استفراغ یا با استفراغ خفیف همراه است و با غذا خوردن بهبود می‌یابد.', 'ناشی از تغییرات هورمونی (افزایش hCG و استروژن) در سه‌ماهه اول بارداری است.', 'ℹ️ وعده‌های غذایی کوچک و مکرر مصرف کنید. صبح قبل از بلند شدن از رختخواب بیسکویت یا کراکر بخورید. از غذاهای چرب و ادویه‌دار خودداری کنید. مایعات کافی بنوشید.', 'informational', 'digestive', 'first', 4, 12, 0, 0, 0, '2026-08-05 14:26:41', '2026-08-05 14:26:41'),
(18, 'درد خفیف کمر', 'درد خفیف تا متوسط در ناحیه کمر که با استراحت، تغییر وضعیت و کمپرس گرم بهبود می‌یابد. بدون علائم هشداردهنده مانند خونریزی یا تب.', 'در اثر افزایش وزن، تغییر مرکز ثقل، شل شدن مفاصل (به دلیل هورمون ریلکسین) و فشار بر عضلات کمر ایجاد می‌شود.', 'ℹ️ از بالشتک کمری استفاده کنید. هنگام نشستن صاف بنشینید. از کفش راحت استفاده کنید. کمپرس گرم روی ناحیه کمر قرار دهید. ورزش‌های سبک (پیاده‌روی، یوگا) انجام دهید.', 'informational', 'pain', 'all', 1, 40, 0, 0, 0, '2026-08-05 14:26:41', '2026-08-05 14:26:41'),
(19, 'گرفتگی خفیف عضلات پا', 'انقباضات ناگهانی و دردناک در عضلات ساق پا، معمولاً در شب یا هنگام دراز کشیدن اتفاق می‌افتد.', 'در اثر تغییرات گردش خون، افزایش وزن و کمبود منیزیم یا کلسیم ایجاد می‌شود.', 'ℹ️ عضلات ساق پا را به آرامی کشش دهید. از کمپرس گرم استفاده کنید. مصرف منیزیم و کلسیم را افزایش دهید. مایعات کافی بنوشید. قبل از خواب پاها را ماساژ دهید.', 'informational', 'pain', 'second', 13, 26, 0, 0, 0, '2026-08-05 14:26:41', '2026-08-05 14:26:41'),
(20, 'احتقان بینی', 'گرفتگی یا خشکی بینی، خونریزی خفیف بینی یا احساس فشار در سینوس‌ها.', 'در اثر افزایش حجم خون و تغییرات هورمونی (افزایش استروژن) ایجاد می‌شود که باعث تورم مخاط بینی می‌شود.', 'ℹ️ از اسپری آب نمک استفاده کنید. رطوبت محیط را افزایش دهید (دستگاه بخور). مایعات کافی بنوشید. از داروهای ضداحتقان خودداری کنید.', 'informational', 'respiratory', 'all', 1, 40, 0, 0, 0, '2026-08-05 14:26:41', '2026-08-05 14:26:41'),
(21, 'انقباضات براکستون هیکس (تمرینی)', 'انقباضات خفیف و نامنظم در عضلات رحم که معمولاً بدون درد هستند و با تغییر وضعیت بهبود می‌یابند. دیواره شکم سفت می‌شود و سپس شل می‌شود.', 'انقباضات تمرینی طبیعی رحم هستند که بدن را برای زایمان آماده می‌کنند.', 'ℹ️ این انقباضات طبیعی هستند. اگر منظم و دردناک شدند یا با خونریزی همراه شدند، به پزشک اطلاع دهید. استراحت کنید و مایعات بنوشید.', 'informational', 'pain', 'third', 27, 40, 0, 0, 0, '2026-08-05 14:26:41', '2026-08-05 14:26:41'),
(22, 'نوسانات خلقی و اضطراب', 'تغییرات ناگهانی در خلق و خو، احساس غمگینی، اضطراب، تحریک‌پذیری یا نگرانی بیش از حد.', 'در اثر تغییرات هورمونی، تغییرات جسمی، نگرانی‌های مربوط به زایمان و نقش جدید مادری ایجاد می‌شود.', 'ℹ️ با همسر، خانواده و دوستان خود صحبت کنید. از تکنیک‌های آرام‌سازی (تنفس عمیق، مدیتیشن) استفاده کنید. ورزش منظم انجام دهید. اگر علائم شدید یا پایدار بود، با پزشک مشورت کنید.', 'informational', 'psychological', 'all', 1, 40, 0, 0, 0, '2026-08-05 14:26:41', '2026-08-05 14:26:41');

