--
-- Table structure for table `pregnancy_weeks`
--

CREATE TABLE `pregnancy_weeks` (
  `id` int(11) NOT NULL,
  `week_number` int(11) NOT NULL,
  `fetus_size_comparison` varchar(100) DEFAULT NULL,
  `fetus_length_cm` decimal(5,2) DEFAULT NULL,
  `fetus_weight_g` decimal(6,2) DEFAULT NULL,
  `development_description` text DEFAULT NULL,
  `mother_changes` text DEFAULT NULL,
  `medical_tips` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `pregnancy_weeks`
--

INSERT INTO `pregnancy_weeks` (`id`, `week_number`, `fetus_size_comparison`, `fetus_length_cm`, `fetus_weight_g`, `development_description`, `mother_changes`, `medical_tips`, `created_at`, `updated_at`) VALUES
(1, 1, 'غیرقابل اندازه‌گیری', NULL, NULL, 'در این هفته، آخرین دوره قاعدگی شما اتفاق می‌افتد. بدن شما در حال آماده‌سازی برای تخمک‌گذاری است. هنوز بارداری اتفاق نیفتاده است.', 'خونریزی قاعدگی، گرفتگی خفیف، خستگی، نوسانات هورمونی', 'رژیم غذایی سالم داشته باشید، مصرف اسید فولیک را شروع کنید، از مصرف الکل و سیگار خودداری کنید.', '2026-08-05 13:52:19', '2026-08-05 13:52:19'),
(2, 2, 'غیرقابل اندازه‌گیری', NULL, NULL, 'تخمک‌گذاری اتفاق می‌افتد و تخمک آزاد می‌شود. لقاح توسط اسپرم در این هفته یا اوایل هفته بعد انجام می‌شود. سلول‌ها شروع به تقسیم می‌کنند.', 'افزایش دمای پایه بدن، ترشحات واژینال شفاف و کشسان، درد خفیف در ناحیه تخمدان', 'برای افزایش شانس بارداری، زمان تخمک‌گذاری را دقیق کنید. مصرف اسید فولیک را ادامه دهید.', '2026-08-05 13:52:19', '2026-08-05 13:52:19'),
(3, 3, 'غیرقابل اندازه‌گیری', NULL, NULL, 'لقاح رخ داده است. زیگوت (تخم بارور شده) شروع به تقسیم و حرکت به سمت رحم می‌کند. بلاستوسیست حدود ۳-۴ روز پس از لقاح به رحم می‌رسد و لانه‌گزینی حدود روز ۶-۱۰ پس از لقاح شروع می‌شود.', 'خستگی، نفخ، گرفتگی خفیف (مشابه قاعدگی)، لکه‌بینی خفیف (خونریزی لانه‌گزینی)', 'به مصرف اسید فولیک ادامه دهید. از استرس دوری کنید. رژیم غذایی متعادل داشته باشید.', '2026-08-05 13:52:19', '2026-08-05 13:52:19'),
(4, 4, 'اندازه یک دانه خشخاش', 0.10, 1.00, 'لانه‌گزینی کامل شده است. لوله عصبی (که بعداً مغز و نخاع می‌شود) شروع به شکل‌گیری می‌کند. سلول‌های اولیه به سه لایه مجزا تقسیم می‌شوند که هر کدام به بخش‌های مختلف بدن تبدیل می‌شوند. قلب و سیستم گردش خون شروع به تشکیل می‌کنند.', 'خستگی شدید، تهوع خفیف، حساسیت و تورم سینه‌ها، تکرر ادرار، نفخ، نوسانات خلقی', 'آزمایش بارداری خانگی را انجام دهید. اگر مثبت شد، برای تأیید و شروع مراقبت‌های دوران بارداری به پزشک مراجعه کنید. مصرف اسید فولیک (۴۰۰ میکروگرم در روز) را ادامه دهید.', '2026-08-05 13:52:19', '2026-08-05 13:52:19'),
(5, 5, 'اندازه یک دانه فلفل یا دانه کنجد', 0.15, 1.00, 'شروع دوره رویان (Embryonic Period). لوله عصبی در حال بسته شدن است. قلب اولیه شروع به تپیدن می‌کند (اگرچه با سونوگرافی قابل مشاهده نیست). جوانه‌های اولیه دست و پا ظاهر می‌شوند. کیسه زرده در حال تولید خون است.', 'تهوع صبحگاهی (تهوع و استفراغ)، خستگی مفرط، بیزاری از بوهای خاص، تکرر ادرار، حساسیت شدید سینه‌ها، افزایش حس بویایی', 'وعده‌های غذایی کوچک و مکرر برای کاهش تهوع مصرف کنید. مایعات کافی بنوشید. از مصرف داروهای خودسرانه پرهیز کنید. مصرف اسید فولیک را ادامه دهید.', '2026-08-05 13:52:19', '2026-08-05 13:52:19'),
(6, 6, 'اندازه یک دانه انار یا نخود', 0.60, 1.00, 'تشکیل حفره‌های قلبی و ضربان قلب قابل تشخیص با سونوگرافی (حدود ۱۰۰-۱۶۰ ضربه در دقیقه). گوش، چشم و دهان در حال شکل‌گیری هستند. کلیه‌ها و ریه‌ها شروع به رشد می‌کنند. جریان خون در رگ‌های اصلی برقرار شده است. بازوها و پاها مانند پاروهای کوچک دیده می‌شوند.', 'تهوع شدیدتر، استفراغ، خستگی، نوسانات خلقی شدید، ادرار مکرر، حساسیت به بو، افزایش ترشحات واژینال', 'برای کاهش تهوع، صبح ها قبل از بلند شدن از رختخواب یک بیسکویت یا کراکر میل کنید. از غذاهای چرب و ادویه‌دار پرهیز کنید. ویتامین B6 می‌تواند به کاهش تهوع کمک کند (با مشورت پزشک).', '2026-08-05 13:52:19', '2026-08-05 13:52:19'),
(7, 7, 'اندازه یک بلوبری یا زغال‌اخته', 1.00, 1.00, 'مغز به سرعت در حال رشد است و به دو نیمکره تقسیم می‌شود. صورت در حال شکل‌گیری واضح‌تر است (چشم‌ها، گوش‌ها و بینی قابل تشخیص‌تر). بند ناف کامل شده و مواد مغذی را منتقل می‌کند. کبد شروع به تولید سلول‌های خونی می‌کند. دم کوچک (دنبالچه) در حال ناپدید شدن است.', 'علائم بارداری به اوج خود می‌رسد (تهوع، استفراغ، خستگی). آکنه و تغییرات پوستی. یبوست، نفخ، افزایش بزاق دهان، نوسانات خلقی', 'برای یبوست، فیبر و مایعات بیشتر مصرف کنید. از خوردن غذاهای نفاخ پرهیز کنید. اگر استفراغ شدید دارید (بیش از ۳-۴ بار در روز) حتماً به پزشک مراجعه کنید.', '2026-08-05 13:52:19', '2026-08-05 13:52:19'),
(8, 8, 'اندازه یک لوبیا کرنبری یا انگور', 1.60, 1.00, 'تمام اندام‌های اصلی شروع به تشکیل کرده‌اند. استخوان‌ها شروع به سفت شدن (استخوانی شدن) می‌کنند. انگشتان دست و پا تشکیل شده‌اند اما به هم چسبیده هستند. پلک‌ها شروع به پوشاندن چشم‌ها می‌کنند. گوش‌های داخلی و خارجی در حال رشد هستند. رشد سریع مغز ادامه دارد.', 'خستگی شدید، تهوع و استفراغ، سوزش سر دل، نفخ و یبوست، ترشحات واژینال، تغییرات خلقی، افزایش وزن خفیف', 'استراحت کافی داشته باشید. از وعده‌های غذایی کوچک استفاده کنید. از مصرف کافئین خودداری کنید. سونوگرافی در این هفته می‌تواند ضربان قلب جنین را نشان دهد.', '2026-08-05 13:52:19', '2026-08-05 13:52:19'),
(9, 9, 'اندازه یک گیلاس یا انگور', 2.30, 2.00, 'پلک‌ها و گوش‌های خارجی در حال رشد هستند. دندان‌های شیری شروع به رشد در زیر لثه می‌کنند. کلیه‌ها شروع به کار کرده و ادرار تولید می‌کنند. ماهیچه‌های اندام در حال رشد و هماهنگ‌تر می‌شوند. نوزاد می‌تواند سر خود را حرکت دهد. ضربان قلب به ۱۴۰-۱۷۰ ضربه در دقیقه رسیده است.', 'سوزش سر دل، نفخ، خستگی، تکرر ادرار، افزایش اشتها، شروع نمایان شدن شکم (در برخی افراد)، واریس خفیف', 'برای سوزش سر دل، از خوردن غذاهای چرب و اسیدی پرهیز کنید و دراز نکشید. مصرف مایعات کافی داشته باشید. از پوشیدن کفش راحت استفاده کنید. ویتامین‌های دوران بارداری را مصرف کنید.', '2026-08-05 13:52:19', '2026-08-05 13:52:19'),
(10, 10, 'اندازه یک کامکوات یا توت‌فرنگی', 3.10, 4.00, 'شروع دوره جنین (Fetus Period). تمام اندام‌های اصلی تشکیل شده‌اند و فقط رشد می‌کنند. ناخن‌های انگشتان دست شروع به رشد می‌کنند. پلک‌ها تشکیل شده و در حال بسته شدن هستند. بند ناف به خوبی کار می‌کند. بیضه‌ها در پسران شروع به تولید تستوسترون می‌کنند. صورت کامل‌تر شده است.', 'افزایش وزن، درخشندگی پوست (به دلیل هورمون‌ها)، آکنه، کمردرد خفیف، تکرر ادرار، افزایش انرژی در برخی افراد، واریس', 'رژیم غذایی غنی از کلسیم و آهن داشته باشید. ورزش‌های سبک مانند پیاده‌روی انجام دهید. از مصرف غذاهای نپخته و لبنیات غیرپاستوریزه پرهیز کنید. برای کمردرد از کمپرس گرم استفاده کنید.', '2026-08-05 13:52:19', '2026-08-05 13:52:19'),
(11, 11, 'اندازه یک جوانه بروکسل یا انجیر', 4.10, 7.00, 'صورت در حال پهن‌تر شدن است. گوش‌ها پایین‌تر و به سمت موقعیت نهایی خود حرکت می‌کنند. غشاء بین انگشتان دست و پا از بین رفته و انگشتان از هم جدا می‌شوند. اندام تناسلی خارجی شروع به رشد و شکل‌گیری می‌کند (اما هنوز تشخیص جنسیت با سونوگرافی دشوار است). جوانه‌های چشایی روی زبان در حال شکل‌گیری هستند. نوزاد می‌تواند قورت دهد و آروغ بزند. روده‌ها در حال حرکت به داخل حفره شکمی هستند.', 'تهوع کمتر می‌شود و اشتها افزایش می‌یابد. تکرر ادرار ادامه دارد. یبوست و نفخ. سوزش سر دل. افزایش خفیف وزن. درخشندگی و چربی پوست. خط تیره (Linea Nigra) ممکن است شروع به نمایان شدن کند. احساس بهتر و انرژی بیشتر نسبت به هفته‌های قبل.', 'با افزایش اشتها، به تغذیه سالم توجه بیشتری کنید. مصرف میوه و سبزیجات را افزایش دهید. برای کاهش یبوست، فیبر و آب بیشتر مصرف کنید. از بلند کردن اجسام سنگین خودداری کنید. شروع به استفاده از کرم‌های ضد ترک (Stretch Marks) کنید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(12, 12, 'اندازه یک لیمو یا آلو', 5.40, 14.00, 'ناخن‌های انگشتان دست رشد کرده و به نوک انگشتان رسیده‌اند. کلیه‌ها به خوبی کار می‌کنند و ادرار تولید و دفع می‌کنند. روده‌ها کاملاً به داخل شکم منتقل شده‌اند. رفلکس مکیدن شروع شده است. نوزاد می‌تواند دهان خود را باز و بسته کند. مغز در حال رشد سریع است. تارهای صوتی در حال شکل‌گیری هستند. ضربان قلب را می‌توان با داپلر شنید. جفت نقش کامل خود را در تغذیه جنین ایفا می‌کند.', 'خستگی همچنان وجود دارد اما کمتر از هفته‌های قبل است. سردرد. سرگیجه خفیف. نفخ و گاز. نمایان شدن شکم (برآمدگی خفیف). افزایش وزن محسوس. خط تیره شکم (Linea Nigra) پررنگ‌تر می‌شود. ممکن است برای اولین بار حرکات خفیف جنین را حس کنید (بالپر زدن).', 'در این هفته معمولاً اولین سونوگرافی غربالگری (NT Scan) انجام می‌شود. برای کاهش سرگیجه، به آرامی از جای خود بلند شوید. از ایستادن طولانی مدت خودداری کنید. از کفش راحت استفاده کنید. مصرف مایعات کافی (حداقل ۸ لیوان آب در روز) را فراموش نکنید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(13, 13, 'اندازه یک غلاف نخود فرنگی یا هلو', 7.40, 23.00, 'تمام اندام‌های اصلی تشکیل شده‌اند و به رشد و بلوغ خود ادامه می‌دهند. استخوان‌ها سفت‌تر و محکم‌تر می‌شوند. اثر انگشت روی نوک انگشتان در حال شکل‌گیری است. روده‌ها شروع به انجام حرکات انقباضی (پریستالسیس) می‌کنند. پانکراس شروع به تولید انسولین می‌کند. کیسه صفرا در حال تولید صفرا است. موهای نرم (لانوگو) شروع به رشد روی بدن می‌کنند. سر در مقایسه با بدن بزرگ‌تر است.', 'سرگیجه. نفخ. افزایش انرژی نسبت به سه‌ماهه اول. نوسانات خلقی. افزایش اشتها. نمایان شدن بیشتر شکم. یبوست ممکن است ادامه یابد. ممکن است دچار گرفتگی عضلات پا شوید.', 'سه‌ماهه اول به پایان رسیده و خطر سقط کاهش یافته است. زمان مناسبی برای شروع ورزش‌های دوران بارداری مانند پیاده‌روی، شنا و یوگا است. از کفش‌های مناسب و پاشنه‌دار استفاده نکنید. مصرف کلسیم و منیزیم را برای جلوگیری از گرفتگی عضلات افزایش دهید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(14, 14, 'اندازه یک لیمو یا گلابی کوچک', 8.70, 43.00, 'گردن مشخص‌تر شده و چانه از سینه جدا شده است. اندام تحتانی (پاها) رشد بیشتری کرده‌اند. شنوایی شروع به رشد کرده و نوزاد می‌تواند صداهای بلند را بشنود. چشم‌ها کامل شده‌اند اما پلک‌ها بسته هستند. ابروها در حال رشد هستند. کلیه‌ها ادرار تولید کرده و به مایع آمنیوتیک دفع می‌کنند. نوزاد می‌تواند انگشت شست خود را بمکد. موهای نرم (لانوگو) تمام بدن را پوشانده است.', 'خط تیره روی شکم (Linea Nigra) واضح‌تر می‌شود. افزایش اشتها. احتقان بینی و خونریزی خفیف بینی (به دلیل افزایش جریان خون). سوزش سر دل. یبوست. افزایش وزن. احساس حرکت جنین (در برخی مادران). ترشحات واژینال بیشتر می‌شود.', 'برای خونریزی بینی، بینی خود را با آب نمک شستشو دهید و از کمپرس سرد استفاده کنید. برای سوزش سر دل، وعده‌های غذایی کوچک و مکرر مصرف کنید و بعد از غذا دراز نکشید. مصرف فیبر را افزایش دهید. از مصرف دخانیات و الکل خودداری کنید.', '2026-08-05 13:52:20', '2026-08-06 10:55:35'),
(15, 15, 'اندازه یک سیب یا پرتقال', 10.10, 70.00, 'نوزاد بسیار فعال شده و مدام در حال حرکت است (لگد زدن، غلت زدن و حرکات آکروباتیک). نوزاد می‌تواند صداهای خارجی مانند صدای شما، ضربان قلب و صداهای معده را بشنود. پوست نازک و شفاف است و رگ‌های خونی از زیر پوست دیده می‌شود. ابروها و مژه‌ها در حال رشد هستند. مفاصل اندام‌ها کامل شده و می‌توانند حرکت کنند. سوراخ‌های بینی باز شده‌اند. موهای سر شروع به رشد می‌کنند.', 'بی‌خوابی. سرگیجه. درد رباط گرد (کشیدگی در ناحیه کشاله ران). یبوست. سوزش سر دل. افزایش انرژی. احساس حرکت جنین (در مادران با تجربه). احتقان بینی. خونریزی لثه. واریس خفیف.', 'برای بی‌خوابی، اتاق خواب را خنک و تاریک نگه دارید و از مصرف کافئین قبل از خواب خودداری کنید. ورزش منظم انجام دهید اما زیاده‌روی نکنید. از نشستن یا ایستادن طولانی مدت خودداری کنید. برای تقویت عضلات کف لگن، تمرینات کگل را شروع کنید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(16, 16, 'اندازه یک آووکادو یا سیب بزرگ', 10.80, 85.00, 'چشم‌ها می‌توانند حرکت کنند (اگرچه پلک‌ها هنوز بسته هستند). نوزاد می‌تواند بشنود و به صداها واکنش نشان دهد. حرکات هماهنگ‌تر شده و نوزاد می‌تواند شست خود را بمکد، قورت دهد و حتی سکسکه کند. استخوان‌ها سخت‌تر می‌شوند. ماهیچه‌ها قوی‌تر شده‌اند. سیستم گردش خون و ادرار به خوبی کار می‌کنند. در پسران، بیضه‌ها شروع به حرکت به سمت کیسه بیضه می‌کنند.', 'شکم به طور واضح نمایان شده است (بامپ بارداری). افزایش انرژی. سوزش سر دل. یبوست. تکرر ادرار. تنگی نفس خفیف. افزایش اشتها. حرکات جنین قوی‌تر و قابل تشخیص‌تر (احساس بالپر زدن). ممکن است اولین حرکات را این هفته یا هفته بعد حس کنید.', 'زمان مناسب برای انجام آزمایش‌های غربالگری سه‌ماهه دوم (آلفا-فتوپروتئین - AFP) است. مصرف پروتئین و کلسیم را افزایش دهید. از مصرف الکل و سیگار خودداری کنید. در صورت مشاهده هرگونه خونریزی یا درد شدید، فوراً به پزشک مراجعه کنید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(17, 17, 'اندازه یک گلابی یا سیب‌زمینی شیرین', 12.00, 140.00, 'پوشش چربی مانند (ورنیکس - Vernix Caseosa) شروع به پوشاندن پوست می‌کند تا از پوست در برابر مایع آمنیوتیک محافظت کند. نوزاد می‌تواند شست خود را بمکد، قورت دهد و حرکات تنفسی تمرینی انجام دهد. چربی زیر پوست شروع به تشکیل می‌شود. مغز در حال توسعه سریع و ایجاد اتصالات عصبی جدید است. قلب با قدرت بیشتر خون پمپاژ می‌کند. اثر انگشت کامل شده است.', 'افزایش وزن (حدود ۲.۵ تا ۴ کیلوگرم از ابتدای بارداری). احساس حرکت جنین (بالپر زدن) قوی‌تر و منظم‌تر می‌شود. تورم خفیف دست و پا. کمردرد. یبوست. سوزش سر دل. تغییرات پوستی (درخشندگی یا آکنه). واریس. گرفتگی عضلات پا.', 'برای جلوگیری از کمردرد، هنگام نشستن از بالشتک کمری استفاده کنید و هنگام بلند کردن اجسام، زانوها را خم کنید. از کفش‌های راحت و بدون پاشنه استفاده کنید. مصرف آهن و ویتامین C را برای جذب بهتر آهن ادامه دهید. از مصرف کافئین خودداری کنید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(18, 18, 'اندازه یک سیب‌زمینی شیرین یا انبه', 14.00, 190.00, 'نوزاد می‌تواند صداهای داخلی و خارجی را بشنود. ابروها و مژه‌ها به وضوح قابل مشاهده هستند. سیستم گوارش به خوبی کار می‌کند و مکونیوم (مدفوع اولیه) در روده جمع می‌شود. عروق خونی از زیر پوست نازک قابل مشاهده هستند. استخوان‌های گوش میانی (برای شنوایی) شروع به استخوانی شدن می‌کنند. روکش پنیری (ورنیکس) ضخیم‌تر می‌شود. نوزاد می‌تواند دست‌های خود را باز و بسته کند.', 'دردهای عضلانی و کمر. افزایش اشتها. تغییر اندازه سینه‌ها (بزرگ‌تر و سنگین‌تر). یبوست. سوزش سر دل. تنگی نفس خفیف. تورم مچ پا و پا. احساس حرکات واضح جنین. افزایش ترشحات واژینال. خط تیره شکم (Linea Nigra) مشخص‌تر.', 'برای کاهش درد کمر، از کمپرس گرم استفاده کنید و به پهلو بخوابید. از ایستادن طولانی مدت خودداری کنید. جوراب‌های واریس می‌توانند به کاهش تورم کمک کنند. مصرف مایعات کافی (حداقل ۸-۱۰ لیوان آب) را فراموش نکنید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(19, 19, 'اندازه یک موز یا انبه', 15.00, 240.00, 'موهای نرم (لانوگو) تمام بدن را پوشانده است. روده‌ها شروع به ساختن مکونیوم (مدفوع اولیه سیاه و قیری) می‌کنند. مغز در حال ایجاد میلیون‌ها سلول عصبی جدید است. کلیه‌ها به طور کامل کار می‌کنند. غدد عرق شروع به رشد می‌کنند. بافت چربی (چربی قهوه‌ای) برای تنظیم دمای بدن پس از تولد شروع به تشکیل می‌شود. پوست هنوز چروکیده و نازک است.', 'درد رباط گرد (کشیدگی در ناحیه کشاله ران و پایین شکم). تپش قلب (به دلیل افزایش حجم خون). احساس حرکت بیشتر و قوی‌تر جنین. افزایش وزن. تنگی نفس. کمردرد. یبوست. ترشحات واژینال بیشتر. ممکن است دچار بواسیر (هموروئید) شوید.', 'برای کاهش درد رباط گرد، حرکات ناگهانی انجام ندهید و به آرامی حرکت کنید. از کمپرس گرم برای درد استفاده کنید. برای پیشگیری از بواسیر، فیبر و مایعات کافی مصرف کنید. از نشستن طولانی مدت خودداری کنید. تمرینات کگل را ادامه دهید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(20, 20, 'اندازه یک انار یا گریپ‌فروت', 16.00, 300.00, 'نصف راه بارداری را پشت سر گذاشته‌اید! مغز و اعصاب به رشد و توسعه خود ادامه می‌دهند. نوزاد می‌تواند قورت دهد و مایع آمنیوتیک را می‌بلعد. اندام‌های تناسلی خارجی به اندازه‌ای رشد کرده‌اند که با سونوگرافی قابل تشخیص هستند. پلک‌ها هنوز بسته هستند. نوزاد می‌تواند حرکات هماهنگ‌تری انجام دهد. روکش پنیری (ورنیکس) ضخیم‌تر شده است. ریه‌ها در حال تولید سورفکتانت (ماده لازم برای تنفس) هستند.', 'احساس حرکات قوی و منظم جنین (شکم در حال لگد زدن). افزایش وزن (حدود ۳.۵ تا ۵ کیلوگرم از ابتدای بارداری). نمایان شدن واضح شکم. تورم پا و مچ پا. کمردرد. تنگی نفس. سوزش سر دل. یبوست. بواسیر. ترشحات واژینال. گرفتگی عضلات پا.', 'سونوگرافی آناتومی (Anomaly Scan) معمولاً در این هفته انجام می‌شود تا سلامت و رشد اعضای بدن جنین بررسی شود. می‌توانید جنسیت نوزاد را بپرسید. ورزش منظم (پیاده‌روی، شنا) را ادامه دهید. از مصرف غذاهای فرآوری شده و قندهای ساده خودداری کنید. مصرف پروتئین و آهن را افزایش دهید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(21, 21, 'اندازه یک هویج بزرگ یا انار بزرگ', 26.00, 360.00, 'نوزاد بسیار فعال است و مرتباً وضعیت خود را تغییر می‌دهد (لگد زدن، چرخش و غلت زدن). موهای نرم (لانوگو) تمام بدن را پوشانده است تا از پوست محافظت کند. مغز استخوان شروع به تولید سلول‌های خونی می‌کند. ابروها و مژه‌ها کامل شده‌اند. روده‌ها شروع به جذب مواد مغذی می‌کنند. پانکراس در حال تولید انسولین است. استخوان‌ها سخت‌تر شده‌اند. تارهای صوتی کامل شده‌اند. نوزاد می‌تواند مایع آمنیوتیک را قورت دهد و بچشد.', 'حرکات جنین قوی‌تر و منظم‌تر می‌شود (شکم شما در حال لگد زدن!). تورم خفیف مچ پا و پا. کمردرد. سوزش سر دل. یبوست. ترشحات واژینال بیشتر. افزایش وزن محسوس. تنگی نفس خفیف. احتقان بینی. ممکن است دچار کشیدگی رباط گرد شوید.', 'برای کاهش کمردرد، از بالشتک کمری استفاده کنید و به پهلو بخوابید. ورزش‌های سبک مانند پیاده‌روی و یوگای بارداری را ادامه دهید. از ایستادن طولانی مدت خودداری کنید. جوراب‌های واریس می‌توانند به کاهش تورم کمک کنند. مصرف آب کافی را فراموش نکنید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(22, 22, 'اندازه یک کدو سبز یا گریپ‌فروت بزرگ', 27.00, 430.00, 'ابروها و مژه‌ها کامل شده و قابل مشاهده هستند. مغز استخوان به تولید سلول‌های خونی (گلبول‌های قرمز و سفید) ادامه می‌دهد. پوست هنوز چروکیده است (زیرا چربی زیر پوست کافی نیست). آثاری از موهای سر قابل مشاهده است. لب‌ها و کام به طور کامل رشد کرده‌اند. دندان‌ها در زیر لثه شکل گرفته‌اند. نوزاد به طور منظم حرکات تنفسی تمرینی انجام می‌دهد (تنفس مایع آمنیوتیک). حس لامسه در حال رشد است و نوزاد می‌تواند صورت و بند ناف خود را لمس کند.', 'حرکات جنین منظم‌تر و قابل پیش‌بینی‌تر شده است. افزایش وزن. کمردرد. تنگی نفس (به دلیل فشار رحم به دیافراگم). تورم پا و مچ پا. سوزش سر دل. یبوست. ترشحات واژینال. ممکن است دچار بواسیر (هموروئید) شوید. برخی مادران دچار انقباضات براکستون هیکس (تمرینی) می‌شوند.', 'برای بواسیر، فیبر و مایعات کافی مصرف کنید و از زور زدن در توالت خودداری کنید. از کمپرس سرد یا گرم برای کاهش ناراحتی استفاده کنید. تمرینات کگل را برای تقویت عضلات کف لگن ادامه دهید. از مصرف غذاهای فرآوری شده خودداری کنید. کفش راحت بپوشید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(23, 23, 'اندازه یک بادمجان یا گریپ‌فروت بزرگ', 28.00, 500.00, 'بیشتر زمان خواب جنین در مرحله REM (حرکت سریع چشم) می‌گذرد که نشاندهنده فعالیت مغزی است. اثر انگشت در حال شکل‌گیری کامل است. چربی زیر پوست در حال افزایش است اما پوست هنوز شل و چروکیده است. ریه‌ها در حال تولید سورفکتانت (ماده لازم برای تنفس) هستند. گوش داخلی (تعادل) کامل شده است. نوزاد می‌تواند به صداهای بلند واکنش نشان دهد و ممکن است با لگد زدن پاسخ دهد. سیستم ایمنی در حال توسعه است.', 'افزایش اشتها. کمردرد. تورم پا و مچ پا. تنگی نفس. انقباضات براکستون هیکس (تمرینی) ممکن است بیشتر شوند. سوزش سر دل. یبوست. بواسیر. گرفتگی عضلات پا. واریس. خط تیره شکم (Linea Nigra) تیره‌تر شده است. ممکن است پوست شکم دچار خارش شود.', 'برای خارش پوست، از کرم‌های مرطوب‌کننده و روغن‌های طبیعی (مانند روغن نارگیل یا روغن بادام) استفاده کنید. از حمام آب داغ خودداری کنید. مصرف امگا ۳ (ماهی سالمون، گردو) را افزایش دهید. ورزش‌های کششی ملایم انجام دهید. به پشت نخوابید (بهتر است به پهلو بخوابید).', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(24, 24, 'اندازه یک ذرت یا طالبی کوچک', 30.00, 600.00, 'کیسه‌های هوایی در ریه‌ها شروع به تشکیل می‌کنند و سورفکتانت بیشتری تولید می‌شود. نوزاد می‌تواند در پاسخ به صداهای بلند حرکت کند یا ضربان قلبش افزایش یابد. پوست هنوز شفاف و چروکیده است. چربی قهوه‌ای (برای تنظیم دمای بدن) شروع به تشکیل می‌کند. مغز به سرعت در حال رشد و توسعه اتصالات عصبی است. حس تعادل کامل شده است. نوزاد می‌تواند به نور واکنش نشان دهد (اگر نور به شکم بتابد).', 'انقباضات براکستون هیکس (تمرینی) بیشتر و منظم‌تر می‌شوند. تورم اندام‌ها (دست، پا و مچ پا). افزایش وزن. کمردرد. تنگی نفس. سوزش سر دل. یبوست. گرفتگی عضلات پا. مشکلات خواب. ممکن است دچار کم‌خونی (آنمی) شوید.', 'آزمایش قند خون (دیابت بارداری) معمولاً بین هفته ۲۴ تا ۲۸ انجام می‌شود. از مصرف قندهای ساده و کربوهیدرات‌های تصفیه‌شده خودداری کنید. برای بهبود خواب، از بالش بارداری استفاده کنید. مصرف آهن و ویتامین C را ادامه دهید. اگر انقباضات همراه با درد یا خونریزی بودند، فوراً به پزشک مراجعه کنید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(25, 25, 'اندازه یک کدو حلوایی یا طالبی', 32.00, 660.00, 'مغز به سرعت در حال رشد است و میلیون‌ها اتصال عصبی جدید ایجاد می‌شود. سیستم عصبی می‌تواند برخی عملکردهای بدن مانند تنفس و ضربان قلب را کنترل کند. چربی زیر پوست در حال افزایش است و پوست کمتر چروکیده می‌شود. ریه‌ها در حال تولید سورفکتانت هستند. نوزاد می‌تواند دست‌های خود را مشت کند و باز کند. عروق خونی در ریه‌ها در حال رشد هستند. موهای سر ضخیم‌تر می‌شوند.', 'تنگی نفس (به دلیل فشار رحم به دیافراگم). کمردرد. تکرر ادرار. افزایش وزن. انقباضات براکستون هیکس. سوزش سر دل. یبوست. بواسیر. واریس. مشکل در خواب. ممکن است دچار کمردرد شدیدتر شوید.', 'برای کاهش تنگی نفس، صاف بنشینید و از بالش برای حمایت استفاده کنید. تمرینات تنفس عمیق انجام دهید. مصرف کلسیم (شیر، ماست، پنیر) را افزایش دهید. از پوشیدن لباس‌های تنگ خودداری کنید. حرکات جنین را بشمارید (حداقل ۱۰ حرکت در ۲ ساعت طبیعی است).', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(26, 26, 'اندازه یک کلم یا طالبی بزرگ', 33.00, 760.00, 'پلک‌ها باز می‌شوند و نوزاد می‌تواند پلک بزند. چشم‌ها به نور واکنش نشان می‌دهند. ریه‌ها ماده سورفکتانت بیشتری تولید می‌کنند. مغز به رشد سریع خود ادامه می‌دهد. چربی زیر پوست در حال افزایش است. نوزاد شروع به تشخیص صداهای آشنا (مانند صدای شما و همسرتان) می‌کند. سیستم ایمنی در حال تکامل است. نوزاد می‌تواند حرکت کند، لگد بزند و وضعیت خود را تغییر دهد.', 'افزایش وزن سریع. کمردرد. تنگی نفس. تکرر ادرار. انقباضات براکستون هیکس. سوزش سر دل. یبوست. بواسیر. گرفتگی عضلات پا. مشکلات خواب. تورم دست و پا. ممکن است دچار خارش پوست شکم شوید.', 'برای کاهش گرفتگی عضلات پا، عضلات ساق پا را کشش دهید و از کمپرس گرم استفاده کنید. مصرف منیزیم و پتاسیم (موز، اسفناج) را افزایش دهید. از ایستادن طولانی مدت خودداری کنید. جوراب‌های فشاری (واریس) بپوشید. حرکات جنین را به دقت زیر نظر داشته باشید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(27, 27, 'اندازه یک بادمجان بزرگ یا کدو سبز', 34.00, 870.00, 'نوزاد می‌تواند به صداهای آشنا (مثل صدای شما) پاسخ دهد و ممکن است با حرکت واکنش نشان دهد. چربی بیشتری برای گرم نگه داشتن نوزاد ذخیره می‌شود. مغز به سرعت در حال رشد است. ریه‌ها به تولید سورفکتانت ادامه می‌دهند. نوزاد می‌تواند شست خود را بمکد. سیستم عصبی در حال بلوغ است. حس بویایی در حال توسعه است. نوزاد می‌تواند بچشد و به طعم‌های مختلف (از طریق مایع آمنیوتیک) واکنش نشان دهد.', 'انقباضات براکستون هیکس مکررتر و شدیدتر می‌شوند. بی‌خوابی. یبوست. سوزش سر دل. تنگی نفس. کمردرد. تکرر ادرار. تورم دست و پا. واریس. بواسیر. افزایش وزن. ممکن است دچار کم‌خونی شوید.', 'برای بی‌خوابی، از تکنیک‌های آرام‌سازی مانند مدیتیشن و تنفس عمیق استفاده کنید. اتاق خواب را خنک و تاریک نگه دارید. از مصرف کافئین در بعد از ظهر خودداری کنید. مصرف آهن و اسید فولیک را ادامه دهید. حرکات جنین را بشمارید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(28, 28, 'اندازه یک بادمجان یا کلم بزرگ', 36.00, 1000.00, 'وارد سه‌ماهه سوم بارداری شده‌اید! ریه‌ها ممکن است به اندازه کافی برای تنفس هوا رشد کرده باشند (اگرچه هنوز نابالغ هستند). پلک‌ها باز می‌شوند و نوزاد می‌تواند پلک بزند و به نور واکنش نشان دهد. چربی زیر پوست افزایش یافته و پوست کمتر چروکیده می‌شود. مغز در حال ایجاد میلیون‌ها سلول عصبی جدید است. نوزاد می‌تواند رویا ببیند (فعالیت REM). سیستم ایمنی در حال تکامل است. استخوان‌ها کامل‌تر شده‌اند اما هنوز نرم هستند.', 'تنگی نفس (شدیدتر). تکرر ادرار (بیشتر). کمردرد شدید. انقباضات براکستون هیکس منظم‌تر. تورم پا، مچ پا و دست. خستگی. بی‌خوابی. سوزش سر دل. یبوست. بواسیر. خط تیره شکم (Linea Nigra) بسیار پررنگ. ممکن است دچار خارش شدید پوست شوید.', 'آزمایش قند خون (دیابت بارداری) معمولاً در این هفته انجام می‌شود. از این هفته به بعد، باید هر ۲ هفته یک بار به پزشک مراجعه کنید. شروع به آماده‌سازی وسایل نوزاد کنید. مصرف غذاهای غنی از آهن (گوشت قرمز، اسفناج) را افزایش دهید. از نشستن یا ایستادن طولانی مدت خودداری کنید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(29, 29, 'اندازه یک کدو تنبل کوچک یا خربزه', 37.00, 1100.00, 'مغز و سیستم عصبی کامل‌تر می‌شوند. نوزاد شروع به تمرین تنفس با تنفس مایع آمنیوتیک می‌کند (حرکات تنفسی منظم). چربی زیر پوست افزایش یافته و پوست پرتر و کمتر چروکیده می‌شود. نوزاد می‌تواند به صداها واکنش واضح‌تری نشان دهد. سیستم گوارش کامل شده است. نوزاد روزانه مقدار زیادی مایع آمنیوتیک می‌بلعد و دفع می‌کند. حس لامسه بسیار توسعه یافته است.', 'کاهش انرژی. انقباضات براکستون هیکس (تمرینی). تنگی نفس. تکرر ادرار. کمردرد شدید. سوزش سر دل. یبوست. بواسیر. واریس. تورم دست و پا. خارش پوست. ممکن است دچار بی‌خوابی شدید شوید. برخی مادران دچار مشکل در تمرکز می‌شوند.', 'از این هفته به بعد، حرکات جنین را به دقت شمارش کنید (حداقل ۱۰ حرکت در ۲ ساعت). برای بهبود گردش خون، پاهای خود را بالا قرار دهید. مصرف مایعات کافی (حداقل ۱۰ لیوان آب) را فراموش نکنید. مصرف پروتئین و کلسیم را افزایش دهید. اگر خونریزی یا درد شدید داشتید، فوراً به پزشک مراجعه کنید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(30, 30, 'اندازه یک کلم یا خربزه بزرگ', 38.00, 1300.00, 'نوزاد می‌تواند کشش دهد، لگد بزند و حرکات گرفتن انجام دهد. چشم‌ها می‌توانند باز و بسته شوند و به نور واکنش نشان دهند. چربی زیر پوست به طور قابل توجهی افزایش یافته است. مغز به سرعت در حال رشد و توسعه است. ریه‌ها به تولید سورفکتانت ادامه می‌دهند. نوزاد می‌تواند بین شب و روز تمایز قائل شود. سیستم ایمنی در حال تکامل است. نوزاد شروع به تشخیص صداهای آشنا می‌کند.', 'تنگی نفس شدیدتر. تورم دست و پا. کمردرد شدید. تکرر ادرار. مشکلات خواب. سوزش سر دل. یبوست. بواسیر. انقباضات براکستون هیکس بیشتر. افزایش وزن سریع. خارش پوست. ممکن است دچار خستگی مفرط شوید. برخی مادران دچار درد لگن و فشار در ناحیه زیر شکم می‌شوند.', 'از این هفته به بعد، باید هر ۲ هفته یک بار به پزشک مراجعه کنید. شروع به تهیه برنامه زایمان کنید. برای کاهش تورم، پاهای خود را بالاتر از قلب قرار دهید. از مصرف نمک و غذاهای شور خودداری کنید. مصرف آب کافی داشته باشید. تمرینات کگل را برای تقویت عضلات کف لگن ادامه دهید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(31, 31, 'اندازه یک آناناس یا کدو تنبل کوچک', 39.00, 1500.00, 'رشد سریع و افزایش وزن ادامه دارد. مغز استخوان به تولید گلبول‌های قرمز ادامه می‌دهد. اندام‌های اصلی (ریه‌ها، کبد، کلیه‌ها) بالغ‌تر می‌شوند. چربی زیر پوست افزایش یافته و پوست پرتر می‌شود. نوزاد می‌تواند سر خود را بچرخاند و حرکت کند. ریه‌ها سورفکتانت بیشتری تولید می‌کنند. نوزاد می‌تواند بین صداهای مختلف تمایز قائل شود. سیستم ایمنی در حال تکامل است. نوزاد روزانه حدود ۵۰۰ میلی‌لیتر مایع آمنیوتیک می‌بلعد و دفع می‌کند.', 'افزایش وزن سریع (حدود ۰.۵ کیلوگرم در هفته). تنگی نفس شدیدتر. تکرر ادرار (فشار رحم به مثانه). کمردرد شدید. مشکلات خواب (بی‌خوابی). سوزش سر دل. یبوست. بواسیر. تورم دست، پا و مچ پا. خارش پوست. انقباضات براکستون هیکس منظم‌تر. درد رباط گرد. ممکن است دچار فشار خون بالا شوید.', 'از این هفته به بعد، مصرف مایعات کافی (حداقل ۱۰-۱۲ لیوان آب) را فراموش نکنید. برای کاهش تنگی نفس، صاف بنشینید و از بالش برای حمایت استفاده کنید. از پوشیدن لباس‌های تنگ خودداری کنید. فشار خون خود را به طور منظم اندازه‌گیری کنید. اگر سردرد شدید، تاری دید یا تورم ناگهانی داشتید، فوراً به پزشک مراجعه کنید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(32, 32, 'اندازه یک کدو تنبل یا آناناس بزرگ', 40.00, 1700.00, 'موهای نرم (لانوگو) شروع به ناپدید شدن می‌کنند. استخوان‌ها کاملاً رشد کرده اما هنوز نرم و انعطاف‌پذیر هستند (برای عبور از کانال زایمان). چربی زیر پوست به طور قابل توجهی افزایش یافته است. ریه‌ها در حال تولید سورفکتانت بیشتری هستند. نوزاد می‌تواند حرکات تنفسی منظمی انجام دهد. مغز به رشد سریع خود ادامه می‌دهد. سیستم عصبی کامل‌تر شده است. نوزاد می‌تواند چشم‌های خود را باز و بسته کند. اثر انگشت کامل شده است.', 'کمردرد شدیدتر. انقباضات براکستون هیکس مکرر و منظم‌تر. تنگی نفس. تکرر ادرار. تورم دست، پا و مچ پا. سوزش سر دل. یبوست. بواسیر. گرفتگی عضلات پا. مشکلات خواب. خستگی. ممکن است دچار کم‌خونی (آنمی) شوید. برخی مادران دچار فشار در ناحیه لگن می‌شوند.', 'از این هفته به بعد، باید هر ۲ هفته یک بار به پزشک مراجعه کنید. برای کاهش کمردرد، از کمپرس گرم و ماساژ استفاده کنید. تمرینات کگل را برای تقویت عضلات کف لگن ادامه دهید. مصرف آهن و اسید فولیک را افزایش دهید. از ایستادن طولانی مدت خودداری کنید. حرکات جنین را به دقت شمارش کنید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(33, 33, 'اندازه یک آناناس یا خربزه بزرگ', 42.00, 1900.00, 'نوزاد می‌تواند پلک بزند و به نور واکنش نشان دهد. مغز و ریه‌ها همچنان در حال رشد و بلوغ هستند. چربی زیر پوست افزایش یافته و پوست صورتی‌تر و کمتر چروکیده می‌شود. استخوان‌ها سخت‌تر می‌شوند اما جمجمه نرم باقی می‌ماند. نوزاد می‌تواند شست خود را بمکد و حرکات هماهنگ‌تری انجام دهد. سیستم ایمنی در حال تکامل است. نوزاد روزانه مقدار زیادی ادرار تولید و دفع می‌کند. الگوهای خواب و بیداری منظم‌تر می‌شود.', 'خستگی شدید. تاری دید (به دلیل تغییرات هورمونی و فشار خون). فشار بیشتر روی شکم و لگن. تنگی نفس. تکرر ادرار. کمردرد شدید. انقباضات براکستون هیکس. تورم دست و پا. سوزش سر دل. یبوست. بواسیر. ممکن است دچار بی‌خوابی شدید شوید. برخی مادران دچار تپش قلب می‌شوند.', 'برای تاری دید، فوراً به پزشک مراجعه کنید (می‌تواند نشانه پره‌اکلامپسی باشد). فشار خون خود را مرتباً اندازه‌گیری کنید. استراحت کافی داشته باشید و به پهلو بخوابید. مصرف مایعات کافی را ادامه دهید. از مصرف نمک و غذاهای فرآوری شده خودداری کنید. کیف بیمارستان را آماده کنید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(34, 34, 'اندازه یک کدو تنبل بزرگ یا خربزه', 43.00, 2100.00, 'استخوان‌ها کاملاً رشد کرده اما نرم و انعطاف‌پذیر هستند. بدن شروع به ذخیره آهن، کلسیم و فسفر برای استفاده پس از تولد می‌کند. چربی زیر پوست به طور قابل توجهی افزایش یافته است. ریه‌ها به تولید سورفکتانت ادامه می‌دهند و تقریباً بالغ شده‌اند. مغز در حال توسعه مهارت‌های شناختی است. نوزاد می‌تواند به صداهای آشنا واکنش نشان دهد و ممکن است به موسیقی پاسخ دهد. سیستم ایمنی در حال تکامل است. نوزاد حرکات هماهنگ‌تری دارد.', 'تنگی نفس شدیدتر (فشار بیشتر به دیافراگم). تکرر ادرار (مثانه تحت فشار). تورم اندام‌ها (دست، پا، مچ پا و صورت). کمردرد شدید. انقباضات براکستون هیکس منظم‌تر. سوزش سر دل. یبوست. بواسیر. گرفتگی عضلات پا. خارش پوست (به دلیل کشیدگی پوست). افزایش وزن سریع. ممکن است دچار خستگی مفرط شوید.', 'از این هفته به بعد، باید هر هفته یک بار به پزشک مراجعه کنید. برای کاهش تورم، پاهای خود را بالا قرار دهید و از جوراب‌های فشاری استفاده کنید. مصرف پروتئین و کلسیم را افزایش دهید. از نشستن یا ایستادن طولانی مدت خودداری کنید. فشار خون خود را به طور منظم اندازه‌گیری کنید. اگر درد شدید یا خونریزی داشتید، فوراً به اورژانس مراجعه کنید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(35, 35, 'اندازه یک خربزه یا هندوانه کوچک', 44.00, 2300.00, 'نوزاد به افزایش وزن ادامه می‌دهد (حدود ۲۰۰-۲۵۰ گرم در هفته). پوست کمتر چروکیده و صورتی‌تر می‌شود. الگوهای خواب مشخص‌تر می‌شوند (نوزاد دوره‌های خواب و بیداری منظمی دارد). ریه‌ها تقریباً بالغ شده‌اند و سورفکتانت کافی تولید می‌کنند. مغز به رشد سریع خود ادامه می‌دهد. کلیه‌ها کامل شده‌اند و ادرار بیشتری تولید می‌کنند. نوزاد می‌تواند حرکات تنفسی منظم و قوی انجام دهد. سیستم گوارش آماده پذیرش شیر است.', 'خستگی شدید. انقباضات براکستون هیکس بیشتر و شدیدتر (ممکن است شبیه به زایمان شوند). کمردرد شدید. تنگی نفس. تکرر ادرار. تورم دست، پا و مچ پا. سوزش سر دل (شدیدتر). یبوست. بواسیر. مشکلات خواب. اضطراب و نوسانات خلقی. ممکن است دچار فشار خون بالا شوید.', 'از این هفته به بعد، هر هفته به پزشک مراجعه کنید. انقباضات خود را زیر نظر داشته باشید (اگر منظم و هر ۵-۱۰ دقیقه بودند، به بیمارستان مراجعه کنید). مصرف غذاهای مغذی و پرانرژی را افزایش دهید. استراحت کافی داشته باشید و از انجام کارهای سنگین خودداری کنید. کیف بیمارستان را کاملاً آماده کنید. تمرینات تنفسی برای زایمان را تمرین کنید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(36, 36, 'اندازه یک هندوانه کوچک یا طالبی بزرگ', 45.00, 2500.00, 'سر نوزاد برای تولد به سمت پایین حرکت می‌کند (موقعیت سفالیک) و در لگن مادر قرار می‌گیرد. ریه‌ها، مغز و سیستم عصبی به رشد ادامه می‌دهند. چربی زیر پوست افزایش یافته و پوست پرتر و صورتی‌تر می‌شود. استخوان‌ها کامل شده‌اند اما جمجمه نرم باقی می‌ماند. نوزاد می‌تواند حرکات مکیدن و بلع را به خوبی انجام دهد. سیستم ایمنی در حال تکامل است. نوزاد روزانه ادرار زیادی تولید و دفع می‌کند. روده‌ها پر از مکونیوم (مدفوع اولیه) هستند.', 'تنگی نفس (فشار رحم به دیافراگم). تکرر ادرار (فشار به مثانه). کمردرد شدید. تورم دست، پا و مچ پا. انقباضات براکستون هیکس منظم و گاهی دردناک. فشار در ناحیه لگن. سوزش سر دل. یبوست. بواسیر. مشکلات خواب. خستگی. اضطراب افزایش می‌یابد. ممکن است دچار بی‌اختیاری خفیف ادرار شوید (به دلیل فشار به مثانه).', 'از این هفته به بعد، هر هفته به پزشک مراجعه کنید. آزمایش استرپتوکوک گروه B (GBS) در این هفته انجام می‌شود. برای کاهش فشار لگن، از توپ زایمان استفاده کنید. تمرینات تنفس عمیق و آرام‌سازی را تمرین کنید. اگر کیسه آب پاره شد (ترشح مایع)، فوراً به بیمارستان مراجعه کنید. برنامه رسیدن به بیمارستان را آماده کنید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(37, 37, 'اندازه یک هندوانه یا کدو تنبل بزرگ', 46.00, 2800.00, 'نوزاد در حال تمرین تنفس با تنفس مایع آمنیوتیک است. سیستم گردش خون کامل شده است. چربی زیر پوست افزایش یافته و پوست صورتی و پر شده است. ریه‌ها تقریباً کاملاً بالغ شده‌اند. مغز و سیستم عصبی به رشد خود ادامه می‌دهند. نوزاد می‌تواند به خوبی شست خود را بمکد. موهای سر در حال رشد هستند. استخوان‌ها کامل شده‌اند اما جمجمه نرم باقی می‌ماند (برای عبور از کانال زایمان). نوزاد کمتر حرکت می‌کند (به دلیل کمبود فضا) اما حرکات قوی‌تر هستند.', 'افزایش انقباضات براکستون هیکس (تمرینی) که ممکن است با انقباضات زایمان اشتباه شوند. خستگی شدید. مشکل در خواب. تنگی نفس (کمی کمتر شده زیرا نوزاد به سمت پایین حرکت کرده است). تکرر ادرار بیشتر (فشار به مثانه). کمردرد شدید. تورم دست، پا و مچ پا. سوزش سر دل. یبوست. بواسیر. اضطراب و نوسانات خلقی. ترشحات واژینال بیشتر (ممکن است توده مخاطی دفع شود).', 'نوزاد در این هفته کامل (ترم) محسوب می‌شود و زایمان در هر زمانی ممکن است شروع شود. کیف بیمارستان را همراه داشته باشید. علائم زایمان را بشناسید (انقباضات منظم، پاره شدن کیسه آب، خونریزی). برنامه تماس با پزشک را آماده کنید. برای کاهش اضطراب، تکنیک‌های آرام‌سازی و تنفس را تمرین کنید. مصرف غذاهای سبک و پرانرژی را ادامه دهید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(38, 38, 'اندازه یک هندوانه یا کدو تنبل', 47.00, 3000.00, 'لانوگو (موهای نرم) تقریباً از بین رفته است (به جز روی بازوها و شانه‌ها). ناخن‌های دست ممکن است از نوک انگشتان بلندتر باشند. چربی زیر پوست به حداکثر رسیده است. ریه‌ها کاملاً بالغ شده‌اند و سورفکتانت کافی دارند. مغز و سیستم عصبی کامل شده‌اند. نوزاد می‌تواند حرکات هماهنگ‌تری انجام دهد. سیستم ایمنی در حال تکامل است. نوزاد برای تولد آماده است. سر نوزاد در لگن ثابت شده است.', 'فشار در ناحیه لگن و زیر شکم. انقباضات براکستون هیکس منظم و گاهی دردناک. کمردرد شدید. تکرر ادرار (فشار زیاد به مثانه). تورم دست، پا و مچ پا. سوزش سر دل. یبوست. بواسیر. بی‌خوابی. خستگی شدید. ترشحات واژینال بیشتر (دفع توده مخاطی). ممکن است دچار اسهال خفیف شوید (نشانه نزدیک شدن زایمان). نوسانات خلقی شدید.', 'هر هفته به پزشک مراجعه کنید. در هر زمانی ممکن است زایمان شروع شود. علائم زایمان را به دقت زیر نظر داشته باشید (انقباضات منظم هر ۵-۱۰ دقیقه، پاره شدن کیسه آب، خونریزی). برنامه رفتن به بیمارستان را نهایی کنید. مصرف غذاهای سبک و زود هضم را ادامه دهید. استراحت کافی داشته باشید. از انجام فعالیت‌های سنگین خودداری کنید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(39, 39, 'اندازه یک هندوانه بزرگ', 48.00, 3200.00, 'نوزاد همچنان به افزایش وزن ادامه می‌دهد (حدود ۲۰۰ گرم در هفته). موهای سر درشت‌تر و ضخیم‌تر می‌شوند. چربی زیر پوست به حداکثر رسیده است. ریه‌ها کاملاً بالغ شده‌اند. مغز و سیستم عصبی به تکامل خود ادامه می‌دهند. نوزاد می‌تواند به صداهای آشنا واکنش نشان دهد. سیستم ایمنی کامل شده است. نوزاد برای تولد کاملاً آماده است. سر در لگن ثابت شده و حرکت کمتری دارد.', 'ترشحات واژینال (توده مخاطی) که ممکن است صورتی یا خونی باشد (نشانه نزدیک شدن زایمان). انقباضات منظم (براکستون هیکس به زایمان تبدیل می‌شود). کمردرد شدید. فشار در ناحیه لگن. تکرر ادرار بسیار زیاد. تورم دست و پا. سوزش سر دل. یبوست. بی‌خوابی. خستگی شدید. اضطراب و هیجان. ممکن است دچار کاهش اشتها شوید.', 'در هر لحظه منتظر شروع زایمان باشید! کیسه آب ممکن است پاره شود (مایع شفاف یا زرد رنگ). انقباضات منظم هر ۵-۱۰ دقیقه به مدت ۱ ساعت نشانه زایمان است. فوراً با پزشک تماس بگیرید و به بیمارستان بروید. به بدن خود گوش دهید و به غرایز خود اعتماد کنید. تمرینات تنفس و آرام‌سازی را ادامه دهید. از حمام آب گرم برای کاهش درد استفاده کنید.', '2026-08-05 13:52:20', '2026-08-05 13:52:20'),
(40, 40, 'اندازه یک هندوانه بزرگ', 50.00, 3400.00, 'همه اندام‌ها بالغ هستند و به رشد خود ادامه می‌دهند. نوزاد برای تولد کاملاً آماده است. وزن نوزاد بین ۳۰۰۰ تا ۳۶۰۰ گرم متغیر است. چربی زیر پوست به حداکثر رسیده است. ریه‌ها کاملاً بالغ شده‌اند. مغز و سیستم عصبی کامل شده‌اند. نوزاد می‌تواند به خوبی بمکد و قورت دهد. سیستم ایمنی کامل است. نوزاد در موقعیت سفالیک (سر پایین) قرار دارد و آماده تولد است. ممکن است نوزاد کمی دیرتر از موعد به دنیا بیاید (تا هفته ۴۲ طبیعی است).', 'آمادگی کامل برای زایمان. انقباضات منظم و دردناک (زایمان). پاره شدن کیسه آب (ترشح مایع). خونریزی خفیف (نشانه شروع زایمان). کمردرد شدید. فشار زیاد در ناحیه لگن. تکرر ادرار بسیار زیاد. تورم دست و پا. سوزش سر دل. بی‌خوابی. خستگی. اضطراب و هیجان شدید. ممکن است دچار اسهال یا حالت تهوع شوید (نشانه نزدیک شدن زایمان).', 'ممکن است نوزاد امروز یا چند روز آینده به دنیا بیاید. در صورت مشاهده هر یک از علائم زیر، فوراً به بیمارستان مراجعه کنید: ۱- انقباضات منظم هر ۵-۱۰ دقیقه به مدت ۱ ساعت ۲- پاره شدن کیسه آب (ترشح مایع) ۳- خونریزی شدید واژینال ۴- کاهش شدید حرکات جنین. کیف بیمارستان را همراه داشته باشید. برنامه رسیدن به بیمارستان را اجرا کنید. آرام باشید و به بدن خود اعتماد کنید. تبریک می‌گوییم! به زودی نوزاد خود را در آغوش خواهید گرفت.', '2026-08-05 13:52:20', '2026-08-05 13:52:20');

