CREATE TABLE `support_messages` (
  `id` int(11) NOT NULL,
  `full_name` varchar(100) DEFAULT NULL COMMENT 'نام و نام خانوادگی (اختیاری)',
  `email` varchar(150) DEFAULT NULL COMMENT 'ایمیل (اختیاری - حداقل یکی از ایمیل/تلفن الزامیه)',
  `phone_number` varchar(20) DEFAULT NULL COMMENT 'شماره تلفن (اختیاری - حداقل یکی از ایمیل/تلفن الزامیه)',
  `message_type` enum('bug','question','suggestion') NOT NULL DEFAULT 'question' COMMENT 'نوع پیام',
  `message` text NOT NULL COMMENT 'متن پیام',
  `status` enum('pending','in_progress','resolved') NOT NULL DEFAULT 'pending' COMMENT 'وضعیت پیگیری',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

