INSERT INTO `testimonials` (`id`, `full_name`, `role_or_context`, `content`, `rating`, `is_active`, `display_order`, `created_at`) VALUES
(1, 'سارا احمدی', 'ماه چهارم بارداری', 'سایت خیلی عالی هست هر سوالی که داشته باشم رو به راحتی از بخش چت باکس میپرسم و استرسم کمتر شده ', 5, 0, 1, '2026-09-06 18:55:59'),
(2, 'سارا احمدی', 'ماه چهارم بارداری', 'سایت خیلی عالی هست هر سوالی که داشتم رو به راحتی توی بخش هفته‌های بارداری پیدا کردم. توضیحات ساده و قابل فهم بود.', 5, 1, 1, '2026-09-06 18:55:59'),
(3, 'نیلوفر رضایی', 'مادر یک کودک ۸ ماهه', 'بخش مراحل تکاملی کودک خیلی کمکم کرد بفهمم پسرم توی مسیر درستی هست یا نه. واقعاً ازش راضی‌ام.', 5, 1, 2, '2026-09-05 14:40:22'),
(4, 'مریم کریمی', 'ماه هفتم بارداری', 'اطلاعات هر هفته دقیق و به‌روز بود. فقط دوست داشتم بخش تغذیه هم کامل‌تر باشه.', 4, 1, 3, '2026-09-03 06:11:07'),
(5, 'فاطمه حسینی', 'مادر دوقلوهای ۳ ماهه', 'استاندارد رشد و وزن رو با پزشک بچه‌هام هم چک کردم، دقیقاً همخوانی داشت. خیالم راحت شد.', 5, 1, 4, '2026-08-30 10:33:45'),
(6, 'الهام موسوی', 'ماه دوم بارداری', 'تازه بارداریم رو فهمیدم و این سایت اولین منبعی بود که استفاده کردم. رابط کاربری ساده و آرومی داره.', 4, 1, 5, '2026-08-27 07:52:10'),
(7, 'زهرا نوری', 'مادر یک نوزاد یک ماهه', 'هشدارهای رشدی که تو بخش مراحل تکاملی نوشته شده خیلی به‌دردم خورد، زودتر متوجه یه مشکل کوچیک شدم و به پزشک مراجعه کردم.', 5, 1, 6, '2026-08-20 16:45:33'),
(8, 'پریسا صادقی', 'ماه نهم بارداری', 'نزدیک زایمانم هست و این سایت باعث شد کمتر استرس داشته باشم چون هر هفته می‌دونم چه اتفاقی داره میفته.', 5, 1, 7, '2026-08-15 05:20:19'),
(9, 'طاهره یوسفی', 'مادر یک کودک ۱۸ ماهه', 'محتوا خوبه ولی جدول رشد فقط تا ۱۲ ماهگی رو پوشش می‌داد، امیدوارم بازه‌ش رو گسترش بدید.', 3, 1, 8, '2026-08-10 13:07:52');

