INSERT INTO `vaccination_schedule` (`id`, `vaccine_name`, `description`, `dose_number`, `age_in_months`, `age_min_months`, `age_max_months`, `precautions`, `created_at`, `updated_at`) VALUES
(1, 'ب.ث.ژ (BCG)', 'واکسن سل، یک نوبت در بدو تولد یا تا ۶ هفتگی تزریق می‌شود. مقدار واکسن در کودکان زیر یک سال معادل نصف دوز بالغین است [citation:2].', 1, 0, 0, 2, '⚠️ در صورت تب بالا یا نقص ایمنی شدید، با پزشک مشورت کنید. از تزریق در محل زخم خودداری شود.', '2026-08-06 09:55:15', '2026-08-06 09:55:15'),
(2, 'هپاتیت ب (Hepatitis B) - دوز اول', 'واکسن هپاتیت ب، دوز اول در بدو تولد تزریق می‌شود. نوزادان نارس با وزن کمتر از ۲۰۰۰ گرم در ۴ نوبت دریافت می‌کنند [citation:2].', 1, 0, 0, 1, '⚠️ در نوزادان نارس با وزن کمتر از ۲۰۰۰ گرم، برنامه متفاوت است (۴ نوبت: بدو تولد، یک ماهگی، دو ماهگی و ۶ ماهگی).', '2026-08-06 09:55:15', '2026-08-06 09:55:15'),
(3, 'سه‌گانه-فلج اطفال-هپاتیت ب (Pentavalent) - دوز اول', 'واکسن پنج‌گانه (سه‌گانه + فلج اطفال + هپاتیت ب) - دوز اول در ۲ ماهگی تزریق می‌شود [citation:2].', 1, 2, 2, 3, '⚠️ اگر کودک تب یا بیماری حاد دارد، واکسیناسیون را به تعویق بیندازید.', '2026-08-06 09:55:15', '2026-08-06 09:55:15'),
(4, 'سه‌گانه-فلج اطفال (DTwP+OPV) - دوز دوم', 'واکسن سه‌گانه و قطره خوراکی فلج اطفال - دوز دوم در ۴ ماهگی [citation:2].', 2, 4, 4, 5, '⚠️ در صورت تشنج یا بیماری عصبی پیشرونده، با پزشک مشورت کنید.', '2026-08-06 09:55:15', '2026-08-06 09:55:15'),
(5, 'سه‌گانه-فلج اطفال-هپاتیت ب (Pentavalent) - دوز سوم', 'واکسن پنج‌گانه - دوز سوم در ۶ ماهگی [citation:2].', 3, 6, 6, 7, '⚠️ مانند دوزهای قبلی', '2026-08-06 09:55:15', '2026-08-06 09:55:15'),
(6, 'MMR (سرخک-سرخجه-اوریون) - دوز اول', 'واکسن سه‌گانه سرخک، سرخجه و اوریون، دوز اول در ۱۲ ماهگی تزریق می‌شود [citation:2][citation:6].', 1, 12, 11, 15, '⚠️ در صورت حساسیت به تخم‌مرغ یا ژلاتین، با پزشک مشورت کنید. ممکن است ۵-۱۲ روز پس از واکسن تب خفیف و بثورات ایجاد شود.', '2026-08-06 09:55:15', '2026-08-06 09:55:15'),
(7, 'سه‌گانه-فلج اطفال (DTwP+OPV) - دوز یادآور', 'دوز یادآور واکسن سه‌گانه و قطره فلج اطفال در ۱۸ ماهگی [citation:2].', 4, 18, 17, 20, '⚠️ مانند نوبت‌های قبلی', '2026-08-06 09:55:15', '2026-08-06 09:55:15'),
(8, 'MMR (سرخک-سرخجه-اوریون) - دوز دوم', 'دوز دوم واکسن MMR در ۱۸ ماهگی تزریق می‌شود [citation:2][citation:6].', 2, 18, 17, 20, '⚠️ مانند دوز اول', '2026-08-06 09:55:15', '2026-08-06 09:55:15'),
(9, 'سه‌گانه-فلج اطفال (DTwP+OPV) - دوز یادآور مدرسه', 'دوز یادآور واکسن سه‌گانه و قطره فلج اطفال در سن ۴-۶ سالگی (ورود به مدرسه) [citation:2].', 5, 48, 42, 72, '⚠️ قبل از ورود به مدرسه حتماً تزریق شود.', '2026-08-06 09:55:15', '2026-08-06 09:55:15');

